/* LOF-26-RA — every chart of risque.html, drawn with D3 from window.RISK
   (risque_data.js, generated by analyse_risque.py). Analyst terminal style:
   right-hand value axes, crosshairs with axis tags, readouts in the panel header. */
(() => {
  'use strict';
  const R = window.RISK;
  const loc = d3.formatLocale({ decimal: '.', thousands: ',', grouping: [3], currency: ['', ' €'], minus: '−' });
  const F = s => loc.format(s);
  const f0 = F(',.0f'), f1 = F('.1f'), f2 = F('.2f'), fs1 = F('+.1f'), fs0 = F('+.0f'), fs2 = F('+.2f');
  const hm = h => { const m = Math.round(h * 60); return `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')}`; };
  const root = document.querySelector('.viz-root');
  const C = n => getComputedStyle(root).getPropertyValue(n).trim();
  const $ = id => document.getElementById(id);
  const actName = id => (R.rows.find(r => r.id === id) || {}).name || id;
  const rowOf = id => R.rows.find(r => r.id === id);
  const dayLbl = d => `D${d}`;
  const dateLbl = s => { const [, m, d] = s.split('-'); return `${+d}/${m}`; };
  const GL = { 1: 'Easy', 2: 'Moderate', 3: 'Demanding', 4: 'Expert' };
  const gcol = g => C(`--g${g}`);
  // terrain sections inside each outing (risque_sections.js, outils/segmentation_terrain.js)
  const EP = window.RISK_EPISODES || { episodes: [], persist: null };
  const SEC = window.RISK_SECTIONS || { seg_grade: R.series.map(s => rowOf(s.act).grade), sections: [] };
  const segG = i => SEC.seg_grade[i];
  const segKm = i => R.series[i].km - (i ? R.series[i - 1].km : 0);
  const secWhy = x => !x.why ? 'grade of the outing' : x.why.k === 'flat' ? 'flat and runnable, normal pace' : `same trail as “ ${actName(x.why.o)} »`;
  const secOf = i => SEC.sections.find(x => i >= x.i0 && i <= x.i1);
  // D+ of each 250 m piece, rescaled so that each outing sums to its measured D+
  const segDp = (() => {
    const raw = R.series.map((s, i) => i && R.series[i - 1].act === s.act ? Math.max(0, s.alt - R.series[i - 1].alt) : 0);
    const tot = d3.rollup(R.series.map((s, i) => [s.act, raw[i]]), v => d3.sum(v, d => d[1]), d => d[0]);
    return raw.map((v, i) => { const a = R.series[i].act, t = tot.get(a); return t ? v / t * rowOf(a).dplus : 0; });
  })();

  /* ---------- tooltip ---------- */
  const tip = $('tip');
  function showTip(ev, html) {
    tip.innerHTML = html; tip.hidden = false;
    const r = tip.getBoundingClientRect(), pad = 14;
    let x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + r.width > innerWidth - 8) x = ev.clientX - r.width - pad;
    if (y + r.height > innerHeight - 8) y = ev.clientY - r.height - pad;
    tip.style.left = `${Math.max(8, x)}px`; tip.style.top = `${Math.max(8, y)}px`;
  }
  const hideTip = () => { tip.hidden = true; };
  const row = (k, v) => `<div class="r">${k}<em>${v}</em></div>`;
  const hover = (sel, html) => sel.on('pointermove', (ev, d) => showTip(ev, html(d))).on('pointerleave', hideTip);
  const readout = (id, html) => { const e = $(id); if (e) e.innerHTML = html; };

  /* ---------- frame and chrome ---------- */
  function frame(id, m) {
    const el = $(id); el.innerHTML = '';
    const W = Math.max(280, el.clientWidth - 8), H = +el.dataset.h;
    const svg = d3.select(el).append('svg').attr('viewBox', `0 0 ${W} ${H}`).attr('height', H).attr('role', 'img');
    const g = svg.append('g').attr('transform', `translate(${m.l},${m.t})`);
    return { el, svg, g, W, H, m, w: W - m.l - m.r, h: H - m.t - m.b, narrow: W < 560 };
  }
  // value axis on the right, as on a trading screen; left variant for charts with a right margin in use
  const hideUnder = (g, ys, gap = 11) => g.selectAll('.axis .tick').filter(function () { const m = /translate\([^,]+,([^)]+)\)/.exec(this.getAttribute('transform') || ''); return m && ys.some(y => Math.abs(+m[1] - y) < gap); }).select('text').attr('opacity', 0);
  const yGrid = (g, y, w, n = 5, fmt = f0, side = 'right') => {
    g.append('g').attr('class', 'gridl').call(d3.axisLeft(y).ticks(n).tickSize(-w).tickFormat('')).lower();
    if (side === 'right') g.append('g').attr('class', 'axis').attr('transform', `translate(${w},0)`).call(d3.axisRight(y).ticks(n).tickSize(0).tickPadding(8).tickFormat(fmt));
    else g.append('g').attr('class', 'axis').call(d3.axisLeft(y).ticks(n).tickSize(0).tickPadding(8).tickFormat(fmt));
  };
  const xAxis = (g, x, h, n, fmt) => g.append('g').attr('class', 'axis').attr('transform', `translate(0,${h})`)
    .call(d3.axisBottom(x).ticks(n).tickSize(0).tickPadding(9).tickFormat(fmt));
  const axTitle = (g, txt, x, y, anchor = 'start') => g.append('text').attr('class', 'ax-title').attr('x', x).attr('y', y).attr('text-anchor', anchor).text(txt);
  function barPath(x, y0, w, y1, rr = 2) {
    const up = y1 < y0, hgt = Math.abs(y1 - y0); const r = Math.min(rr, hgt, w / 2);
    if (hgt < .5) return '';
    return up
      ? `M${x},${y0}V${y1 + r}Q${x},${y1} ${x + r},${y1}H${x + w - r}Q${x + w},${y1} ${x + w},${y1 + r}V${y0}Z`
      : `M${x},${y0}V${y1 - r}Q${x},${y1} ${x + r},${y1}H${x + w - r}Q${x + w},${y1} ${x + w},${y1 - r}V${y0}Z`;
  }
  const clip = f => { const id = `cl${Math.random().toString(36).slice(2, 8)}`; f.svg.append('defs').append('clipPath').attr('id', id).append('rect').attr('width', f.w).attr('height', f.h); return f.g.append('g').attr('clip-path', `url(#${id})`); };
  const legend = (id, items) => {
    $(id).innerHTML = items.map(([kind, col, txt]) => `<span><i class="${kind}" style="${kind === 'ring' ? `border-color:${col}` : kind === 'dash' ? `border-top-color:${col || 'var(--text-primary)'}` : `background:${col}`}"></i>${txt}</span>`).join('');
  };
  // a value tag on an axis, for crosshairs (filled label like on a trading screen)
  function axTag(g, x, y, txt, anchor = 'start') {
    const t = g.append('g').attr('class', 'axtag').style('pointer-events', 'none');
    const tx = t.append('text').attr('x', x + (anchor === 'start' ? 5 : anchor === 'end' ? -5 : 0)).attr('y', y).attr('dy', '.35em').attr('text-anchor', anchor).text(txt);
    const b = tx.node().getBBox();
    const wd = Math.max(b.width + 8, 46), x0 = anchor === 'middle' ? b.x + b.width / 2 - wd / 2 : anchor === 'end' ? b.x + b.width + 4 - wd : b.x - 4;
    t.insert('rect', 'text').attr('x', x0).attr('y', b.y - 2).attr('width', wd).attr('height', b.height + 4).attr('rx', 3);
    return t;
  }
  function crossH(f) {   // a horizontal + vertical crosshair pair, hidden until used
    const gx = f.g.append('g').style('display', 'none').style('pointer-events', 'none');
    const v = gx.append('line').attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '3 3');
    const h = gx.append('line').attr('x1', 0).attr('x2', f.w).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '3 3');
    let tags = [];
    return {
      show(px, py, yTxt, xTxt) {
        gx.style('display', null); v.attr('x1', px).attr('x2', px);
        if (py == null) h.style('display', 'none'); else h.style('display', null).attr('y1', py).attr('y2', py);
        tags.forEach(t => t.remove()); tags = [];
        if (py != null && yTxt) tags.push(axTag(gx, f.w + 2, py, yTxt));
        if (xTxt) tags.push(axTag(gx, px, f.h + 12, xTxt, 'middle'));
      },
      hide() { gx.style('display', 'none'); },
    };
  }
  // day separators along a km axis, labelled at the top (session breaks)
  function dayBands(g, x, h, top = true) {
    R.day_bounds.forEach((d, i) => {
      if (i) g.append('line').attr('class', 'daysep').attr('x1', x(d.km)).attr('x2', x(d.km)).attr('y1', 0).attr('y2', h);
      const end = i < R.day_bounds.length - 1 ? R.day_bounds[i + 1].km : R.series[R.series.length - 1].km;
      if (top) g.append('text').attr('class', 'lbl').attr('x', (x(d.km) + x(end)) / 2).attr('y', -6).attr('text-anchor', 'middle').text(dayLbl(d.day));
    });
  }

  /* ---------- header: ticker, scope, KPIs ---------- */
  const D = window.RISK_DIST || R.dist, MC = window.RISK_MC, W_ = R.weather;
  // rolling pace and irregularity recomputed without the GPS artefact (outils/distribution.js)
  if (D.roll_sd) { R.series.forEach((s, i) => { s.m = D.roll_m[i]; s.sd = D.roll_sd[i]; }); R.reg_thr = D.roll_p90; R.long_sd = D.roll_mean_sd; }
  // regression and correlation matrix recomputed without the GPS artefact (outils/sensibilites.js)
  const SX = window.RISK_SENS;
  if (SX) { R.sens = SX.sens; R.r2 = SX.r2; R.corr = SX.corr; R.rows.forEach(r => { if (SX.e_mean[r.id] != null) r.e_mean = SX.e_mean[r.id]; }); }
  const N_REG = SX ? SX.n : R.series.length;
  const sens = Object.fromEntries(R.sens.map(s => [s.name, s]));
  const sacS = sens['pack on my back'];
  const mcLate = MC.real_dev[MC.real_dev.length - 1], cL = v => v > 99 ? '> 99' : v < 1 ? '< 1' : f0(v);
  const lateRain = d3.sum(W_.days.filter(d => d.day >= 7), d => d.rain);
  const HRV_USUAL = 45;
  const totKm = d3.sum(R.rows, r => r.km), totDp = d3.sum(R.rows, r => r.dplus);
  $('scope').innerHTML = [['Period', '14–22 June 2026'], ['Distance', `${f1(totKm)} km`], ['Elevation gain', `${f0(totDp)} m`], ['Walking days', '9'], ['Outings', R.rows.length], ['250 m segments', D.n], ['Nights tracked', R.nights.length]]
    .map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('');

  /* ---------- 01 · OHLC candles + D+ ---------- */
  function drawCandles() {
    const days = R.candles;
    // une bougie par sortie (risque_bougies.js, altitudes de tous les points GPS)
    const data = window.RISK_BOUGIES.map(d => ({ ...d }));
    const m = { t: 22, r: 58, b: 26, l: 8 };
    const f = frame('c-candles', m);
    const gap = .7, nd = new Set(data.map(d => d.day)).size, units = data.length + (nd - 1) * gap;
    const step = Math.min(f.w / units, 34), gw = step * units, off = (f.w - gw) / 2;
    let di = -1, prev = null;
    data.forEach((d, i) => { if (d.day !== prev) { di++; prev = d.day; } d.x = off + (i + di * gap + .5) * step; });
    const y = d3.scaleLinear().domain([0, d3.max(data, d => d.h) * 1.12]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${f0(v)} m`);
    const bw = Math.max(4, Math.min(step * .62, 18)), up = d => d.c >= d.o, col = d => up(d) ? C('--up') : C('--down');
    const groups = d3.groups(data, d => d.day);
    const sep = (g, h) => groups.slice(1).forEach(([, a]) => g.append('line').attr('class', 'daysep').attr('x1', a[0].x - step * (.5 + gap / 2)).attr('x2', a[0].x - step * (.5 + gap / 2)).attr('y1', 0).attr('y2', h));
    sep(f.g, f.h);
    groups.forEach(([day, a]) => f.g.append('text').attr('class', 'lbl').attr('x', (a[0].x + a[a.length - 1].x) / 2).attr('y', f.h + 17).attr('text-anchor', 'middle').text(dayLbl(day)));
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', f.h).attr('y2', f.h).attr('stroke', C('--border')).attr('stroke-width', 1);
    const cg = f.g.selectAll('.cd').data(data).join('g').attr('transform', d => `translate(${d.x},0)`);
    cg.append('line').attr('y1', d => y(d.h)).attr('y2', d => y(d.l)).attr('stroke', col).attr('stroke-width', 1).attr('shape-rendering', 'crispEdges');
    cg.append('rect').attr('x', -bw / 2).attr('width', bw)
      .attr('y', d => y(Math.max(d.o, d.c))).attr('height', d => Math.max(1.5, Math.abs(y(d.o) - y(d.c))))
      .attr('fill', col).attr('stroke', col).attr('stroke-width', 1).attr('shape-rendering', 'crispEdges');
    const top = data.reduce((a, b) => b.h > a.h ? b : a);
    const ro = d => `<b>${dayLbl(d.day)}</b> ${d.name}  O <b>${f0(d.o)}</b>  H <b>${f0(d.h)}</b>  B <b>${f0(d.l)}</b>  C <b class="${up(d) ? 'u' : 'd'}">${f0(d.c)}</b>  D+ <b>${f0(d.dplus)}</b>`;
    const def = `${data.length} outings · max alt. <b>${f0(top.h)} m</b> (${top.name}) · total D+ <b>${f0(d3.sum(data, d => d.dplus))} m</b>`;
    readout('r-candles', def);
    const ch = crossH(f);
    const near = mx => data[d3.minIndex(data, d => Math.abs(d.x - mx))];
    const tip = (ev, d) => showTip(ev, `<b>${d.name} · ${dayLbl(d.day)}</b>${row('start', `${f0(d.o)} m`)}${row('high point', `${f0(d.h)} m`)}${row('low point', `${f0(d.l)} m`)}${row('finish', `${f0(d.c)} m`)}${row('distance', `${f1(d.km)} km`)}${row('D+', `${f0(d.dplus)} m`)}${row('pack', d.sac ? 'with' : 'without (trail)')}${row('start at', d.start)}${row('moving', hm(d.mov_h))}`);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => { const [mx, my] = d3.pointer(ev), d = near(mx); ch.show(d.x, my, `${f0(y.invert(my))} m`); readout('r-candles', ro(d)); tip(ev, d); })
      .on('pointerleave', () => { ch.hide(); hideTip(); readout('r-candles', def); });

    const v = frame('c-volume', { t: 6, r: 58, b: 6, l: 8 });
    const yv = d3.scaleLinear().domain([0, d3.max(data, d => d.dplus)]).nice().range([v.h, 0]);
    yGrid(v.g, yv, v.w, 2, v_ => f0(v_));
    sep(v.g, v.h);
    v.g.selectAll('.vb').data(data).join('path').attr('transform', d => `translate(${d.x - bw / 2},0)`)
      .attr('d', d => barPath(0, yv(0), bw, yv(d.dplus), 0)).attr('fill', col).attr('fill-opacity', d => d.sac ? .35 : .8);
    legend('l-candles', [['', C('--up'), 'finish higher'], ['', C('--down'), 'finish lower'], ['', `color-mix(in srgb, ${C('--text-secondary')} 80%, transparent)`, 'D+ without pack (solid) / with pack (light)']]);
    const big = days.reduce((a, b) => b.dplus > a.dplus ? b : a);
    const sansShare = d3.sum(days, d => d.dplus - d.dplus_sac) / d3.sum(days, d => d.dplus);
    {
      // slopes on the 250 m segments (GPS artefact excluded): flat ground no longer dilutes the climbs
      const A = R.series, SG = A.map((g, i) => ({ ...g, len: i && A[i - 1].act === g.act ? g.km - A[i - 1].km : .25 })).filter(g => Math.abs(g.slope) <= 60);
      const len = c => d3.sum(SG.filter(c), g => g.len), up = SG.filter(g => g.slope >= 5);
      const upMean = d3.sum(up, g => g.slope * g.len) / d3.sum(up, g => g.len);
      const stT = len(g => !g.sac && Math.abs(g.slope) >= 15) / len(g => !g.sac), stS = len(g => g.sac && Math.abs(g.slope) >= 15) / len(g => g.sac);
      const top1 = SG.reduce((x, y) => y.slope > x.slope ? y : x), nameOf = id => data.find(d => d.id === id);
      // steepest kilometre: 4 consecutive segments of one outing (about 1 km), climb brought back to 1 km
      const AL = A.map((g, i) => ({ ...g, len: i && A[i - 1].act === g.act ? g.km - A[i - 1].km : .25 })); let bestKm = { d: 0 };
      for (let i = 0; i < AL.length; i++) { let L = 0, dp = 0, j = i, ok = true;
        while (j < AL.length && AL[j].act === AL[i].act && L < .95) { if (Math.abs(AL[j].slope) > 60) { ok = false; break; } L += AL[j].len; dp += Math.max(0, AL[j].slope) * AL[j].len * 10; j++; }
        if (ok && L >= .95 && dp / L > bestKm.d) bestKm = { d: dp / L, act: AL[i].act }; }
      const same = bestKm.act === top1.act;
      $('facts-1').innerHTML = [
        [`${f0(stT * 100)}%`, `of trail on slopes steeper than 15% (${f0(stS * 100)}% with the pack)`],
        [`${f0(upMean * 10)} m`, `of D+ on average per kilometre of climbing`],
        [`${f0(top1.slope)}%`, `on the steepest 250 m (${nameOf(top1.act).name.split(' / ')[0]}, ${dayLbl(top1.day)})`],
      ].map(([v, k]) => `<div><dd><b>${v}</b></dd><dt>${k}</dt></div>`).join(''); }
    $('t-candles').innerHTML = `<b>${f0(sansShare * 100)}%</b> of the D+ climbed without the pack. <b>${dayLbl(big.day)}</b>, the heaviest day (${f0(big.dplus)} m). <b>D8</b>: the camp did not move, hence the flat candle.<br><br>This relief is more than scenery: with or without the pack, on a traverse or a summit, each outing carries a different risk. First step: grade the terrain.`;
  }

  /* ---------- 01 · terrain grading ---------- */
  const isEst = r => /critères/.test(r.src) && !/68north|Horizon|Hunting/.test(r.src);
  const srcL = r => isEst(r) ? 'DNT' : r.src;
  function drawTerrain() {
    const S = R.series, maxKm = S[S.length - 1].km;
    const m = { t: 22, r: 58, b: 30, l: 8 };
    const f = frame('c-terrain', m);
    const x = d3.scaleLinear().domain([0, maxKm]).range([0, f.w]);
    const y = d3.scaleLinear().domain([0, d3.max(S, s => s.alt) * 1.1]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 4, v => `${f0(v)} m`);
    xAxis(f.g, x, f.h, f.narrow ? 4 : 8, v => `${v} km`);
    dayBands(f.g, x, f.h);
    // one area per terrain section (a whole outing, or a flat / already-walked part of it)
    const runs = []; let cur = null;
    S.forEach((s, i) => { const g = segG(i); if (!cur || cur.act !== s.act || cur.g !== g) { if (cur) cur.pts.push(s); cur = { act: s.act, pts: [], g }; runs.push(cur); } cur.pts.push(s); });
    const area = d3.area().x(s => x(s.km)).y0(f.h).y1(s => y(s.alt)).curve(d3.curveMonotoneX);
    const ln = d3.line().x(s => x(s.km)).y(s => y(s.alt)).curve(d3.curveMonotoneX);
    runs.forEach(r => {
      f.g.append('path').attr('d', area(r.pts)).attr('fill', gcol(r.g)).attr('fill-opacity', r.g === 4 ? .85 : .42);
      f.g.append('path').attr('d', ln(r.pts)).attr('fill', 'none').attr('stroke', r.g === 4 ? C('--text-primary') : gcol(r.g)).attr('stroke-width', 1.4);
    });
    const ch = crossH(f);
    const segTot = d3.sum(S, (_, i) => segKm(i));
    const share = g => d3.sum(S, (_, i) => segG(i) >= g ? segKm(i) : 0) / segTot;
    const def = `demanding + expert: <b>${f0(share(3) * 100)}%</b> of the distance · expert: <b>${f0((share(4)) * 100)}%</b>`;
    readout('r-terrain', def);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => {
        const [mx] = d3.pointer(ev); const si = d3.minIndex(S, q => Math.abs(q.km - x.invert(mx))), s = S[si], r = rowOf(s.act), g = segG(si), sec = secOf(si);
        ch.show(x(s.km), y(s.alt), `${f0(s.alt)} m`, `${f1(s.km)} km`);
        readout('r-terrain', `<b>${dayLbl(s.day)}</b> ${r.name} · <b>${GL[g]}</b>${g === r.grade ? ` · ${r.sac_t}` : ` · key passage ${GL[r.grade]}`}`);
        showTip(ev, `<b>${r.name} · ${dayLbl(s.day)}</b>${row('grade here', GL[g])}${sec ? row('section', `${f1(sec.i0 ? S[sec.i0 - 1].km : 0)} → ${f1(S[sec.i1].km)} km`) : ''}${row('why', sec ? secWhy(sec) : 'grade of the outing')}${row('key passage', `${GL[r.grade]} · ${r.sac_t}`)}${row('altitude', `${f0(s.alt)} m`)}${row('segment slope', `${s.slope}%`)}${row('source', srcL(r))}`);
      }).on('pointerleave', () => { ch.hide(); hideTip(); readout('r-terrain', def); });
    legend('l-terrain', [1, 2, 3, 4].map(g => ['', g === 4 ? `${gcol(4)};box-shadow:inset 0 0 0 1px var(--text-muted)` : gcol(g), GL[g]]));

    // distance mix
    const mix = [1, 2, 3, 4].map(g => ({ g, km: d3.sum(S, (_, i) => segG(i) === g ? segKm(i) : 0) / segTot * totKm, n: SEC.sections.filter(x => x.g === g).length, dp: d3.sum(S, (_, i) => segG(i) === g ? segDp[i] : 0) }));
    $('grade-mix').innerHTML = `<div class="gm-bar">${mix.map(d => `<i style="flex:${d.km};background:${gcol(d.g)}${d.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}" title="${GL[d.g]}"></i>`).join('')}</div>
      <div class="gm-rows">${mix.map(d => `<div class="gm-row"><i style="background:${gcol(d.g)}${d.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}"></i><span>${GL[d.g]} <span class="mono">· ${d.n} sections</span></span><span class="mono">${f1(d.km)} km · ${f0(d.dp)} m D+</span><span class="mono"><b>${f0(d.km / totKm * 100)}%</b></span></div>`).join('')}</div>`;
    $('grade-legend').innerHTML = [
      [1, 'T1', 'Easy trail, no steep passage or obstacle.'],
      [2, 'T1–T2', 'Moderate climbs, a few steeper passages.'],
      [3, 'T2–T3', 'Rocky or narrow ground, scree, hands sometimes useful.'],
      [4, 'T3–T4', 'Ridges, bare rock, exposed passages crossed with the hands.'],
    ].map(([g, t, d]) => `<div><span class="chipg l${g}"><i></i>${GL[g]}</span><span class="mono">${t}</span><span>${d}</span></div>`).join('');
    const rows = [...R.rows].sort((a, b) => a.day - b.day || 0);
    const split = r => { const ss = SEC.sections.filter(x => x.act === r.id), k = x => d3.sum(d3.range(x.i0, x.i1 + 1), segKm), tot = d3.sum(ss, k);
      return `<span class="secbar" title="${ss.map(x => `${GL[x.g]} ${f1(k(x) / tot * r.km)} km (${secWhy(x)})`).join(' · ')}">${ss.map(x => `<i style="flex:${k(x)};background:${gcol(x.g)}${x.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}"></i>`).join('')}</span>`; };
    const tableHtml = `<thead><tr><th>Day</th><th>Outing</th><th>Key passage</th><th>SAC</th><th>Breakdown</th><th class="n">km</th><th class="n">D+</th><th class="n">Steep</th><th>Source</th></tr></thead><tbody>${rows.map(r => `<tr><td class="nw mono">${dayLbl(r.day)}</td><td>${r.name}</td><td><span class="chipg l${r.grade}"><i></i>${GL[r.grade]}</span></td><td class="mono">${r.sac_t}</td><td>${split(r)}</td><td class="n">${f1(r.km)}</td><td class="n">${f0(r.dplus)}</td><td class="n">${f0(r.pente_max)}%</td><td class="muted">${srcL(r)}</td></tr>`).join('')}</tbody>`;
    DEFS.cotes = { t: 'Grading of the 25 outings', wide: true, html: () => `<p>The grade is that of the outing’s key passage. The “Breakdown” bar shows the share of each grade in the outing; “DNT” in the Source column marks a grade set with the DNT criteria, for lack of a guide.</p><div class="table-wrap flat"><table class="data">${tableHtml}</table></div>` };
    DEFS.cotation = { t: 'Where the grades come from', html: () => `
      <p><b>The origin.</b> The Norwegian Trekking Association (DNT) grades its trails in four colours, like ski runs: green, blue, red, black. The Swiss Alpine Club (SAC) uses six levels, T1 to T6. Both look at the same things: elevation gain, length, ground and exposure to drops.</p>
      <p><b>The grade of an outing.</b> When a guide covers the route (68north, Horizon Rando, Hunting for Bliss), I use the published grade of the key passage. Otherwise I set it with the DNT criteria and the account of the day: these outings are marked “DNT” in the table.</p>
      <p><b>The breakdown.</b> An outing is not uniform. The grade applies to the whole outing, except for two breaks spotted on the smoothed slope (averaged over 1.25 km):</p>
      <div class="def-ex">A flat stretch longer than 1.5 km (slope &lt; 5%) walked at normal pace becomes <b>easy</b>.<br>A passage longer than 1 km that follows a trail already graded lower on another day takes that grade: same trail, same grade.</div>
      <p class="muted">Limit: a grade remains a judgement. Those I set myself are flagged.</p>` };
    $('cotes-btn').innerHTML = defBtn('cotes', 'Grading of the 25 outings');
    { const pt = $('c-terrain').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('cotation')); }
    const BG = window.RISK_BOUGIES, sansShare = d3.sum(BG.filter(d => !d.sac), d => d.dplus) / d3.sum(BG, d => d.dplus);
    $('t-terrain').innerHTML = `<b>${f0(share(3) * 100)}%</b> of the distance on demanding or expert terrain. Each grade level adds <b>${fs0(sens['terrain (+1 level)'].pct)}%</b> to the time taken.`;
    $('t-terrain-b').innerHTML = `This grading is already a risk analysis in itself: it combines measurable factors (slope, D+, length, exposure) with the judgement of guides who know the ground. The traverse is now split up and graded: risk-taking can be measured, segment by segment.`;
  }

  /* ---------- 02 · distribution ---------- */
  function drawDist() {
    const m = { t: 16, r: 46, b: 34, l: 8 };
    const f = frame('c-hist', m);
    const x = d3.scaleLinear().domain([D.edges[0], D.edges[D.edges.length - 1]]).range([0, f.w]);
    const bins = D.hist.map((n, i) => ({ n, a: D.edges[i], b: D.edges[i + 1] }));
    const y = d3.scaleLinear().domain([0, d3.max([d3.max(D.hist), d3.max(D.pdf_t)]) * 1.1]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 4);
    xAxis(f.g, x, f.h, 8, F('+.1f'));
    axTitle(f.g, 'deviation e (0 = at my pace)', 0, f.h + 30);
    const z = v => Math.abs((v - D.mu) / D.sd) > 2;
    f.g.selectAll('.hb').data(bins).join('path')
      .attr('d', d => barPath(x(d.a) + .5, y(0), Math.max(1, x(d.b) - x(d.a) - 1.5), y(d.n), 1))
      .attr('fill', d => z((d.a + d.b) / 2) ? C('--down') : C('--accent')).attr('fill-opacity', d => z((d.a + d.b) / 2) ? .9 : .45);
    [-2, 2].forEach(k => {
      const xv = x(D.mu + k * D.sd);
      f.g.append('line').attr('x1', xv).attr('x2', xv).attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '2 3');
      f.g.append('text').attr('class', 'lbl tagt').attr('x', xv + 4).attr('y', 10).text(`${k > 0 ? '+' : '−'}2σ`);
    });
    const ln = d3.line().x((d, i) => x(D.xs[i])).y(d => y(d)).curve(d3.curveBasis);
    f.g.append('path').attr('d', ln(D.pdf)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.6).attr('stroke-dasharray', '5 4');
    hover(f.g.selectAll('.hh').data(bins).join('rect').attr('class', 'hit').attr('x', d => x(d.a)).attr('width', d => x(d.b) - x(d.a)).attr('y', 0).attr('height', f.h),
      d => { const mid = (d.a + d.b) / 2, i = d3.minIndex(D.xs, v => Math.abs(v - mid)); return `<b>e between ${f2(d.a)} and ${f2(d.b)}</b>${row('actual / expected time', `×${f2(Math.exp(d.a))} to ×${f2(Math.exp(d.b))}`)}${row('observed segments', d.n)}${row('expected under a normal distribution', f1(D.pdf[i]))}`; });
    legend('l-hist', [['', C('--accent'), 'segments'], ['', C('--down'), 'beyond ±2σ'], ['dash', '', 'normal distribution']]);
    readout('r-hist', `${f0(D.n)} segments · σ <b>${f2(D.sd)}</b>`);

    // ---------- the key numbers, the indicators (in a button), the « ? » buttons ----------
    const SS = R.series, okI = SS.map((q, i) => i).filter(i => Math.abs(SS[i].slope) <= 60);
    const base = Math.round(d3.median(okI, i => EP.seg_t[i] * Math.exp(-SS[i].e) / 60) * 2) / 2;   // typical expected time of a piece
    const mn = v => { const t = Math.round(v * 60); return `${Math.floor(t / 60)} min ${String(t % 60).padStart(2, '0')}`; };
    const lo1 = base * Math.exp(-D.sd), hi1 = base * Math.exp(D.sd);
    const ex3 = (D.extremes || []).map(e => ({ ...e, t: EP.seg_t[e.i] / 60, x: EP.seg_t[e.i] * Math.exp(-SS[e.i].e) / 60 }));
    const NM = { bunes_munkebu: 'the ghost trail', reinebringen_helvete: 'the Reinebringen ridge', stuvla: 'the Støvla rock band', ryten: 'the Ryten descent' };
    const ex3txt = [...ex3].sort((a, b) => b.z - a.z).map(e => e.act === 'stuvla' || e.act === 'ryten' ? `${NM[e.act] || actName(e.act)} (expected ${mn(e.x)}, done in ${mn(e.t)})` : (NM[e.act] || actName(e.act))).join(', ');
    const art = (D.artefacts || [])[0], w = D.edges[1] - D.edges[0];
    const V = { ok: ['c-ok', 'normal'], warn: ['c-sub', 'to watch'], info: ['c-av', 'marker'] };
    const rows = [
      ['Standard deviation σ', 'The width of the bell: how far I usually stray.',
        `<b>${f2(D.sd)}</b>. On a segment expected to take ${mn(base)}, two times out of three I take between ${mn(lo1)} and ${mn(hi1)}.`, 'info'],
      ['Jarque-Bera test', 'Checks whether the bell leans to one side (skewness) and whether its tails are too thick (kurtosis). The larger the score, the less credible the normal distribution; above 6, it is rejected.',
        `<b>${f1(D.jb)}</b> (skewness ${fs2(D.skew)}, kurtosis ${fs2(D.kurt)}), a score a true normal distribution gives ${f0(D.jb_p * 100)} times out of 100 by chance: nothing abnormal.`, D.jb_p > .05 ? 'ok' : 'warn'],
      ['Beyond 3σ', 'The real surprises.',
        `<b>${D.n3} segments</b>: ${ex3txt}. A normal distribution expects ${f1(D.exp3)}: a slight excess, which chance would produce ${f0(D.p_pois3 * 100)} times out of 100.`, 'warn'],
      ['With or without the pack', 'The width σ, measured separately with and without the pack.',
        `On a segment expected to take ${mn(base)}: with the pack, between ${mn(base * Math.exp(-D.sd_avec))} and ${mn(base * Math.exp(D.sd_avec))}; on trail, between ${mn(base * Math.exp(-D.sd_sans))} and ${mn(base * Math.exp(D.sd_sans))}. Without the pack, I push, I run, I stop.`, 'info'],
    ];
    DEFS.indicateurs = { t: 'The indicators, one by one', wide: true, html: () => `
      <div class="table-wrap flat"><table class="data dstats"><thead><tr><th>Indicator</th><th>What it measures</th><th>On my traverse</th><th>Verdict</th></tr></thead><tbody>${rows.map(([a, m, t, k]) => `<tr><td><b>${a}</b></td><td class="muted">${m}</td><td>${t}</td><td><span class="chip ${V[k][0]}">${V[k][1]}</span></td></tr>`).join('')}</tbody></table></div>
      <p class="muted">${f0(D.n)} 250 m segments.${art ? ` One segment removed: ${actName(art.act)}, GPS slope of ${f0(art.slope)}%, wrong altitude.` : ''}</p>` };

    $('dist-key').innerHTML = `
      <p><span class="dk-v">${mn(lo1)} – ${mn(hi1)}</span>Two times out of three, for a segment expected to take ${mn(base)}. Each step is unpredictable.</p>
      <p><span class="dk-v">${D.n3} of ${f0(D.n)}</span>segments beyond 3σ; a normal distribution expects ${f1(D.exp3)}. Big surprises are rare.</p>
      <p>The bell follows the bars: the normal distribution describes my deviations well.</p>`;
    $('dist-btns').innerHTML = defBtn('indicateurs', 'The indicators') + defBtn('student', 'Student’s t-distribution') + defBtn('vraisemblance', 'Maximum likelihood');

    /* boutons « ? » de la partie 02 : d'où viennent les outils et les graphiques, façon cours */
    {
      const mm = D.mode_mu || R.dist.mode_mu;
      const tob = sl => 6 * Math.exp(-3.5 * Math.abs(sl / 100 + .05));
      const eUp = d3.mean(SS.filter(q => q.slope > 15 && q.slope <= 60), q => q.e), eDn = d3.mean(SS.filter(q => q.slope <= -5 && q.slope >= -15), q => q.e);
      const st = SS[539], stT = EP.seg_t[539] / 60, stX = stT * Math.exp(-st.e);
      // small chart of the rule, drawn as a static SVG for the pop-up
      const tobSvg = () => {
        const W = 400, H = 170, m = { t: 8, r: 46, b: 24, l: 20 }, iw = W - m.l - m.r, ih = H - m.t - m.b;
        const x = d3.scaleLinear().domain([-40, 40]).range([0, iw]), y = d3.scaleLinear().domain([0, 7]).range([ih, 0]);
        const xs = d3.range(-40, 40.5, .5), ln = k => d3.line().x(v => x(v)).y(v => y(tob(v) * k))(xs);
        const pts = [];
        [1, 0].forEach(sac => d3.range(-35, 36, 5).forEach(c => {
          const v = SS.map((q, i) => [q, i]).filter(([q]) => q.sac === sac && Math.abs(q.slope) <= 60 && q.slope >= c - 2.5 && q.slope < c + 2.5)
            .map(([q, i]) => (q.km - (i ? SS[i - 1].km : 0)) / (EP.seg_t[i] / 3600)).filter(v => isFinite(v) && v > 0);
          if (v.length >= 5) pts.push({ sac, c, v: d3.median(v) });
        }));
        const grid = [0, 2, 4, 6].map(v => `<line x1="0" x2="${iw}" y1="${y(v)}" y2="${y(v)}" stroke="${C('--grid')}"/><text x="${iw + 6}" y="${y(v) + 4}" class="lbl">${v} km/h</text>`).join('');
        const xt = [-40, -20, 0, 20, 40].map(v => `<text x="${x(v)}" y="${ih + 16}" text-anchor="middle" class="lbl">${v > 0 ? '+' : ''}${v}%</text>`).join('');
        return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block;margin:4px 0 6px"><g transform="translate(${m.l},${m.t})">${grid}${xt}
          <path d="${ln(1)}" fill="none" stroke="${C('--text-primary')}" stroke-width="1.4" stroke-dasharray="4 3"/>
          <path d="${ln(Math.exp(-mm.avec))}" fill="none" stroke="${C('--series-avec')}" stroke-width="1.8"/>
          <path d="${ln(Math.exp(-mm.sans))}" fill="none" stroke="${C('--series-sans')}" stroke-width="1.8" opacity=".8"/>
          ${pts.map(d => `<circle cx="${x(d.c)}" cy="${y(Math.min(7, d.v))}" r="3" fill="${d.sac ? C('--series-avec') : C('--series-sans')}" stroke="${C('--bg')}"/>`).join('')}</g></svg>
          <p class="muted">Dotted: Tobler. Lines: recalibrated Tobler, with the pack (blue) and without (orange). Dots: my actual speed, median by slope class.</p>`;
      };
      DEFS.tobler = { t: 'Where Tobler’s rule comes from', html: () => `
        <p>In 1950, the Swiss cartographer <b>Eduard Imhof</b> published tables of walking speed measured on mountain trails, by slope. In 1993, the geographer <b>Waldo Tobler</b> looked for a simple formula fitting these measurements. He chose an exponential of the slope:</p>
        <p class="def-f">v = 6 · e<sup>−3.5 · |s + 0.05|</sup> km/h, where s is the slope (0.10 for +10%)</p>
        <p>The <b>6</b> is the maximum speed; the <b>+0.05</b> puts that maximum on a gentle descent (−5%); the <b>3.5</b> sets how fast you slow down as the slope moves away from −5%, in either direction. On the flat: <b>5.0 km/h</b>; at +20%: <b>2.5 km/h</b>.</p>
        ${tobSvg()}
        <p><b>The recalibration.</b> Tobler describes an average walker without a load, measured by others more than 70 years ago: it is the only piece of the analysis that does not come from my trek. I take only two numbers from my data, my average pace with and without the pack: <b>${f0((1 - Math.exp(-mm.avec)) * 100)}% slower</b> than Tobler with the pack, roughly his speed without.</p>
        <p class="def-ex"><b>Example.</b> On the Støvla rock band (${st.slope > 0 ? '+' : ''}${f0(st.slope)}%), the expected time was ${mn(stX)}; I took ${mn(stT)}, a deviation e = ${fs2(st.e)}: <b>×${f1(Math.exp(st.e))}</b> the expected time. e = 0: at my pace; +0.4: about 1.5 times slower.</p>
        <p><b>How I walk.</b> Compared with Tobler, I go ${f0((1 - Math.exp(eUp)) * 100)}% faster on climbs steeper than 15%, and ${f0((Math.exp(eDn) - 1) * 100)}% slower on gentle descents, where Tobler assumes you run. These deviations remain surprises: I did not know them before leaving.</p>
        <p class="muted"><b>Robustness test.</b> No control outing: the baseline is a convention. I tried five others (pace fitted on the flat, on easy flat ground, one pace per outing, median, measured day left out). The extremes remain the same passages, and 3 to 6 segments exceed 3σ where the normal distribution expects 1.6. Only the verdict “normal distribution accepted or not” depends on the baseline: it is borderline.</p>` };
      DEFS.student = { t: 'Where Student’s t-distribution comes from', html: () => `
        <p>In 1908, <b>William Gosset</b>, a chemist at the Guinness brewery in Dublin, was checking the quality of barley on <b>small samples</b>. He noticed that when the mean and standard deviation are estimated from few measurements, extreme deviations come up more often than the normal distribution predicts. As Guinness forbade publishing under his own name, he signed <b>“Student”</b>.</p>
        <p><b>The construction.</b> Take a normal variable Z and divide it by a noisy estimate of its standard deviation, built from ν other normal variables (a χ² distribution with ν degrees of freedom):</p>
        <p class="def-f">T = Z / √(χ²<sub>ν</sub> / ν)  →  density ∝ (1 + t²/ν)<sup>−(ν+1)/2</sup></p>
        <p>When the denominator happens to be small, T becomes large: that is what thickens the tails. The larger ν, the more stable the estimate of the standard deviation, and the more T looks like Z. At ν = 1 it is the Cauchy distribution, with extreme tails; as ν goes to infinity, it is exactly the normal distribution.</p>
        <p class="def-ex">Here it is used as a model with three settings: a centre, a width, and ν. Fitted on my ${f0(D.n)} segments, it takes ν ≈ <b>${f0(D.t_df)}</b>: already very close to a normal.</p>
        <p class="muted">In finance it is used for stock returns, whose crashes are more frequent than a normal distribution says.</p>` };
      DEFS.vraisemblance = { t: 'Where the log-likelihood comes from', html: () => `
        <p><b>Ronald Fisher</b>, between 1912 and 1922, turned the question around: instead of asking “what data does this distribution produce?”, he asked “<b>with which settings would this distribution make my data most probable?</b>”.</p>
        <p><b>The likelihood.</b> For given settings θ, the distribution gives a density f(x<sub>i</sub> | θ) to each segment. Treating the segments as independent, the probability of the whole set is the product:</p>
        <p class="def-f">L(θ) = f(x<sub>1</sub> | θ) × f(x<sub>2</sub> | θ) × … × f(x<sub>${f0(D.n)}</sub> | θ)</p>
        <p><b>Why the logarithm.</b> A product of ${f0(D.n)} small numbers becomes tiny and hard to compute. The logarithm turns the product into a sum, without moving the maximum:</p>
        <p class="def-f">ln L(θ) = Σ ln f(x<sub>i</sub> | θ)</p>
        <p>θ is varied until this sum is as large as possible. For the normal distribution, the calculation is exact: the maximum is reached at the mean and standard deviation of the data. For Student’s t there is no formula: the computer searches for the maximum step by step.</p>
        <p class="def-ex"><b>Choosing between two distributions.</b> Adding a setting always raises ln L a little. In 1973, <b>Hirotugu Akaike</b> proposed counting each setting as a penalty: AIC = 2 × (number of settings) − 2 ln L, and the smallest value wins. Here, Student’s t gains <b>+${f1(D.ll_gain)}</b> in ln L for one extra setting, which costs 1: AIC difference ${Math.abs(D.d_aic) < .005 ? '0,00' : F('+.2f')(D.d_aic)}, a tie. The simpler one, the normal, is kept.</p>` };
      DEFS.hist = { t: 'Where the histogram and its curve come from', html: () => `
        <p>The word is <b>Karl Pearson</b>’s, from 1891. The construction takes three steps.</p>
        <p><b>1. The bins.</b> The axis of deviations e is cut into intervals of equal width, here ${f1(w)} (from ${f1(D.edges[0])} to ${f1(D.edges[D.edges.length - 1])}).</p>
        <p><b>2. The count.</b> Each of the ${f0(D.n)} segments is placed in its bin; the height of each bar is the number of segments in the bin.</p>
        <p><b>3. The comparison curve.</b> The mean (${F('+.3f')(D.mu)}) and standard deviation (${f2(D.sd)}) of the deviations are computed, and the normal distribution with these two values is drawn. To put it on the same scale as the bars, its density is multiplied by the number of segments and by the width of a bin: ${f0(D.n)} × ${f1(w)}. The curve then gives the number of segments a normal distribution would put in each bin.</p>
        <p class="def-ex">The red bars are the bins beyond ±2σ, i.e. ±${f2(2 * D.sd)} in e. ${f0(D.n)} segments of 250 m${art ? `; one segment removed: ${actName(art.act)}, GPS slope of ${f0(art.slope)}%, wrong altitude` : ''}.</p>` };
      const add = (el, k) => el && !el.querySelector('.def-btn') && el.insertAdjacentHTML('beforeend', defBtn(k));
      add($('lede-dist'), 'tobler');
      add($('c-hist').closest('.pc').querySelector('.pc-t'), 'hist');
    }
  }

  /* ---------- 03 · tail table ---------- */
  function drawTail() {
    const T = D.tail, SS = R.series, LBL = { bunes_munkebu: 'ghost trail', reinebringen_helvete: 'ridge, fog', stuvla: 'rock band', ryten: 'descent', volandstinden: 'descent', munkebu_reine: 'road to Reine' };
    // neighbouring pieces of the same outing form one passage (the Ryten descent is one descent, not four)
    const passages = list => {
      const P = []; [...list].sort((a, b) => a.i - b.i).forEach(t => { const last = P[P.length - 1];
        if (last && last.act === t.act && t.i - last.i1 <= 2) { last.i1 = t.i; last.items.push(t); } else P.push({ act: t.act, day: t.day, sac: t.sac, i0: t.i, i1: t.i, items: [t] }); });
      return P.map(p => { const ii = p.items.map(t => t.i), real = d3.sum(ii, i => EP.seg_t[i]), exp = d3.sum(ii, i => EP.seg_t[i] * Math.exp(-SS[i].e));
        const zz = p.items.reduce((b, t) => Math.abs(t.z) > Math.abs(b.z) ? t : b, p.items[0]);
        return { ...p, n: ii.length, km0: (p.i0 ? SS[p.i0 - 1].km : 0), km1: SS[p.i1].km, z: zz.z, mult: real / exp, grade: d3.max(p.items, t => t.grade), slope: d3.mean(p.items, t => t.slope) }; })
        .sort((a, b) => Math.abs(b.z) - Math.abs(a.z));
    };
    const PS = passages(T.slow), PF = passages(T.fast), slow = PS.slice(0, 3), fast = PF.slice(0, 3);
    const rowT = (t, k) => `<tr><td class="n">${k + 1}</td><td class="nw"><span class="dot" style="background:${t.sac ? C('--series-avec') : C('--series-sans')}" title="${t.sac ? 'with the pack' : 'trail'}"></span>${actName(t.act).replace(/\s*\(.*\)$/, '')}<div class="muted">km ${t.n > 1 ? `${f1(t.km0)}–${f1(t.km1)}` : f1(t.km1)}${LBL[t.act] ? ` · ${LBL[t.act]}` : ''}</div></td><td class="mono">${dayLbl(t.day)}</td>
      <td><span class="chipg l${t.grade}"><i></i>${GL[t.grade]}</span></td><td class="n">${t.slope > 0 ? '+' : ''}${f0(t.slope)}%</td><td class="n">×${f1(t.mult)}</td>
      <td class="n">${fs2(t.z)}</td></tr>`;
    const head = '<colgroup><col style="width:5%"><col style="width:38%"><col style="width:7%"><col style="width:20%"><col style="width:10%"><col style="width:9%"><col style="width:11%"></colgroup><thead><tr><th class="n">#</th><th>Passage</th><th>Day</th><th>Grade</th><th class="n">Slope</th><th class="n">Time</th><th class="n">z</th></tr></thead>';
    $('tail-table').innerHTML = head + `<tbody>${slow.map(rowT).join('')}</tbody>`;
    $('tail-fast').innerHTML = head + `<tbody>${fast.map(rowT).join('')}</tbody>`;
    readout('r-tail', `${T.slow.length} segments beyond +2σ`); readout('r-tail-f', `${T.fast.length} segments beyond −2σ`);
    $('n-tail-meth').textContent = `The ${f0(D.n)} segments, sorted by z = (e − mean) / σ, with σ = ${f2(D.sd)}. Neighbouring segments of the same outing form a passage; z is that of the worst segment. Three passages on each side.`;
    const rep = d3.rollups([...T.slow, ...T.fast], v => v.length, t => t.act).filter(([, n]) => n >= 3).sort((a, b) => b[1] - a[1]);
    $('t-tail').innerHTML = `Slow: the passages of the account, on demanding or expert terrain. Fast: descents run on trail, and the flat road to Reine.<br><br>Rare (${T.slow.length + T.fast.length} of ${f0(D.n)}), these extremes nevertheless come back to the same places: <b>${d3.sum(rep, r => r[1])} of ${T.slow.length + T.fast.length}</b> in ${rep.length} passages, from the Reinebringen ridge to the Ryten descent. Deviations come in whole passages.`;
  }

  /* ---------- 04 · bands + rolling irregularity (shared crosshair) ---------- */
  const nearest = km => R.series[d3.minIndex(R.series, s => Math.abs(s.km - km))];
  function drawRoll() {
    const S = R.series, maxKm = S[S.length - 1].km, S2 = S.filter(s => s.sd != null);
    const EPS = EP.episodes.filter(d => d.sign < 0 || Math.round(d.lost_min) >= 5), pc = v => Math.exp(v) - 1, fpc = v => `${v >= 0 ? '+' : '−'}${f0(Math.abs(pc(v)) * 100)}%`;
    const epAt = i => MAJ.find(x => i >= x.i0 && i <= x.i1);
    const slow = EPS.filter(d => d.sign > 0).sort((a, b) => b.lost_min - a.lost_min);
    const MAJ = slow.filter(d => Math.round(d.lost_min) >= 10), PAU = slow.filter(d => Math.round(d.lost_min) < 10);
    const m = { t: 10, r: 62, b: 30, l: 8 };
    const f = frame('c-bands', m);
    const x = d3.scaleLinear().domain([0, maxKm]).range([0, f.w]);
    const y = d3.scaleLinear().domain([-.8, 1]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, fpc);
    dayBands(f.g, x, f.h);
    const cg = clip(f);
    const x0 = i => x(i ? S[i - 1].km : 0);
    // episodes as shaded bands behind the curves
    cg.selectAll('.ep').data(MAJ).join('rect').attr('x', d => x0(d.i0)).attr('width', d => Math.max(1.5, x(S[d.i1].km) - x0(d.i0))).attr('y', 0).attr('height', f.h)
      .attr('fill', C('--down')).attr('opacity', .2);
    xAxis(f.g, x, f.h, f.narrow ? 4 : 8, v => `${v} km`);
    cg.append('line').attr('class', 'zero').attr('x1', 0).attr('x2', f.w).attr('y1', y(0)).attr('y2', y(0));
    const cl = v => Math.max(-.8, Math.min(1, v));
    d3.groups(S2, s => s.day).forEach(([, v]) => cg.append('path').attr('d', d3.line().x(s => x(s.km)).y(s => y(cl(s.m))).curve(d3.curveMonotoneX)(v)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 1.8));
    const def = `${slow.length} slow episodes · <b>${f0(d3.sum(slow, d => d.lost_min))} min</b> lost over ${f0(d3.sum(slow, d => d.len))} km`;
    readout('r-roll', def);
    const c1 = crossH(f);
    const move = (ev, xs) => {
      const s = nearest(xs.invert(d3.pointer(ev)[0])), i = S.indexOf(s), ep = epAt(i);
      c1.show(x(s.km), y(cl(s.m == null ? s.e : s.m)), s.m == null ? '' : fpc(s.m), `${f1(s.km)} km`);
      readout('r-roll', `<b>${dayLbl(s.day)}</b> ${actName(s.act)} · segment <b>${fpc(s.e)}</b> · 2 km <b>${s.m == null ? '–' : fpc(s.m)}</b>${ep ? ` · episode <b>${ep.lost_min > 0 ? '+' : '−'}${f0(Math.abs(ep.lost_min))} min</b>` : ''}`);
      if (ep) showTip(ev, `<b>${actName(ep.act)} · ${dayLbl(ep.day)}</b>${row('episode', `km ${f1(ep.km0)} → ${f1(ep.km1)}`)}${row(ep.sign > 0 ? 'slower' : 'faster', `${f0(Math.abs(ep.pct))}%`)}${row(ep.sign > 0 ? 'time lost' : 'time gained', `${f0(Math.abs(ep.lost_min))} min`)}${ep.gps ? row('attention', 'doubtful GPS slope') : ''}`); else hideTip();
    };
    const leave = () => { c1.hide(); hideTip(); readout('r-roll', def); };
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h).on('pointermove', ev => move(ev, x)).on('pointerleave', leave);
    legend('l-roll', [['ln', C('--accent'), '2 km moving average'], ['', C('--down'), 'slow episode of 10 min or more']]);

    // table of the costly slow episodes (>= 10 min), with their causes
    const RS = window.RESSENTIS_EPISODES || {};
    const CAUSE = {
      sentier: ['Faint trail', '--series-sans', 'Terrain endured'],
      terrain_instable: ['Unstable ground', '--critical', 'Terrain endured'],
      meteo: ['Weather', '--series-avec', 'Weather endured'],
      evaluation: ['Assessment', '--accent', 'Stops and decisions'],
      arret: ['Stop', '--text-muted', 'Stops and decisions'],
      pause: ['Other · probable break', '--hair', 'Probable breaks'],
    };
    const chip = (k, main) => `<span class="cause${main ? '' : ' dry'}"><i style="background:${C(CAUSE[k][1])}"></i>${CAUSE[k][0]}</span>`;
    const majMin = d3.sum(MAJ, d => d.lost_min), pauMin = d3.sum(PAU, d => d.lost_min);
    const epTable = `<thead><tr><th class="n">#</th><th>Day</th><th>Outing</th><th class="n">km</th><th class="n">Actual / expected</th><th class="n">Lost</th><th>Grade</th><th>Cause</th></tr></thead><tbody>${MAJ.map((d, k) => {
      const r = rowOf(d.act), rs = RS[d.id];
      return `<tr title="${d.id}"><td class="n">${k + 1}</td><td class="mono">${dayLbl(d.day)}</td><td class="nw"><span class="dot" style="background:${d.sac ? C('--series-avec') : C('--series-sans')}" title="${d.sac ? 'with the pack' : 'trail'}"></span>${r.name}</td>
        <td class="n">${f1(d.km0)}–${f1(d.km1)}<div class="muted">${f1(d.len)} km</div></td><td class="n">${f0(d.real_min)} / ${f0(d.real_min - d.lost_min)} min</td>
        <td class="n"><b>+${f0(d.lost_min)} min</b><span class="zbar" style="width:${Math.round(d.lost_min / MAJ[0].lost_min * 46)}px"></span></td>
        <td><span class="chipg l${d.grade}"><i></i>${GL[d.grade]}</span><div class="muted mono">slope ${d.slope > 0 ? '+' : ''}${f0(d.slope)}%</div></td>
        <td>${rs ? `<div class="causes">${rs.causes.map((c, j) => chip(c, !j)).join('')}${rs.certitude === 'probable' ? '<span class="est">probable</span>' : ''}</div><div class="cause-d">${rs.detail}</div>` : `<div class="causes"><span class="cause sec">not qualified</span></div><div class="cause-d muted">Note on the outing: ${r.note}</div>`}${d.alert.length ? `<div class="causes" style="margin-top:4px"><span class="tag"><svg viewBox="-8 -8 16 15"><path d="M0,-7 7,5.5 -7,5.5Z" fill="currentColor"/></svg>${d.alert.join(', ')}</span></div>` : ''}</td>
</tr>`;
    }).join('')}</tbody>`;
    const epPause = `${PAU.length} shorter episodes, 5 to 10 min each (${f0(pauMin)} min in total), are not detailed: they are very probably breaks. They are counted in the summary under “Other · probable break”.`;
    // minutes lost by main cause (costly episodes) + the probable pauses
    const mainOf = d => RS[d.id] ? RS[d.id].causes[0] : null;
    // minutes of each episode by cause: all to the main cause, unless a share is set (Støvla: weather share from the stress test)
    const rainPct = EP.sys ? EP.sys.rain_pct : 0;   // rain effect at equal terrain, measured on the massifs (part 03)
    const shareOf = d => { const rs = RS[d.id], out = {}; if (!rs) return out;
      let rest = d.lost_min;
      Object.entries(rs.partage || {}).forEach(([k, v]) => { if (v === 'pluie') { const m = Math.min(rest, (d.real_min - d.lost_min) * rainPct); out[k] = m; rest -= m; } });
      out[rs.causes[0]] = (out[rs.causes[0]] || 0) + rest; return out; };
    const groups = Object.keys(CAUSE).filter(k => k !== 'pause').map(k => ({ k, eps: MAJ.filter(d => shareOf(d)[k] > 0) })).filter(c => c.eps.length)
      .map(c => ({ k: c.k, min: d3.sum(c.eps, d => shareOf(d)[c.k]), n: c.eps.filter(d => mainOf(d) === c.k).length, part: c.eps.filter(d => mainOf(d) !== c.k) })).sort((a, b) => b.min - a.min);
    const stv = MAJ.find(d => RS[d.id] && RS[d.id].partage), stvS = stv ? shareOf(stv) : null;
    const unq = MAJ.filter(d => !mainOf(d));
    const bars = groups.concat(unq.length ? [{ k: null, min: d3.sum(unq, d => d.lost_min), n: unq.length }] : [], PAU.length ? [{ k: 'pause', min: pauMin, n: PAU.length }] : []);
    const totMin = majMin + pauMin, col = c => c.k ? C(CAUSE[c.k][1]) : 'var(--surface-3)', lab = c => c.k ? CAUSE[c.k][0] : 'Not qualified';
    $('cause-mix').innerHTML = `<div class="gm-bar">${bars.map(c => `<i style="flex:${c.min};background:${col(c)}" title="${lab(c)}"></i>`).join('')}</div>
      <div class="gm-rows">${bars.map(c => `<div class="gm-row"><i style="background:${col(c)}"></i><span>${lab(c)} <span class="mono">· ${[c.n ? `${c.n} episode${c.n > 1 ? 's' : ''}` : '', ...(c.part || []).map(d => `share of ${d.act === 'stuvla' ? 'Støvla' : actName(d.act)}`)].filter(Boolean).join(' + ')}</span></span><span class="mono">${f0(c.min)} min</span><span class="mono"><b>${f0(c.min / totMin * 100)}%</b></span></div>`).join('')}</div>`;
    readout('r-cause', `${slow.length} episodes · ${f0(totMin)} min`);
    const fast = EPS.filter(d => d.sign < 0).sort((a, b) => a.lost_min - b.lost_min), fastOk = fast.filter(d => !d.gps);
    const epFast = `On the fast side, ${fast.length} episodes give back ${f0(-d3.sum(fastOk, d => d.lost_min))} min (excluding doubtful GPS slopes). The clearest: ${fastOk.slice(0, 3).map(d => `${actName(d.act)} (${dayLbl(d.day)}, ${f0(-d.lost_min)} min)`).join(', ')}. ${(g => g.length ? `${g.join(' and ')} ${g.length > 1 ? 'are left out' : 'is left out'}: a GPS slope steeper than 60% distorts the expected time.` : '')(fast.filter(d => d.gps).map(d => actName(d.act)))}`;
    DEFS.episodes = { t: `The ${MAJ.length} slow episodes of 10 min or more · ${f0(d3.sum(bars.filter(c => c.k !== 'pause'), c => Math.round(c.min)))} min`, wide: true, html: () => `<p>“Lost” is the time spent beyond the expected time over the episode. The cause is qualified afterwards, from the account of the day.</p>${stv ? `<div class="def-ex"><b>Støvla (${dayLbl(stv.day)}), an episode with two causes.</b> ${f0(stv.real_min)} min instead of ${f0(stv.real_min - stv.lost_min)} expected: ${f0(stv.lost_min)} min lost. I could not find the way through the rock band: snowfield, scree, slippery rock, and the drop not far away. And it was raining, so I moved very carefully. To split the two, I apply the rule measured over the 15 massifs (part 03): on equal terrain, rain made me <b>${f0(rainPct * 100)}%</b> slower. Over the ${f0(stv.real_min - stv.lost_min)} expected minutes, that makes <b>${f0(stvS.meteo || 0)} min</b> for the weather; the remaining <b>${f0(stvS.sentier || 0)} min</b> go to the trail. Even in good weather I would not have been much faster: it is the passage itself that cost the time. The rockfall on the way back is the best illustration: this ground was not just difficult, it was dangerous.</div>` : ''}<div class="table-wrap flat"><table class="data ep">${epTable}</table></div><p class="muted" style="margin-top:10px">${epPause} ${epFast}</p>` };
    $('ep-btn').innerHTML = defBtn('episodes', `The ${MAJ.length} slow episodes, one by one`);
    const fam = d3.rollups(bars.filter(c => c.k), v => d3.sum(v, c => c.min), c => CAUSE[c.k][2]);
    const top = groups[0], subi = d3.sum(fam.filter(([fm]) => /subi/.test(fm)), d => d[1]);
    const CL = EP.cluster;
    if (CL) $('lede-roll').innerHTML = `Taken alone, my steps are ordinary. But they come in an order. Shuffled at random, my deviations would give about ${f0(CL.all.n)} slow episodes, for ${f0(CL.all.min)} min. There are <b>${CL.obs_n}</b>, costing <b>${f0(CL.obs_min)} min</b>: slow segments come in chains.`;
    $('t-roll').innerHTML = `<b>${slow.length}</b> slow episodes, <b>${f0(totMin)} min</b>, of which <b>${MAJ.length}</b> of 10 min or more make up most of it; <b>${f0(subi / totMin * 100)}%</b> of the time lost is endured.<br><br>A single step is ordinary; it is the chain that costs. A difficult passage lasts a whole climb: the relief creates these streaks (part 03).`;
    DEFS.enchainement = { t: 'How an episode is spotted', html: () => `
      <p><b>The measure.</b> On each 250 m segment, the deviation e compares the actual time with the expected time: e = ln(actual time ÷ expected time), on the watch’s moving time.</p>
      <p><b>The episode.</b> At least 3 segments in a row (750 m) whose average deviation exceeds ±0.20, i.e. 22% slower or 18% faster than expected.</p>
      <p><b>The chance test.</b> To know whether these chains are real, the same deviations are shuffled 2,000 times and the episodes recounted each time. It is the equivalent of a runs test in finance: independent returns do not make long streaks.</p>
      <div class="def-ex"><b>Result.</b> Chance would give about ${CL ? f0(CL.all.n) : '–'} slow episodes for ${CL ? f0(CL.all.min) : '–'} min; there are ${CL ? CL.obs_n : '–'}, for ${CL ? f0(CL.obs_min) : '–'} min. ${CL ? `Even shuffling only within each outing gives just ${f0(CL.act.min)} min: slowness chains within the same passage.` : ''}</div>
      <p class="muted">Causes are qualified afterwards, from the account of the day, for episodes of 10 min or more. The ${PAU.length} episodes of 5 to 10 min (${f0(pauMin)} min) are very probably breaks.</p>` };
    { const pt = $('c-bands').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('enchainement')); }
  }

  /* ---------- 05 · independent summits, steep climbs: the risk structure of the massifs ---------- */
  /* ---------- definition buttons (finance terms explained on demand) ---------- */
  // usage: defBtn('cle') inside any HTML string; the text lives in DEFS
  const DEFS = {};
  const defBtn = (k, label) => label
    ? `<button type="button" class="def-btn wide" data-def="${k}"><i>?</i>${label}</button>`
    : `<button type="button" class="def-btn" data-def="${k}" aria-label="Explanation: ${DEFS[k] ? DEFS[k].t : k}">?</button>`;
  const pop = document.createElement('div'); pop.className = 'def-pop'; pop.hidden = true; pop.setAttribute('role', 'dialog'); root.appendChild(pop);
  let popFor = null;
  const closeDef = () => { pop.hidden = true; if (popFor) popFor.setAttribute('aria-expanded', 'false'); popFor = null; };
  document.addEventListener('click', ev => {
    const b = ev.target.closest('.def-btn');
    if (!b) { if (!ev.target.closest('.def-pop')) closeDef(); return; }
    if (popFor === b) { closeDef(); return; }
    const d = DEFS[b.dataset.def]; if (!d) return;
    pop.classList.toggle('big', !!d.wide); pop.classList.toggle('full', !!d.full);
    pop.innerHTML = `<button type="button" class="def-x" aria-label="Close">×</button><h5>${d.t}</h5>${d.html()}`;
    pop.hidden = false; popFor = b; b.setAttribute('aria-expanded', 'true');
    if (d.full) { pop.classList.remove('sheet'); pop.style.left = pop.style.top = ''; if (d.after) d.after(pop); return; }
    if (innerWidth < 640) { pop.classList.add('sheet'); pop.style.left = pop.style.top = ''; if (d.after) d.after(pop); return; }
    pop.classList.remove('sheet');
    const r = b.getBoundingClientRect(), w = pop.offsetWidth, h = pop.offsetHeight;
    let x = Math.min(innerWidth - w - 12, Math.max(12, r.left - 20)), y = r.bottom + 8;
    if (y + h > innerHeight - 12) y = Math.max(12, r.top - h - 8);
    pop.style.left = `${x}px`; pop.style.top = `${y}px`;
    if (d.after) d.after(pop);
  });
  pop.addEventListener('click', ev => { if (ev.target.closest('.def-x')) closeDef(); });
  document.addEventListener('keydown', ev => { if (ev.key === 'Escape') closeDef(); });
  addEventListener('scroll', () => { if (!pop.classList.contains('sheet') && !pop.classList.contains('full')) closeDef(); }, { passive: true });

  function drawAcf() {
    const T = EP.topo, M = T.massifs, SY = EP.sys, AG = SY.agg, sig = t => Math.abs(t.r) > t.crit;
    const med = k => d3.median(M, m => m[k]), steepD = d3.sum(T.slope.filter(b => b.lo >= 20), b => b.dist), steepG = d3.sum(T.slope.filter(b => b.lo >= 20), b => b.gain);
    const SPLIT = { reinebringen_helvete: ['Reinebringen', 'Helvete'] };   // une sortie, deux massifs
    const mName = m => { const same = M.filter(x => x.act === m.act), k = same.indexOf(m); return same.length < 2 ? actName(m.act) : SPLIT[m.act] ? SPLIT[m.act][k] : `${actName(m.act)} (${k + 1})`; };
    const rainPct = SY.rain_pct * 100, worst = M.reduce((b, m) => m.lost > b.lost ? m : b, M[0]);

    // 1. exposure: two small charts with their own scale, steep classes (> 20%) highlighted
    [['c-acf1', 'dist', 'r-acf1', `> 20% : <b>${f0(steepD * 100)}%</b> of the distance`], ['c-acf1b', 'gain', 'r-acf1b', `> 20% : <b>${f0(steepG * 100)}%</b> of the D+`]].forEach(([id, k, rid, rd]) => {
      const B = T.slope, lab = b => b.hi == null ? `> ${b.lo}%` : `${b.lo}–${b.hi}%`;
      const f = frame(id, { t: 10, r: 40, b: 26, l: 6 });
      const x = d3.scaleBand().domain(B.map(lab)).range([0, f.w]).padding(.25);
      const y = d3.scaleLinear().domain([0, d3.max(B, b => b[k]) * 1.12]).nice().range([f.h, 0]);
      yGrid(f.g, y, f.w, 3, v => `${f0(v * 100)}%`);
      f.g.selectAll(null).data(B).join('path').attr('d', b => barPath(x(lab(b)), f.h, x.bandwidth(), y(b[k]), 2))
        .attr('fill', b => b.lo >= 20 ? C('--down') : C('--text-muted')).attr('opacity', b => b.lo >= 20 ? .9 : .45);
      f.g.selectAll(null).data(B).join('text').attr('class', 'lbl').attr('x', b => x(lab(b)) + x.bandwidth() / 2).attr('y', b => y(b[k]) - 4).attr('text-anchor', 'middle').text(b => `${f0(b[k] * 100)}`);
      xAxis(f.g, x, f.h, 7, d => f.narrow ? d.replace(' %', '').replace('> ', '>') : d);
      readout(rid, rd);
    });

    // 2. full risk sheet
    const T2 = T.agg, wi = M.indexOf(worst), topI = T.intens[T.intens.length - 1], flatI = T.intens[0];
    const steepT = d3.sum(T.intens.filter((c, k) => T.slope[k].lo >= 20), c => c.time);
    const rows = [
      ['Correlation of terrain from one massif to the next', `steepness r = ${f2(T.grad_next.r)} · ${sig(T.grad_next) ? 'significatif' : 'not significant'} (threshold ${f2(T.grad_next.crit)}, ${T.grad_next.n} pairs)`,
        'The terrain of the next massif cannot be inferred from the previous one: a difficult summit does not announce another.', 'Massifs are drawn independently: their deviations offset each other from one massif to the next.'],
      ['Correlation within a massif', `climb → descent: steepness r = ${f2(T.grad_same.r)} · pace r = ${f2(T.pace_same.r)}`,
        'Once committed, the whole massif goes the same way: deviations do not offset, they add up all the way down.', `Count deviations massif by massif, not segment by segment: the uncertainty is ${f1(T2.massif / T2.seg)} times larger.`],
      [`Systematic risk${defBtn('sysspec')}`, `rain: ${fs0(rainPct)}% on equal terrain · ${SY.n_wet} massifs · ${fs0(AG.sys)} min`,
        'Rain weighs on every massif of the moment, whatever its terrain: it does not cancel out.', 'Add a common weather factor: its minutes add up end to end, massif after massif.'],
      ['Specific risk', `± ${f0(AG.spec)} min over the ${M.length} massifs · terrain from one massif to the next r = ${f2(T.grad_next.r)}`,
        'Scree, invisible trail, rock band: what belongs to one massif only and says nothing about the next.', `This is what the returns to sea level wipe out: it goes from ± ${f0(AG.block)} to ± ${f0(AG.spec)} min.`],
      ['Exit option', `back to sea level in ${f0(med('t_exit'))} min (median) after the summit (max ${f0(d3.max(M, m => m.t_exit))} min)`,
        `Each massif ends at sea level: the loss is capped. Worst massif: ${fs0(worst.lost)} min (${mName(worst)}).`, 'A failed massif does not spread to the rest of the traverse.'],
      ['Commitment time', `${f0(med('t_tot'))} min (median) per massif, of which ${f0(med('t_engage'))} min of climbing above 15%`,
        `Short commitments: the decision to go on or turn back is made again at the foot of each of the ${M.length} massifs.`, 'Turning back keeps its value, because it can be done without compromising what follows.'],
      ['Intensity', `> 20% : ${f0(steepD * 100)}% of the distance, ${f0(steepT * 100)}% of the time, ${f0(steepG * 100)}% of the D+ · ${f0(topI.vr)} m/h and ${topI.hr} bpm above 30%, against ${f0(flatI.vr)} m/h and ${flatI.hr} bpm on the flat`,
        'Risk is not spread out: it is concentrated on short, very steep passages, where effort is at its peak and a mistake is costly.', 'The average slope is not enough: count the share of the massif above 20% and the specific effect of steep descents (part 04).'],
    ];
    $('risk-sheet').innerHTML = `<thead><tr><th>Indicator</th><th>Measure</th><th>Risk reading</th><th>Consequence for the model</th></tr></thead><tbody>${rows.map(r => `<tr><td${/def-btn/.test(r[0]) ? ' class="def-mid"' : ''}><b>${r[0]}</b></td><td class="mono rs-m">${r[1]}</td><td>${r[2]}</td><td class="muted">${r[3]}</td></tr>`).join('')}</tbody>`;
    readout('r-sheet', `${M.length} massifs · ${M.length - 1} returns to sea level`);

    // 3. diversification, in words: one block, independent massifs, with the rain
    $('ex-intro').innerHTML = `<b>Independent, the deviations of the massifs add up as the square root of the sum of squares and partly offset each other; linked, they add up end to end.</b>`;
    $('ex-cols').innerHTML = [
      [C('--down'), 'Without independence', 'A single block with no way out', AG.block, `The whole traverse as one single ridge, never coming down: both risks add up end to end, the terrain of each massif as well as the weather. No deviation offsets another.`],
      [C('--accent'), 'The benefit: specific risk is diluted', 'Independent massifs', AG.spec, `Each return to sea level resets the counter: scree on one massif says nothing about the next, and a difficult massif is offset by an easier one. Over ${M.length} massifs, each one’s own risk is divided by ${f0(AG.block / AG.spec)}.`],
      [C('--series-avec'), 'The limit: systematic risk remains', 'Plus rain', AG.total, `Returns to sea level do not stop the rain: it hit the ${SY.n_wet} last massifs at the same time, and its ${fs0(AG.sys)} min add up end to end. <span class="nw">√(${f0(AG.spec)}² + ${f0(AG.sys)}²) = ± ${f0(AG.total)}</span>.`],
    ].map(([c, s_, t, v, p]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><b class="v">± ${f0(v)} min</b><p>${p}</p></div>`).join('');
    $('ex-msg').innerHTML = `<b>Independence is a benefit, not full protection.</b> The more independent massifs, the more each one’s own risk is diluted; the common risk stays whole. Without returning to sea level: ± ${f0(AG.block)} min. With: ± ${f0(AG.spec)}. But the rain brings back ${fs0(AG.sys)} min that nothing dilutes: ± ${f0(AG.total)}.`;
    readout('r-acf2', `block <b>± ${f0(AG.block)}</b> · independent <b>± ${f0(AG.spec)}</b> · with rain <b>± ${f0(AG.total)}</b>`);

    // the « ? » button: systematic and specific risk, how the rain effect is measured
    DEFS.sysspec = { t: 'Specific risk and systematic risk', html: () => `
      <p>In finance, the risk of a portfolio splits in two. <b>Specific risk</b> belongs to a single company (a failed product, a lawsuit): by holding many independent stocks, it is diluted. <b>Systematic risk</b> hits the whole market at once (a crisis, a rate rise): holding more stocks changes nothing.</p>
      <p>Here, the massifs are the stocks. <b>Specific</b>: the terrain of each massif, scree, an invisible trail, a rock band. <b>Systematic</b>: the weather, which weighs on every massif of the moment.</p>
      <p class="def-f">total risk = √(specific² + systematic²)</p>
      <p><b>The measure.</b> The ${M.length} massifs are compared on equal terrain (same grade): in the rain (a day with 1 mm or more, ${SY.n_wet} massifs), the pace is <b>${fs0(rainPct)}%</b> slower. Without accounting for terrain, one would find ${fs0(SY.raw_pct * 100)}%: the massifs in the rain were also harder. For each massif in the rain, the systematic part is its expected time × ${f0(rainPct)}%; the rest is specific.</p>
      <p><b>The other common factors tried</b>, on equal terrain (p: share of random draws that do as well):</p>
      <div class="table-wrap flat"><table class="data"><tbody>${SY.tried.map(t => `<tr><td>${t.l}</td><td class="n mono">p = ${f2(t.p)}</td></tr>`).join('')}</tbody></table></div>
      <p class="muted">Temperature stands out most, but it goes with the rain: over 9 days, cold and rain arrive together, they cannot be separated. Call it “the weather”. HRV stands out too, but out of six factors tried, one often stands out by chance, and part 04 finds no effect of fatigue on the segments: a lead, not a result. With ${SY.n_wet} massifs in the rain, the effect is an order of magnitude; the simulation (part 07) measures it on all segments and finds an effect of the same order.</p>
      <p class="muted">Reference points: if the segments were independent, it would be ± ${f0(T.agg.seg)} min; if all the massifs were, rain included, ± ${f0(AG.indep)} min. Massif: a continuous stretch above 60 m that peaks above 150 m, between two returns to sea level (below 60 m). Each massif weighs the minutes actually lost or gained.</p>` };
    $('t-acf').innerHTML = `Thanks to <b>diversification</b>, the independent massifs bring the uncertainty down from ± ${f0(AG.block)} to <b>± ${f0(AG.spec)} min</b>: each return to sea level wipes out part of the massif’s own risk. But the rain hits all the massifs at once: <b>${fs0(AG.sys)} min</b> that nothing dilutes. Decide massif by massif, and keep the margin for the weather.`;
  }


  /* ---------- 06 · sensitivities (tornado) + correlation matrix ---------- */
  function drawSens() {
    const S = R.sens.slice().sort((a, b) => b.pct - a.pct), sLbl = n => n === 'slope (+10%)' ? 'slope ↑ or ↓ (+10%)' : n;
    const f = frame('c-sens', { t: 12, r: 64, b: 32, l: 150 });
    const x = d3.scaleLinear().domain([-25, 50]).range([0, f.w]);
    const y = d3.scaleBand().domain(S.map(s => s.name)).range([0, f.h]).padding(.42);
    f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(6).tickSize(-f.h).tickFormat('')).lower();
    xAxis(f.g, x, f.h, f.narrow ? 3 : 6, v => `${v > 0 ? '+' : ''}${v}%`);
    f.g.append('line').attr('class', 'zero').attr('x1', x(0)).attr('x2', x(0)).attr('y1', -6).attr('y2', f.h);
    const sig = s => s.lo > 0 || s.hi < 0;
    const col = s => !sig(s) ? C('--text-muted') : s.pct > 0 ? C('--down') : C('--up');
    const r = f.g.selectAll('.sr').data(S).join('g').attr('transform', s => `translate(0,${y(s.name)})`);
    r.append('text').attr('class', 'lbl-strong').attr('x', -10).attr('y', y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(s => sLbl(s.name));
    r.append('rect').attr('x', s => x(Math.min(0, s.pct))).attr('width', s => Math.abs(x(s.pct) - x(0))).attr('height', y.bandwidth()).attr('rx', 2).attr('fill', col).attr('fill-opacity', .75);
    const mid = y.bandwidth() / 2;
    r.append('line').attr('x1', s => x(s.lo)).attr('x2', s => x(s.hi)).attr('y1', mid).attr('y2', mid).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2);
    ['lo', 'hi'].forEach(k => r.append('line').attr('x1', s => x(s[k])).attr('x2', s => x(s[k])).attr('y1', mid - 5).attr('y2', mid + 5).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2));
    r.append('text').attr('class', 'lbl-ink tagt').attr('x', s => x(Math.max(s.hi, 0)) + 8).attr('y', mid).attr('dy', '.35em').text(s => `${s.pct > 0 ? '+' : ''}${f1(s.pct)}%${sig(s) ? '' : ' n.s.'}`);
    hover(r.append('rect').attr('class', 'hit').attr('x', -150).attr('width', f.w + 210).attr('y', -y.step() * .2).attr('height', y.step()),
      s => `<b>${sLbl(s.name)}</b>${row('effet', `${s.pct > 0 ? '+' : ''}${f1(s.pct)}%`)}${row('95% CI', `${f1(s.lo)} to ${f1(s.hi)}%`)}${row('significatif', sig(s) ? 'yes' : 'no')}`);
    {
      const sac_ = sens['pack on my back'], ter_ = sens['terrain (+1 level)'], k1 = 1 + sac_.pct / 100, k2 = 1 + ter_.pct / 100;
      DEFS.regression = { t: 'The regression: isolating the effect of each factor', html: () => `
        <p><b>The problem.</b> On each 250 m segment, I compare my actual time with the time predicted by Tobler (part 02). Several things play at once: the pack, the slope, the terrain, the wind, fatigue. And they are mixed: with the pack I walked mostly on the flat; without it I climbed steep summits. Simply comparing “with” and “without” the pack would mix the effect of the pack with that of the terrain.</p>
        <p><b>The principle.</b> The regression looks for a time multiplier for each factor, and picks the set of multipliers that best explains the ${f0(N_REG)} segments <i>all at once</i>. Since each segment combines the factors differently, the calculation manages to untangle them: this is what is called “all else being equal”.</p>
        <p class="def-ex"><b>Example.</b> A segment expected to take 10 min. With the pack: × ${f2(k1)}, i.e. ${f1(10 * k1)} min. If the terrain is also one notch harder: × ${f2(k2)}, i.e. ${f1(10 * k1 * k2)} min. The effects multiply. The “${fs0(sac_.pct)}%” of the pack therefore means: two segments identical in slope, terrain, wind and fatigue, one with the pack, the other without; the one with the pack takes ${f0(sac_.pct)}% more time.</p>
        <p><b>How it chooses.</b> Least squares: it keeps the multipliers that make the sum of squared errors as small as possible, between the time they predict and the actual time.</p>
        <p><b>Reading the result.</b> The whisker is the 95% confidence interval: the zone where the true effect very probably lies. If it crosses zero, the effect cannot be told apart from chance (n.s.), like fatigue. The R² of ${f0(R.r2 * 100)}% says what share of the differences from one segment to another these factors explain; the rest is terrain the numbers do not see.</p>
        <p class="muted">Technical: ordinary least squares on ln(actual time / Tobler time); a coefficient β becomes an effect of e<sup>β</sup> − 1 in %. The logarithm turns multiplications into additions, which regression can handle.</p>` };
      $('sens-more').innerHTML = defBtn('regression', 'How the regression isolates each factor');
    }
    readout('r-sens', `R² <b>${f2(R.r2)}</b> · n <b>${N_REG}</b> · OLS`);

    const V = R.corr.vars, M = R.corr.m, n = V.length;
    const cm = { t: 6, r: 6, b: 92, l: 86 };
    const c = frame('c-corr', cm);
    const s = Math.min(c.w, c.h) / n;
    const colS = d3.scaleLinear().domain([-1, 0, 1]).range([C('--div-neg'), C('--div-mid'), C('--div-pos')]).interpolate(d3.interpolateLab);
    const cells = [];
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) cells.push({ i, j, v: M[i][j] });
    c.g.selectAll('.cc').data(cells).join('rect').attr('x', d => d.j * s + .5).attr('y', d => d.i * s + .5).attr('width', s - 1).attr('height', s - 1).attr('fill', d => d.i === d.j ? C('--surface-3') : colS(d.v));
    if (s > 22) c.g.selectAll('.ct').data(cells.filter(d => d.i !== d.j)).join('text').attr('x', d => d.j * s + s / 2).attr('y', d => d.i * s + s / 2).attr('dy', '.35em').attr('text-anchor', 'middle')
      .attr('class', 'lbl').style('font-size', `${Math.min(10, s * .3)}px`).style('fill', d => Math.abs(d.v) > .5 ? '#fff' : C('--text-secondary')).text(d => F('.1f')(d.v).replace('−0,0', '0,0'));
    c.g.selectAll('.rl').data(V).join('text').attr('class', 'lbl').attr('x', -6).attr('y', (v, i) => i * s + s / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(v => v);
    c.g.selectAll('.cl').data(V).join('text').attr('class', 'lbl').attr('transform', (v, i) => `translate(${i * s + s / 2},${n * s + 6}) rotate(-45)`).attr('text-anchor', 'end').text(v => v);
    hover(c.g.selectAll('.ch').data(cells.filter(d => d.i !== d.j)).join('rect').attr('class', 'hit').attr('x', d => d.j * s).attr('y', d => d.i * s).attr('width', s).attr('height', s),
      d => `<b>${V[d.i]} × ${V[d.j]}</b>${row('Spearman’s ρ', fs2(d.v))}`);
    const pente = sens['slope (+10%)'], desc = sens['steep descent (> 15%)'];
    // vitesses réelles en pente raide (15 à 25%), montée contre descente : temps = Tobler × exp(e) × calage sur le temps en mouvement
    const tob = q => 6 * Math.exp(-3.5 * Math.abs(q.slope / 100 + .05)), dK = R.series.map((q, i) => q.km - (i ? R.series[i - 1].km : 0));
    const spd = sac => {
      const ix = d3.range(R.series.length).filter(i => R.series[i].sac === sac), T = i => dK[i] / tob(R.series[i]) * Math.exp(R.series[i].e);
      const cal = d3.sum(R.rows.filter(r => r.sac === sac), r => r.mov_h) / d3.sum(ix, T);
      const v = (lo, hi) => { const k = ix.filter(i => R.series[i].slope >= lo && R.series[i].slope < hi); return { n: k.length, v: d3.sum(k, i => dK[i]) / (d3.sum(k, T) * cal), t: d3.sum(k, i => dK[i]) / d3.sum(k, i => dK[i] / tob(R.series[i])) }; };
      return { up: v(15, 25), dn: v(-25, -15) };
    };
    const vT = spd(0);
    $('t-sens').innerHTML = `<b>On steep ground, without the pack, I climb faster than I descend</b> (${f1(vT.up.v)} vs ${f1(vT.dn.v)} km/h), the opposite of Tobler. The reason is the terrain: in the Lofoten, mostly scree and technical passages with scrambling. Going up, the poles help; going down, caution is needed (${fs0(desc.pct)}%). The pack remains the first factor (<b>${fs0(sacS.pct)}%</b>). Fatigue comes right after.`;
    // le cœur selon le terrain (outils/frequence_cardiaque.js) : encadré « Ce que dit le cœur »
    const FC = window.RISK_FC, GA = (window.RISK_ACTE2 || {}).gamma;
    if (FC && GA) {
      const st = FC.steps, bpm = v => `${fs0(v)} bpm`, ci = x => `from ${f0(x.lo)} to ${f0(x.hi)}`;
      $('t-fc').innerHTML = `<b>Difficult terrain costs me time, not breath.</b> At equal slope, pack and pace, my heart beats ${f0(st.fm.b)} bpm more when the terrain goes from easy to moderate, then nothing more: from moderate to demanding, <b>${bpm(st.mex.b)}</b>. Yet that is where my time makes its jump (<b>+${f0(GA.steps[1].pct)}%</b>, the gamma of part 06). Demanding terrain does not wear me out: it asks me to find the way and place each foot. On this ground, the danger is a mistake, not fatigue. ${defBtn('fc')}`;
      DEFS.fc = { t: 'What the heart says: the method', wide: true, html: () => `
        <p><b>The measure.</b> The watch records heart rate continuously; each 250 m segment gets its average (${FC.n} segments, ${FC.sorties} outings).</p>
        <p><b>The method.</b> The same idea as the regression of part 04, applied to heartbeats: heart rate is explained by the slope (up and down), the pack, the pace deviation, the day, and one step per grade level. This shows how much the heart rises from one level to the next, at equal slope, pack and pace. Segments of the same outing resemble each other: the error margins are computed by outing.</p>
        <div class="table-wrap flat"><table class="data"><thead><tr><th>Grade step</th><th class="n">Time (part 06)</th><th class="n">Heart</th><th class="n">95% margin</th></tr></thead><tbody>
          ${[['easy → moderate', 0, st.fm], ['moderate → demanding', 1, st.mex], ['demanding → expert', 2, st.exexp]].map(([l, k, x]) => `<tr><td>${l}</td><td class="n">+${f0(GA.steps[k].pct)}%${GA.steps[k].t < 2 ? ' n.s.' : ''}</td><td class="n"><b>${bpm(x.b)}</b>${Math.abs(x.t) < 2 ? ' n.s.' : ''}</td><td class="n">${ci(x)} bpm</td></tr>`).join('')}
        </tbody></table></div>
        <p><b>Robustness.</b> Removing any single outing, the step from moderate to demanding stays between ${fs0(FC.loo_mex[0])} and ${fs0(FC.loo_mex[1])} bpm.</p>
        <p class="muted">Limits: an optical wrist sensor, less accurate in the cold and the rain; a segment’s average mixes walking and short stops. At equal effort, heart rate also falls over the days (${fs0(FC.day.b)} bpm per day), but stops in the wind, the cold and the sensor are mixed in: it is not kept as a result.</p>` };
    }
  }

  /* ---------- 06 · physical reserve (underwater curve) ---------- */
  function drawHrv() {
    // écart à la VFC habituelle (45 ms, mesurée hors traversée) : 0% = nuit ordinaire
    const HRV_BASE = HRV_USUAL, BAND = .1;
    const N = R.nights.map(n => ({ ...n, dd_hrv: n.hrv / HRV_BASE - 1 }));
    const base = 0, lowB = -BAND, hiB = BAND;
    const m = { t: 20, r: 52, b: 24, l: 8 };
    const f = frame('c-hrv', m);
    const x = d3.scalePoint().domain(N.map((n, i) => i)).range([0, f.w]).padding(.5);
    const y = d3.scaleLinear().domain([-.6, .65]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${fs0(v * 100).replace('+0', '0')}%`);
    xAxis(f.g, x, f.h, null, i => f.narrow ? `${i + 1}` : N[i].camp.replace(' heights', '').replace(' beach', ''));
    const st = d3.curveStepAfter, pts = [...N.map((n, i) => [x(i), n.dd_hrv]), [x(N.length - 1) + x.step() / 2, N[N.length - 1].dd_hrv]];
    const xs = pts.map(p => p[0]); xs[0] = x(0) - x.step() / 2;
    const P = pts.map((p, i) => [xs[i], p[1]]);
    // usual range (±10% around the usual HRV), red only below it
    f.g.append('rect').attr('x', 0).attr('width', f.w).attr('y', y(hiB)).attr('height', y(lowB) - y(hiB)).attr('fill', C('--text-muted')).attr('opacity', .12);
    f.g.append('path').attr('d', d3.area().curve(st).x(p => p[0]).y0(y(lowB)).y1(p => y(Math.min(p[1], lowB)))(P)).attr('fill', C('--down')).attr('fill-opacity', .25);
    f.g.append('path').attr('d', d3.area().curve(st).x(p => p[0]).y0(y(hiB)).y1(p => y(Math.max(p[1], hiB)))(P)).attr('fill', C('--up')).attr('fill-opacity', .2);
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(base)).attr('y2', y(base)).attr('stroke', C('--text-secondary')).attr('stroke-dasharray', '5 4').attr('stroke-width', 1.2);
        if (!f.narrow) f.g.append('text').attr('class', 'lbl').attr('x', 4).attr('y', y(lowB) + 13).attr('text-anchor', 'start').text(`0% = usual HRV ${HRV_BASE} ms · normal zone ±${f0(BAND * 100)}%`);
    f.g.append('path').attr('d', d3.line().curve(st).x(p => p[0]).y(p => y(p[1]))(P)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.6);
    f.g.selectAll('.hd').data(N).join('circle').attr('cx', (n, i) => x(i)).attr('cy', n => y(n.dd_hrv)).attr('r', 3.4).attr('fill', C('--bg')).attr('stroke', n => n.dd_hrv < lowB ? C('--down') : n.dd_hrv > hiB ? C('--up') : C('--text-primary')).attr('stroke-width', 1.6);
    const worst = N.reduce((a, b) => b.dd_hrv < a.dd_hrv ? b : a), wi = N.indexOf(worst);
    const best = N.reduce((a, b) => b.hrv > a.hrv ? b : a), bi = N.indexOf(best);
    axTag(f.g, f.w + 2, y(worst.dd_hrv), `${fs0(worst.dd_hrv * 100)}%`).select('rect').attr('fill', C('--down'));
    if (!f.narrow) {
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(wi) + 8).attr('y', y(worst.dd_hrv) + 16).text('2-hour night → gave up Hermannsdalstinden');
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(bi) + 8).attr('y', y(best.dd_hrv) - 8).text(`${fs0(best.dd_hrv * 100)}% · good fatigue after D1`);
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(0)).attr('y', y(N[0].dd_hrv) - 10).attr('text-anchor', 'middle').text('rested start');
    }
    hover(f.g.selectAll('.hh').data(N).join('rect').attr('class', 'hit').attr('x', (n, i) => x(i) - x.step() / 2).attr('width', x.step()).attr('y', 0).attr('height', f.h),
      n => `<b>${n.camp} · night of ${dateLbl(n.night)}</b>${row('HRV', `${n.hrv} ms`)}${row('deviation from usual', `${fs0(n.dd_hrv * 100)}%`)}${row('sommeil', hm(n.sleep_h))}${row('score', `${n.score}/100`)}${row('recharge', `${n.bb}/100`)}${row('resting HR', `${n.fc} bpm`)}`);
    readout('r-hrv', `usual <b>${HRV_BASE} ms</b> · max <b>${best.hrv} ms</b> · min <b>${worst.hrv} ms</b> · lowest deviation <b class="d">${fs0(worst.dd_hrv * 100)}%</b>`);

    const g = frame('c-sleep', { t: 8, r: 52, b: 22, l: 8 });
    const x2 = x.copy().range([0, g.w]);
    const y2 = d3.scaleLinear().domain([0, 11]).range([g.h, 0]);
    yGrid(g.g, y2, g.w, 2, v => `${v} h`);
    const bw = Math.min(18, x2.step() * .35);
    g.g.selectAll('.sb').data(N).join('path').attr('d', (n, i) => barPath(x2(i) - bw / 2, y2(0), bw, y2(n.sleep_h), 1.5)).attr('fill', n => n.sleep_h < 4 ? C('--warning') : C('--text-muted')).attr('fill-opacity', .8);
    g.g.selectAll('.stt').data(N).join('text').attr('class', 'lbl').attr('x', (n, i) => x2(i)).attr('y', n => y2(n.sleep_h) - 4).attr('text-anchor', 'middle').text(n => f1(n.sleep_h));
    xAxis(g.g, x2, g.h, null, i => g.narrow ? `${+N[i].night.slice(8)}` : dateLbl(N[i].night));
    const after = N.slice(wi + 1);
    const low = N.filter(n => n.hrv < HRV_BASE * (1 - BAND)), firstLow = low[0];
    $('t-hrv').innerHTML = `<b>0%</b> the first night (${N[0].hrv} ms, rested). <b>${fs0(best.dd_hrv * 100)}%</b> after the big first day: the body absorbs it. <b>${fs0(firstLow.dd_hrv * 100)}%</b> on ${firstLow.camp}, after a night of ${hm(firstLow.sleep_h)}: from then on, HRV never returns to the normal zone.<br><br>The reserve wears down, and yet the pace does not drop. Fatigue shows in the decisions: Helvetestinden (D4) and Hermannsdalstinden (D5) are given up. One factor remains that I do not control: the weather.`;
    DEFS.vfc = { t: 'Where the HRV measure comes from', html: () => `
      <p><b>The origin.</b> The heart does not beat like a metronome: the interval between two beats varies by a few milliseconds. This heart rate variability (HRV) is driven by the nervous system: rested, it lets the heart vary a lot; tired or stressed, it tightens it. Athletes have tracked it since the 1990s to dose their training.</p>
      <p><b>The construction.</b> The watch measures the average HRV of each night, in milliseconds. I compare it with my usual value, measured by the same watch outside the traverse.</p>
      <div class="def-f">deviation = night’s HRV ÷ usual HRV (${N[0].hrv} ms) − 1</div>
      <div class="def-ex"><b>Example.</b> ${firstLow.camp}: ${firstLow.hrv} ms, i.e. ${fs0(firstLow.dd_hrv * 100)}%. The grey band (±10%) is the normal zone: a night inside it is an ordinary night.</div>
      <p><b>How to read it.</b> Above usual after a big effort: active recovery, a good sign. Durably below: fatigue that builds up instead of clearing. The curve looks like a fund below its high-water mark: as long as it stays under water, the loss is not made up.</p>
      <p class="muted">Limit: a single measure per night, also sensitive to cold, wind and sleep quality.</p>` };
    { const pt = $('c-hrv').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('vfc')); }
  }

  /* ---------- 09 bis · rain persistence, 2026 among 1 200 windows (risque_meteo.js, outils/meteo_series.js) ---------- */
  function drawPersist() {
    const M = window.RISK_METEO; if (!M) return;
    const pww = M.p_ww, pwd = M.p_wd, p = M.p_wet;

    // left: P(rain | yesterday)
    const f = frame('c-persist', { t: 26, r: 46, b: 30, l: 8 });
    const B = [{ k: 'dry day before', v: pwd, n: M.n_wd }, { k: 'rainy day before', v: pww, n: M.n_ww }];
    const x = d3.scaleBand().domain(B.map(b => b.k)).range([0, f.w]).padding(.45);
    const y = d3.scaleLinear().domain([0, .8]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 4, v => `${f0(v * 100)}%`);
    xAxis(f.g, x, f.h, null, d => d);
    f.g.selectAll('.pb').data(B).join('path').attr('d', b => barPath(x(b.k), y(0), x.bandwidth(), y(b.v), 2)).attr('fill', (b, i) => i ? C('--down') : C('--accent')).attr('fill-opacity', .75);
    f.g.selectAll('.pt').data(B).join('text').attr('class', 'lbl-ink').attr('x', b => x(b.k) + x.bandwidth() / 2).attr('y', b => y(b.v) - 7).attr('text-anchor', 'middle').text(b => `${f0(b.v * 100)}%`);
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(p)).attr('y2', y(p)).attr('stroke', C('--text-secondary')).attr('stroke-dasharray', '5 4');
    f.g.append('text').attr('class', 'lbl').attr('x', 4).attr('y', y(p) - 5).text(`without memory: ${f0(p * 100)}%`);
    hover(f.g.selectAll('.ph').data(B).join('rect').attr('class', 'hit').attr('x', b => x(b.k)).attr('width', x.bandwidth()).attr('y', 0).attr('height', f.h),
      b => `<b>After a ${b.k}</b>${row('rain the next day', `${f0(b.v * 100)}%`)}${row('observed days', f0(b.n))}`);
    readout('r-persist', `×<b>${f1(pww / pwd)}</b> after a rainy day`);

    // right: one small histogram per question, 2026 marked
    const g = frame('c-strip', { t: 8, r: 8, b: 4, l: 8 });
    const S = [
      { k: 'Longest dry streak', o: M.dry, fmt: v => `${f0(v)} d`, tick: e => f0(e + .5), unit: 'd' },
      { k: 'Biggest 3-day episode', o: M.max3, fmt: null, tick: e => f0(e), unit: 'mm' },
    ];
    const rh = g.h / S.length;
    S.forEach((s, i) => {
      const o = s.o, E = o.edges, gg = g.g.append('g').attr('transform', `translate(0,${i * rh})`);
      const xx = d3.scaleLinear().domain([E[0], E[E.length - 1]]).range([0, g.w]), top = 22, base = rh - 22;
      const yy = d3.scaleLinear().domain([0, d3.max(o.hist)]).range([base, top]);
      gg.append('text').attr('class', 'lbl-strong').attr('x', 0).attr('y', 13).text(s.k);
      gg.append('text').attr('class', 'lbl-ink').attr('x', g.w).attr('y', 13).attr('text-anchor', 'end').text(`2026: ${s.fmt ? `${s.fmt(o.v)} · ` : ''}percentile ${f0(o.pct)}`);
      const inBin = k => o.v >= E[k] && o.v < E[k + 1];
      gg.selectAll('.hb').data(o.hist).join('rect').attr('x', (n, k) => xx(E[k]) + .5).attr('width', (n, k) => Math.max(1, xx(E[k + 1]) - xx(E[k]) - 1)).attr('y', n => yy(n)).attr('height', n => base - yy(n))
        .attr('fill', (n, k) => inBin(k) ? C('--down') : C('--text-muted')).attr('fill-opacity', (n, k) => inBin(k) ? .9 : .5);
      gg.append('line').attr('x1', 0).attr('x2', g.w).attr('y1', base).attr('y2', base).attr('stroke', C('--grid'));
      const lo = s.unit === 'd' ? E[0] + .5 : E[0], hi = s.unit === 'd' ? E[E.length - 1] - .5 : E[E.length - 1];
      const tL = gg.append('text').attr('class', 'lbl').attr('x', 0).attr('y', base + 13).text(`${f0(lo)} ${s.unit}`);
      const tR = gg.append('text').attr('class', 'lbl').attr('x', g.w).attr('y', base + 13).attr('text-anchor', 'end').text(`${f0(hi)} ${s.unit}`);
      // médiane sur l'axe ; moyenne ajoutée dans la même étiquette si la place le permet
      const nb = v => Number.isInteger(v) ? f0(v) : f1(v), pm = xx(o.med);
      gg.append('line').attr('x1', pm).attr('x2', pm).attr('y1', top - 2).attr('y2', base + 3).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3').attr('opacity', .8);
      const lab = gg.append('text').attr('class', 'lbl').style('fill', C('--text-primary')).attr('y', base + 13);
      const put = txt => { lab.text(txt); const w = lab.node().getComputedTextLength(), x0 = Math.max(0, Math.min(g.w - w, pm - w / 2)); lab.attr('x', x0); return [x0, x0 + w]; };
      let [a0, a1] = put(`med. ${nb(o.med)} · mean ${nb(o.mean)} ${s.unit}`);
      const room = (l, r) => { const L = tL.node().getComputedTextLength(), R_ = g.w - tR.node().getComputedTextLength(); return l > L + 8 && r < R_ - 8; };
      if (!room(a0, a1)) [a0, a1] = put(`med. ${nb(o.med)} ${s.unit}`);
      if (a0 < tL.node().getComputedTextLength() + 8) tL.remove();
      if (a1 > g.w - tR.node().getComputedTextLength() - 8) tR.remove();
      hover(gg.selectAll('.hh').data(o.hist).join('rect').attr('class', 'hit').attr('x', (n, k) => xx(E[k])).attr('width', (n, k) => xx(E[k + 1]) - xx(E[k])).attr('y', top).attr('height', base - top),
        (n, k) => `<b>${s.k}</b>${row(s.unit === 'd' ? 'length' : 'rain', s.unit === 'd' ? `${f0(E[k] + .5)} d` : `${f0(E[k])} to ${f0(E[k + 1])} mm`)}${row('windows', `${n} of ${M.n}`)}`);
    });
    legend('l-strip', [['', C('--text-muted'), '9-day windows, 1996–2025'], ['', C('--down'), '2026 bin'], ['dash', '', 'median']]);
    readout('r-strip', `starts ${M.starts}, 30 summers`);
    $('t-wx2').innerHTML = `<b>Rain has a memory</b>: after a rainy day, the next day is rainy ${f0(pww * 100)}% of the time, against ${f0(pwd * 100)}% after a dry day. Fine weather therefore comes in streaks, rain in episodes. On the dry streak I was a little lucky, but not that much: ${M.dry.v} dry days in a row, percentile ${f0(M.dry.pct)}; ${f0(M.dry.ge / M.n * 100)}% of 9-day windows have as many or more. The final episode, on the other hand, was rare: <b>percentile ${f0(M.max3.pct)}</b>, almost 9 summers out of 10 do not have three days that wet. Yet this timing worked in my favour despite the rain: it came at the end, when I had almost reached the coast. Luck or decision: we will see in part 09.`;
  }

  /* ---------- 07 · weather vs benchmark ---------- */
  function drawWx() {
    const Dd = W_.days;
    const m = { t: 14, r: 50, b: 26, l: 8 };
    const f = frame('c-rain', m);
    const x = d3.scaleLinear().domain([.6, 9.4]).range([0, f.w]);
    const y = d3.scaleLinear().domain([0, Math.max(W_.total_rain, W_.climato.pluie_mm) * 1.12]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${v} mm`);
    xAxis(f.g, x, f.h, 9, dayLbl);
    const bw = Math.min(14, f.w / 30);
    f.g.selectAll('.rb').data(Dd).join('path').attr('d', d => barPath(x(d.day) - bw / 2, y(0), bw, y(d.rain), 1.5)).attr('fill', C('--text-muted')).attr('fill-opacity', .45);
    // fine interpolation so the excess / deficit areas meet exactly where the lines cross
    const fine = []; for (let i = 0; i < Dd.length - 1; i++) for (let k = 0; k < 20; k++) { const u = k / 20, a = Dd[i], b = Dd[i + 1]; fine.push({ d: a.day + u, r: a.cum_rain + (b.cum_rain - a.cum_rain) * u, n: a.cum_norm + (b.cum_norm - a.cum_norm) * u }); }
    fine.push({ d: Dd[Dd.length - 1].day, r: Dd[Dd.length - 1].cum_rain, n: Dd[Dd.length - 1].cum_norm });
    f.g.append('path').attr('d', d3.area().x(p => x(p.d)).y0(p => y(p.n)).y1(p => y(Math.max(p.r, p.n)))(fine)).attr('fill', C('--down')).attr('fill-opacity', .28);
    f.g.append('path').attr('d', d3.area().x(p => x(p.d)).y0(p => y(p.n)).y1(p => y(Math.min(p.r, p.n)))(fine)).attr('fill', C('--up')).attr('fill-opacity', .2);
    const line = k => d3.line().x(d => x(d.day)).y(d => y(d[k]));
    f.g.append('path').attr('d', line('cum_norm')(Dd)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.4).attr('stroke-dasharray', '5 4');
    f.g.append('path').attr('d', line('cum_rain')(Dd)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 2);
    const last = Dd[Dd.length - 1];
    axTag(f.g, f.w + 2, y(last.cum_rain), f1(last.cum_rain)).select('rect').attr('fill', C('--accent'));
    axTag(f.g, f.w + 2, y(last.cum_norm), f1(last.cum_norm));
    hideUnder(f.g, [y(last.cum_rain), y(last.cum_norm)]);
    // repère sur 1 200 fenêtres de 9 jours (risque_meteo.js), dans l'espace libre en haut à gauche
    const MM = window.RISK_METEO;
    if (MM) {
      const bx = f.g.append('g').attr('transform', 'translate(6,4)');
      bx.append('text').attr('class', 'lbl').attr('y', 10).text(f.narrow ? `9-day total · ${f0(MM.n)} windows` : `9-day total · ${f0(MM.n)} windows 1996–2025 · central point`);
      bx.append('text').attr('class', 'lbl-strong').attr('y', 27).text(`median ${f1(MM.tot.med)} mm · mean ${f1(MM.tot.mean)} mm`);
      bx.append('text').attr('class', 'lbl-ink').attr('y', 43).text(`2026: percentile ${f0(MM.tot.pct)}`);
    }
    const ch = crossH(f);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h).on('pointermove', ev => {
      const d = Dd[Math.max(0, Math.min(8, Math.round(x.invert(d3.pointer(ev)[0])) - 1))];
      ch.show(x(d.day), y(d.cum_rain), f1(d.cum_rain));
      showTip(ev, `<b>${dayLbl(d.day)} · ${dateLbl(d.date)}</b>${row('daily rain', `${f1(d.rain)} mm`)}${row('actual total', `${f1(d.cum_rain)} mm`)}${row('normal total', `${f1(d.cum_norm)} mm`)}${row('deviation', `${fs1(d.cum_rain - d.cum_norm)} mm`)}${row('temperatures', `${f1(d.tmin)} to ${f1(d.tmax)} °C`)}`);
    }).on('pointerleave', () => { ch.hide(); hideTip(); });
    legend('l-rain', [['ln', C('--accent'), 'actual total'], ['dash', '', '1996–2025 normal'], ['', C('--down'), 'surplus'], ['', C('--up'), 'deficit'], ['', C('--text-muted'), 'daily rain']]);
    readout('r-rain', `actual <b>${f1(W_.total_rain)} mm</b> · normal <b>${f1(W_.climato.pluie_mm)}</b> · <b class="d">${fs0((W_.total_rain / W_.climato.pluie_mm - 1) * 100)}%</b>`);

    const g = frame('c-gust', { t: 14, r: 50, b: 26, l: 8 });
    const xg = x.copy().range([0, g.w]);
    const yg = d3.scaleLinear().domain([0, 90]).range([g.h, 0]);
    yGrid(g.g, yg, g.w, 4, v => `${v}`);
    xAxis(g.g, xg, g.h, 9, dayLbl);
    const ref = W_.climato.rafale;
    const fineG = []; for (let i = 0; i < Dd.length - 1; i++) for (let k = 0; k < 20; k++) { const u = k / 20; fineG.push({ d: Dd[i].day + u, v: Dd[i].gust + (Dd[i + 1].gust - Dd[i].gust) * u }); }
    fineG.push({ d: 9, v: Dd[8].gust });
    g.g.append('path').attr('d', d3.area().x(p => xg(p.d)).y0(yg(0)).y1(p => yg(p.v))(fineG)).attr('fill', C('--accent')).attr('fill-opacity', .08);
    g.g.append('path').attr('d', d3.area().x(p => xg(p.d)).y0(yg(ref)).y1(p => yg(Math.max(ref, p.v)))(fineG)).attr('fill', C('--down')).attr('fill-opacity', .35);
    g.g.append('path').attr('d', d3.line().x(d => xg(d.day)).y(d => yg(d.gust))(Dd)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 1.8);
    g.g.selectAll('.gd').data(Dd).join('circle').attr('cx', d => xg(d.day)).attr('cy', d => yg(d.gust)).attr('r', 3).attr('fill', d => d.gust > ref ? C('--down') : C('--accent')).attr('stroke', C('--bg')).attr('stroke-width', 1.2);
    g.g.append('line').attr('x1', 0).attr('x2', g.w).attr('y1', yg(ref)).attr('y2', yg(ref)).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2).attr('stroke-dasharray', '5 4');
    axTag(g.g, g.w + 2, yg(ref), `${ref}`);
    hideUnder(g.g, [yg(ref)]);
    hover(g.g.selectAll('.gh').data(Dd).join('rect').attr('class', 'hit').attr('x', d => xg(d.day - .5)).attr('width', xg(1.6) - xg(.6)).attr('y', 0).attr('height', g.h),
      d => `<b>${dayLbl(d.day)} · max gust ${d.gust} km/h</b>${row('reference for the period', `${ref} km/h`)}${row('deviation', `${fs0(d.gust - ref)} km/h`)}`);
    legend('l-gust', [['ln', C('--accent'), 'daily max gust (km/h)'], ['dash', '', 'normal max gust'], ['', C('--down'), 'exceedance']]);
    readout('r-gust', `max <b>${W_.gust_max} km/h</b> · days > ref. <b>${Dd.filter(d => d.gust > ref).length}</b>`);
    $('t-wx').textContent = `Six dry days, warmer than normal (${f1(W_.tmax_mean)} °C average max against ${f1(W_.climato.tmax)}), then ${f1(lateRain)} mm in three days, i.e. ${f0((lateRain / W_.climato.pluie_mm - 1) * 100)}% more than the normal for the whole period, with gusts up to ${W_.gust_max} km/h. The number of rainy days is normal (${W_.rainy_days}): it is their bunching at the end of the trip that created the risk.`;
  }

  /* ---------- 06 · les grecs du trek ---------- */
  function drawActe2() {
    const A = window.RISK_ACTE2, box = $('gk-grid'); if (!A || !box) return;
    const D = A.delta, G = A.gamma, V = A.vega, TH = A.theta, RH = A.rho, SW = A.sacWet;
    const pct = v => `${v >= 0 ? '+' : '−'}${Math.abs(v) < 1 ? f1(Math.abs(v)) : f0(Math.abs(v))}%`, d2 = v => f2(v);
    const sgn = m => `${m >= 0 ? '+' : '−'}${Math.abs(m) < 60 ? `${Math.abs(m)} min` : hm(Math.abs(m) / 60)}`;
    const hN = TH.horizon[TH.horizon.length - 1], h1 = TH.horizon[0];
    const ns = t => Math.abs(t) < 1.96 ? ' <span class="gk-ns">n.s.</span>' : '';
    const big = G.steps[1];
    const cards = [
      { k: 'delta', dq: 'How much does my time move when the terrain goes up one level?', l: 'Δ', n: 'Delta', q: 'the terrain',
        tr: `The terrain is my “asset”: when it gets harder, my time goes up. On average, one more grade level costs <b>${pct(D.cote)}</b> of time, a steep descent ${pct(D.desc)}, all else being equal (part 04).`,
        fi: ['Δ = ∂V / ∂S', 'How much the option price V moves when the asset price S rises by one unit.'] },
      { k: 'gamma', dq: 'Is the cost of a terrain level the same at every level?', l: 'Γ', n: 'Gamma', q: 'the terrain jump',
        tr: `No: the delta changes with the place. From easy to moderate, ${pct(G.steps[0].pct)} only. Then <b>${pct(big.pct)} at once</b> on moving to demanding, where the trail disappears. Then ${pct(G.steps[2].pct)} up to expert. The cost of terrain comes in one jump.`,
        fi: ['Γ = ∂²V / ∂S²', 'How much the delta itself moves when the price rises by one unit. A strong gamma: the price reacts much more in some places than in others.'] },
      { k: 'vega', dq: 'How much does my pace vary from one segment to the next, and what makes it vary?', l: 'ν', n: 'Vega', q: 'the unpredictable',
        tr: `I manage my effort over the whole route. On steep climbs, my engine decides, and the pace is <b>steady</b> (${d2(V.mont.b)} vs ${d2(V.mont.a)} elsewhere). Elsewhere, the terrain slows me or is runnable. Without the pack, I run when it is runnable: more alternation (${d2(V.sac.a)} vs ${d2(V.sac.b)} with the pack). The heart confirms it: with the pack, it keeps the same rhythm whether I move fast or slow; without it, it follows the pace.`,
        fi: ['ν = ∂V / ∂σ', 'How much the price moves when volatility σ, the size of the price swings, rises by one point.'] },
      { k: 'theta', dq: 'How wrong is my forecast when it looks one day further ahead?', l: 'Θ', n: 'Theta', q: 'the horizon',
        tr: `Seen from the evening of D${TH.origin}, the fair-weather forecast is ${sgn(-h1.lo)} / ${sgn(h1.hi)} for the next day, but <b>${sgn(-hN.lo)} / ${sgn(hN.hi)}</b> for D${hN.day}. My arrival: <b>${sgn(TH.real_end)}</b>, at the top of the range. Without the chaining of deviations, it would stop at ${sgn(hN.n_hi)} and I would have been outside it.`,
        fi: ['Θ = ∂V / ∂t', 'How much the price moves when one day passes, all else equal. The uncertainty on the price, for its part, grows with the time left, like σ√T.'] },
      { k: 'rho', dq: 'How much does my time move when I carry my camp on my back?', l: 'ρ', n: 'Rho', q: 'the carry',
        tr: `Carrying my camp has a cost, paid at every step: <b>${pct(RH.sac)}</b> of time with the pack, on equal terrain (part 04). The pack gets lighter over the days, but fatigue makes up for it: its cost does not clearly fall. And I never carried it on expert terrain: demanding was enough.`,
        fi: ['ρ = ∂V / ∂r', 'How much the price moves when the interest rate r rises by one point: the cost of carrying the position over time.'] },
      { k: 'second', dq: 'When it rains, does the pack still cost as much?', l: '∂²', n: 'Second order', q: 'pack × rain',
        tr: `A second-order effect measures how the effect of one factor changes when another changes. Here: the pack, depending on the weather. In the dry it costs me <b>${pct(SW.sac_dry)}</b>; in the rain, only <b>${pct(SW.sac_wet)}</b>. Without the pack, I run as soon as it is runnable; in the rain I no longer run: the gap with the pack narrows.`,
        fi: ['∂²V / ∂r ∂S', 'A cross derivative: how much the sensitivity to one input moves when another moves. Here, how much the cost of carrying moves when the weather changes.'] },
    ];
    cards.forEach(c => { DEFS['gk_' + c.k] = { t: `${c.n}: the definition in finance`, html: () => `<div class="def-f">${c.fi[0]}</div><p>${c.fi[1]}</p>` }; });
    box.innerHTML = cards.map(c => `<div class="pc gk-card concept"><div class="pc-head"><span class="gk-l">${c.l}</span><span class="pc-t"><span class="ck">${c.n}</span><span class="ck-sub">${c.q}</span>${defBtn('gk_' + c.k)}</span></div>
      <div class="gk-body"><p class="gk-dq">${c.dq}</p><p class="gk-tr">${c.tr}</p></div>
      <div class="chart gk-c" id="c-gk-${c.k}" data-h="${c.k === 'theta' ? 130 : 110}"></div></div>`).join('');
    const lab = (g, x, y, t, a = 'middle', cls = 'ax-title') => g.append('text').attr('class', cls).attr('x', x).attr('y', y).attr('text-anchor', a).text(t);
    const bars = (id, vals, names, col, opt = {}) => {
      const f = frame(id, { t: 16, r: 8, b: 18, l: 8 });
      const x = d3.scaleBand().domain(names).range([0, f.w]).padding(.28), y = d3.scaleLinear().domain([0, d3.max(vals) * 1.15 || 1]).range([f.h, 0]);
      if (opt.ref != null) { f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(opt.ref)).attr('y2', y(opt.ref)).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3'); lab(f.g, 0, -4, opt.refLab, 'start'); }
      vals.forEach((v, i) => {
        const dim = opt.dim && opt.dim[i];
        f.g.append('rect').attr('x', x(names[i])).attr('width', x.bandwidth()).attr('y', y(v)).attr('height', f.h - y(v)).attr('rx', 2).attr('fill', col).attr('fill-opacity', dim ? .3 : .85);
        const inside = f.h - y(v) > 18;
        lab(f.g, x(names[i]) + x.bandwidth() / 2, inside ? y(v) + 12 : y(v) - 4, `+${f0(v)}%${dim ? ' n.s.' : ''}`, 'middle', inside && !dim ? 'ax-title gk-in' : 'ax-title');
        lab(f.g, x(names[i]) + x.bandwidth() / 2, f.h + 13, names[i]);
      });
    };
    bars('c-gk-delta', [D.cote, D.desc], ['one grade level', 'steep descent'], C('--critical'));
    bars('c-gk-gamma', G.steps.map(s => s.pct), ['→ moderate', '→ demanding', '→ expert'], C('--critical'), { ref: D.cote, refLab: `- - average delta: +${f0(D.cote)}% per level`, dim: G.steps.map(s => Math.abs(s.t) < 1.96) });
    { // vega : paires d'écarts-types
      const f = frame('c-gk-vega', { t: 12, r: 12, b: 16, l: 44 });
      const rowsV = [['slope', 'elsewhere', 'steep climb', V.mont], ['pack', 'without', 'with', V.sac]];
      const x = d3.scaleLinear().domain([.2, .38]).range([0, f.w]), y = d3.scaleBand().domain(rowsV.map(r => r[0])).range([0, f.h]).padding(.3);
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(3).tickSize(0).tickPadding(5).tickFormat(d2));
      rowsV.forEach(([k, a, b, v]) => {
        const cy = y(k) + y.bandwidth() / 2;
        lab(f.g, -8, cy + 3, k, 'end');
        f.g.append('line').attr('x1', x(v.a)).attr('x2', x(v.b)).attr('y1', cy).attr('y2', cy).attr('stroke', C('--hair')).attr('stroke-width', 3);
        f.g.append('circle').attr('cx', x(v.a)).attr('cy', cy).attr('r', 4).attr('fill', C('--text-muted'));
        f.g.append('circle').attr('cx', x(v.b)).attr('cy', cy).attr('r', 4).attr('fill', C('--accent'));
        const left = v.a < v.b;
        lab(f.g, x(v.a), cy - 8, a, left ? 'start' : 'end');
        lab(f.g, x(v.b), cy - 8, b, left ? 'end' : 'start');
      });
    }
    { // thêta : deux fourchettes et la trajectoire réelle
      const f = frame('c-gk-theta', { t: 12, r: 58, b: 18, l: 8 }), P = TH.path;
      const x = d3.scaleLinear().domain([0, P.length - 1]).range([0, f.w]);
      const y = d3.scaleLinear().domain([d3.min(P, p => p.b5) * 1.05, Math.max(d3.max(P, p => p.b95), TH.real_end) * 1.08]).range([f.h, 0]);
      const ar = (lo, hi) => d3.area().x((p, i) => x(i)).y0(p => y(p[lo])).y1(p => y(p[hi]))(P);
      f.g.append('path').attr('d', ar('b5', 'b95')).attr('fill', C('--accent')).attr('fill-opacity', .2);
      f.g.append('path').attr('d', ar('n5', 'n95')).attr('fill', C('--accent')).attr('fill-opacity', .25);
      f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(0)).attr('y2', y(0)).attr('stroke', C('--accent')).attr('stroke-dasharray', '3 3');
      f.g.append('path').attr('d', d3.line().x((p, i) => x(i)).y(p => y(p.real))(P)).attr('fill', 'none').attr('stroke', C('--down')).attr('stroke-width', 1.8);
      const ends = {}; P.forEach((p, i) => { ends[p.d] = i; });
      Object.entries(ends).forEach(([d, i]) => lab(f.g, x(i), f.h + 13, dayLbl(d), 'end'));
      lab(f.g, f.w + 4, y(TH.real_end) + 3, sgn(TH.real_end), 'start').attr('fill', C('--down'));
      lab(f.g, f.w + 4, y(P[P.length - 1].b95) - 6, 'blocks', 'start');
      lab(f.g, f.w + 4, y(P[P.length - 1].n95) + 10, 'normal', 'start');
    }
    { // rho : une heure sans sac, avec sac
      const f = frame('c-gk-rho', { t: 8, r: 10, b: 8, l: 64 }), x = d3.scaleLinear().domain([0, 1 + RH.hi / 100]).range([0, f.w]);
      const yb = d3.scaleBand().domain(['no pack', 'with pack']).range([0, f.h]).padding(.32);
      [['no pack', 1, C('--series-sans')], ['with pack', 1 + RH.sac / 100, C('--series-avec')]].forEach(([k, v, col]) => {
        f.g.append('rect').attr('x', 0).attr('width', x(v)).attr('y', yb(k)).attr('height', yb.bandwidth()).attr('rx', 2).attr('fill', col).attr('fill-opacity', .8);
        lab(f.g, -8, yb(k) + yb.bandwidth() / 2 + 3, k, 'end');
        lab(f.g, x(v) - 6, yb(k) + yb.bandwidth() / 2 + 3, hm(v), 'end', 'ax-title gk-in');
      });
    }
    { // second ordre : le coût du sac, au sec et sous la pluie
      const f = frame('c-gk-second', { t: 14, r: 40, b: 8, l: 56 });
      const vals = [['dry', SW.sac_dry], ['rain', SW.sac_wet]], x = d3.scaleLinear().domain([0, d3.max(vals, v => v[1]) * 1.1]).range([0, f.w]);
      const yb = d3.scaleBand().domain(vals.map(v => v[0])).range([0, f.h]).padding(.32);
      f.g.append('line').attr('x1', x(RH.sac)).attr('x2', x(RH.sac)).attr('y1', -4).attr('y2', f.h).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3');
      lab(f.g, x(RH.sac), -5, `average ${pct(RH.sac)}`);
      vals.forEach(([k, v], i) => {
        f.g.append('rect').attr('x', 0).attr('width', x(v)).attr('y', yb(k)).attr('height', yb.bandwidth()).attr('rx', 2).attr('fill', C('--series-avec')).attr('fill-opacity', i ? .45 : .85);
        lab(f.g, -8, yb(k) + yb.bandwidth() / 2 + 3, k, 'end');
        lab(f.g, x(v) + 5, yb(k) + yb.bandwidth() / 2 + 3, `+${f0(v)}%`, 'start');
      });
    }
    $('t-gk').innerHTML = `Terrain costs mostly when the trail disappears (<b>${pct(big.pct)} at once</b>). The pack costs <b>${pct(RH.sac)}</b> on average (${pct(SW.sac_dry)} in the dry, ${pct(SW.sac_wet)} in the rain) but makes my pace steadier. And my arrival falls at the edge of the range: it is the chaining of deviations, which the simulation will measure.`;
    DEFS.grecs = { t: 'The Greeks: where they come from, how they are measured here', html: () => `
      <p><b>The origin.</b> In 1973, <b>Fischer Black and Myron Scholes</b> gave a formula for the price of an option. This price depends on a few inputs: the asset price, its volatility, the time left, the interest rate. Traders name the sensitivity of the price to each input with a Greek letter: these are derivatives. Every evening, a desk explains its P&amp;L Greek by Greek.</p>
      <div class="def-f">Δ = ∂V/∂S · Γ = ∂²V/∂S² · ν = ∂V/∂σ · Θ = ∂V/∂t · ρ = ∂V/∂r</div>
      <p><b>Here.</b> The “price” is my walking time. <b>Δ</b> and <b>ρ</b> are the effects of part 04 (regression on ${A.n} segments): the terrain is the underlying, the pack the cost of carry. <b>Γ</b>: the same regression, with an effect for each grade level; the moderate → demanding step holds even when any single outing is removed (t ≥ ${f1(G.loo_tmin)}). <b>ν</b>: the standard deviation of what the regression does not explain (${d2(V.all)} overall), compared between groups with a permutation test. <b>Θ</b>: the 90% ranges of the simulation in part 07. <b>Second order</b>: ${SW.scanned} pairs of factors screened, one at a time. On the heart side, the regression in the part 04 box: the pace deviation moves heart rate without the pack (${f0(window.RISK_FC.e_trail.b)} bpm per unit of deviation), not with it (${fs0(window.RISK_FC.e_sac.b)}, n.s.); the difference holds when any single outing is removed (t from ${f1(window.RISK_FC.inter.loo_t[0])} to ${f1(window.RISK_FC.inter.loo_t[1])}).</p>
      <p class="muted">Limits: with ${SW.scanned} pairs tested, a result can come out by chance; pack × rain holds when any single outing is removed (t from ${f1(SW.t_loo[1])} to ${f1(SW.t_loo[0])}), but rests on ${SW.n_out} outings with the pack in the rain. Not kept: rain weighing more on hard terrain (t = ${f1(A.vanna.t)}), terrain learnt over the days (t = ${f1(A.charm.t)}). Rain is not in the part 04 regression: its delta (${pct(D.pluie)}) comes from part 03.</p>` };
    const gb = $('gk-btn'); if (gb && !gb.innerHTML) gb.innerHTML = defBtn('grecs', 'Where the Greeks come from');
  }

  /* ---------- 07 (fin) · le jour de marge, évalué comme une option ---------- */
  function drawMarge() {
    const G = window.RISK_MARGE; if (!G || !$('c-mg')) return;
    const CV = G.curve, c0 = CV[0], wet = CV.find(c => c.day === 7), c6 = CV.find(c => c.day === 6), M = G.M_min;
    const mn = m => m < 60 ? `${m} min` : hm(m / 60);
    { // ce que la marge doit absorber, soir après soir
      const f = frame('c-mg', { t: 14, r: 64, b: 26, l: 8 });
      const x = d3.scalePoint().domain(CV.map(c => c.day)).range([0, f.w]).padding(.2), y = d3.scaleLinear().domain([0, M * 1.12]).range([f.h, 0]);
      const x7 = x(7) - x.step() / 2;
      f.g.append('rect').attr('x', x7).attr('width', f.w - x7).attr('y', 0).attr('height', f.h).attr('fill', C('--text-muted')).attr('fill-opacity', .1).attr('rx', 4);
      f.g.append('text').attr('class', 'ax-title').attr('x', x7 + 6).attr('y', 10).text('rainy days');
      yGrid(f.g, y, f.w, 4, v => `${v} min`);
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).tickSize(0).tickPadding(9).tickFormat(d => f.narrow ? `D${d}` : `evening D${d}`));
      f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(M)).attr('y2', y(M)).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '5 4');
      axTag(f.g, f.w + 2, y(M), mn(M));
      hideUnder(f.g, [y(M)]);
      [['blocs', C('--text-muted'), 1.4], ['clim', C('--accent'), 2.2]].forEach(([k, col, w]) => {
        f.g.append('path').attr('d', d3.line().x(c => x(c.day)).y(c => y(c[k].value))(CV)).attr('fill', 'none').attr('stroke', col).attr('stroke-width', w);
        f.g.selectAll(null).data(CV).join('circle').attr('cx', c => x(c.day)).attr('cy', c => y(c[k].value)).attr('r', k === 'clim' ? 3.2 : 2.4).attr('fill', col);
      });
      f.g.append('text').attr('class', 'ax-title').attr('x', x(CV[0].day)).attr('y', y(c0.clim.value) - 9).attr('text-anchor', 'start').text(mn(c0.clim.value));
      f.g.append('text').attr('class', 'ax-title').attr('x', x(7) - 6).attr('y', y(wet.clim.value) - 8).attr('text-anchor', 'end').text(mn(wet.clim.value));
      hover(f.g.selectAll('.mh').data(CV).join('rect').attr('class', 'hit').attr('x', c => x(c.day) - x.step() / 2).attr('width', x.step()).attr('y', 0).attr('height', f.h),
        c => `<b>Evening of D${c.day}${c.wet ? ' · rain' : ''}</b>${row('behind schedule', `${c.dev >= 0 ? '+' : '−'}${mn(Math.abs(c.dev))}`)}${row('to absorb, simulation', mn(c.clim.value))}${row('to absorb, Black-Scholes', mn(c.clim.black))}${row('chance of being used', `${f0(c.clim.p_use)}%`)}`);
      legend('l-mg', [['ln', C('--accent'), 'with the climate'], ['ln', C('--text-muted'), 'fair weather only'], ['dash', '', 'the whole margin']]);
      readout('r-mg', `margin <b>${mn(M)}</b> · used <b>${mn(G.used_min)}</b>`);
    }
    $('mg-lede').innerHTML = `The plan kept a day “in reserve (weather or fitness)”: Støvla, about <b>${mn(M)}</b> of walking. Any delay against the schedule comes out of this day. In finance, it is an option: the simulation gives its price, in minutes.`;
    $('mg-greeks').innerHTML = [
      ['Δ', 'Delta', `If the forecast slips by an hour, the margin has to absorb <b>${f0(G.greeks.delta * 60)} min</b> more.`],
      ['ν', 'Vega', `More uncertainty changes almost nothing (<b>${G.greeks.vega_10 > 0 ? '+' : '−'}${f0(Math.abs(G.greeks.vega_10))} min</b> for +10%): on the evening of D2, the margin already has a ${f0(c0.clim.p_use)}% chance of being used.`],
      ['Θ', 'Theta', `Each dry evening, it melts by <b>${f0(-G.theta.per_day)} min</b>: ${mn(c0.clim.value)} on D2, ${mn(c6.clim.value)} on D6. The rain on D7 pushes it back up to ${mn(wet.clim.value)}.`],
    ].map(([l, n, t]) => `<div><h4><span class="gk">${l}</span> ${n}</h4><p>${t}</p></div>`).join('');
    $('mg-read').textContent = `Each evening, what the margin should expect to absorb, with and without the climate; dotted: the whole margin.`;
    $('t-mg').innerHTML = `On D2, the margin has to absorb <b>${mn(c0.clim.value)}</b> out of ${mn(M)}, with a ${f0(c0.clim.p_use)}% chance of being used. It melts in dry weather, rain pushes it back up. At the finish, <b>${mn(G.used_min)}</b> were used (${f0(G.used_min / M * 100)}%): it held, and the midnight sun did the rest for Støvla.`;
    DEFS.blackscholes = { t: 'Black-Scholes and Monte Carlo: the price of an insurance', html: () => `
      <p><b>The origin.</b> In 1973, <b>Fischer Black, Myron Scholes and Robert Merton</b> found the “fair” price of an option: the right, but not the obligation, to buy an asset at a price set in advance (the strike K). Merton and Scholes received the Nobel prize in economics in 1997. In 1976, Black adapted the formula to a forward price F, known today for a future date. In 1977, <b>Phelim Boyle</b> showed that this price can also be found by Monte Carlo: simulate thousands of futures, and average what the option pays. It is how banks do it when the future does not follow the formula’s distribution.</p>
      <div class="def-f">call = F·N(d₁) − K·N(d₂) · d₁ = [ln(F/K) + s²/2] / s · d₂ = d₁ − s</div>
      <p>N is the normal distribution, s the uncertainty left until expiry. A capped insurance, paying the excess over K up to K + M, is the difference of two calls: a <i>call spread</i>.</p>
      <div class="def-ex"><b>Here.</b> The asset: my walking time from D3 to D9, <b>without Støvla</b> (it is the margin, it is not counted twice). The strike K: the D2 evening forecast at my fair-weather pace, ${hm(G.K)}, i.e. the schedule. The margin M: Støvla converted to my trail pace, ${mn(M)} (${f1(G.margin.km)} km, ${f0(G.margin.dplus)} m of D+). Payoff: the excess over K, capped at M. Price on D2: <b>${mn(G.value_j2.sim)}</b> by the simulation with the climate, ${mn(G.value_j2.black)} by the formula, ${mn(G.value_j2.beau_temps)} if the rain is ignored. Each evening, what has already been walked is replaced by the actual, and only the worlds whose weather that day matches mine are kept.</div>
      <p><b>The skew.</b> To match the simulated prices, the formula has to assume more uncertainty the larger the delay considered (from ${hm(G.smile[0].sd_h)} to ${hm(G.smile[G.smile.length - 1].sd_h)}): big delays are more likely than a lognormal distribution says. That is the rain, which comes in streaks; on equity markets, the same slope comes from crashes.</p>
      <p><b>Robustness.</b> Depending on the simulation choices (cost of rain from part 03 or measured, blocks of 1 to 4 km, worlds kept, draws), the margin has to absorb between ${mn(G.sens.value_min)} and ${mn(G.sens.value_max)} on D2, with a ${f0(G.sens.use_min)} to ${f0(G.sens.use_max)}% chance of being used. On the other hand, the chance of it being <b>exhausted</b> depends on the size given to it: ${G.sens.by_M.map(b => `${f0(b.p_out)}% for ${mn(b.M_min)}`).join(', ')}. So it is not a result, and it is not shown.</p>
      <p class="muted">Limits. A reserve day is not a fixed number of minutes: under the midnight sun, a day has no end time, and Støvla (${mn(G.stvla_real_min)}) was done despite ${mn(G.used_min)} of delay. The “price” here is the expected excess, not an arbitrage price: a trek cannot be hedged by buying and selling. The cost of rain is measured afterwards (part 07, stress test).</p>` };
    const b = $('mg-btn'); if (b && !b.innerHTML) b.innerHTML = defBtn('blackscholes', 'Black-Scholes and Monte Carlo: the price of an insurance');
  }

  /* ---------- 07 · Monte Carlo ---------- */
  let mcModel = 'clim', mcPlayed = false, mcRaf = 0;
  const MCL = { clim: 'with the climate', blocs: 'fair weather only' };
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  function drawMc(animate = false) {
    const K = MC.seg_km, other = mcModel === 'clim' ? 'blocs' : 'clim';
    const M = MC[mcModel].seg, O = MC[other].seg;
    const el = $('c-mc'), narrow = el.clientWidth < 560;
    const histW = narrow ? 64 : 150;
    const m = { t: 22, r: histW + (narrow ? 34 : 132), b: 34, l: 46 };
    const f = frame('c-mc', m);
    const x = d3.scaleLinear().domain([0, K[K.length - 1]]).range([0, f.w]);
    const lastR = MC.real_dev[MC.real_dev.length - 1];
    const hiL = Math.ceil(Math.max(M.term[6], O.term[6], lastR) + .6), loL = Math.ceil(Math.max(-M.term[0], -O.term[0], -lastR) + .6);
    const y = d3.scaleLinear().domain([-loL, hiL]).range([f.h, 0]);
    dayBands(f.g, x, f.h);
    // J1–J2 : période de calage, hors simulation
    f.g.append('rect').attr('x', 0).attr('width', x(K[0])).attr('y', 0).attr('height', f.h).attr('fill', C('--text-muted')).attr('opacity', .09);
    f.g.append('text').attr('class', 'lbl-strong').attr('x', x(K[0]) / 2).attr('y', f.h - 26).attr('text-anchor', 'middle').text(narrow ? 'calibration' : `D1–D${MC.origin}: model calibration`);
    if (!narrow) f.g.append('text').attr('class', 'lbl').attr('x', x(K[0]) / 2).attr('y', f.h - 11).attr('text-anchor', 'middle').text(`${MC.cal_n} segments known by evening D${MC.origin}`);
    yGrid(f.g, y, f.w, 7, v => `${v > 0 ? '+' : ''}${v} h`, 'left');
    xAxis(f.g, x, f.h, narrow ? 4 : 8, v => `${v} km`);
    f.g.append('line').attr('class', 'zero').attr('x1', 0).attr('x2', f.w + histW + 8).attr('y1', y(0)).attr('y2', y(0));
    const col = d3.scaleLinear().domain([-loL * .8, 0, hiL * .6]).range([C('--div-neg'), C('--text-muted'), C('--div-pos')]).interpolate(d3.interpolateLab).clamp(true);
    const pg = f.g.append('g');
    const band = (lo, hi) => d3.area().x((v, i) => x(K[i])).y0((v, i) => y(lo[i])).y1((v, i) => y(hi[i])).curve(d3.curveMonotoneX)(lo);
    const bandG = pg.append('g');   // percentile bands: they appear once the simulations are in
    bandG.append('path').attr('d', band(M.bands['5'], M.bands['95'])).attr('fill', C('--accent')).attr('opacity', .1);
    bandG.append('path').attr('d', band(M.bands['25'], M.bands['75'])).attr('fill', C('--accent')).attr('opacity', .14);
    const line = a => d3.line().x((v, i) => x(K[i])).y(v => y(Math.max(-loL, Math.min(hiL, v))))(a);
    const pathG = pg.append('g');
    const simP = M.paths.map(p => pathG.append('path').attr('d', line(p)).attr('fill', 'none').attr('stroke', col(p[p.length - 1])).attr('stroke-width', .8).attr('opacity', .42));
    const lineG = pg.append('g');
    [['5', 1.6], ['95', 1.6], ['1', 1], ['99', 1]].forEach(([k, w]) => lineG.append('path').attr('d', line(M.bands[k])).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', w).attr('opacity', k === '1' || k === '99' ? .45 : .9));
    [O.bands['5'], O.bands['95']].forEach(a => lineG.append('path').attr('d', line(a)).attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.3).attr('stroke-dasharray', '5 4').attr('opacity', .9));
    const realP = pg.append('path').attr('d', line(MC.real_dev)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 2.6);
    // right margin: distribution of the arrival, rotated
    const hx = f.w + 10, H = M.hist, E = M.edges;
    const xh = d3.scaleLinear().domain([0, d3.max([...M.hist, ...O.hist])]).range([0, histW]);
    const hg = f.g.append('g').attr('transform', `translate(${hx},0)`);
    const bars = hg.selectAll('.mh').data(H.map((n, i) => ({ n, a: E[i], b: E[i + 1] })).filter(d => d.b > -loL && d.a < hiL)).join('rect')
      .attr('y', d => y(Math.min(hiL, d.b)) + .5).attr('height', d => Math.max(.5, y(Math.max(-loL, d.a)) - y(Math.min(hiL, d.b)) - 1)).attr('x', 0).attr('rx', 1.5)
      .attr('width', d => animate ? 0 : xh(d.n)).attr('fill', d => col((d.a + d.b) / 2)).attr('opacity', .9);
    const cmpH = hg.append('path').attr('d', d3.line().curve(d3.curveStepAfter).x(d => xh(d.n)).y(d => y(d.a))(O.hist.map((n, i) => ({ n, a: E[i] })).filter(d => d.a >= -loL && d.a < hiL)))
      .attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.2).attr('stroke-dasharray', '4 3').attr('opacity', .9);
    const tags = [[M.term[5], `P95 ${F('+.1f')(M.term[5])} h`, 'lbl-ink'], [M.es95, `worst 5% ${F('+.1f')(M.es95)} h`, 'lbl-strong'], [M.term[1], `P5 ${F('+.1f')(M.term[1])} h`, 'lbl-ink']];
    const tagG = hg.append('g');
    if (!narrow) tags.forEach(([v, t, c], i) => {
      tagG.append('line').attr('x1', 0).attr('x2', histW + 6).attr('y1', y(v)).attr('y2', y(v)).attr('stroke', C('--text-primary')).attr('stroke-width', 1).attr('opacity', i === 1 ? .5 : .9);
      tagG.append('text').attr('class', `${c} mc-tag`).attr('x', histW + 10).attr('y', y(v) + (i === 1 ? -4 : 4)).text(t);
    });
    hg.append('text').attr('class', 'lbl').attr('x', 0).attr('y', -10).text(narrow ? 'finish' : 'distribution at the finish');
    const realL = f.g.append('g'), ex = x(K[K.length - 1]), ey = y(lastR);
    realL.append('circle').attr('cx', ex).attr('cy', ey).attr('r', 4.5).attr('fill', C('--text-primary')).attr('stroke', C('--bg')).attr('stroke-width', 1.5);
    realL.append('text').attr('class', 'lbl-ink').attr('x', ex - 10).attr('y', ey - 14).attr('text-anchor', 'end').style('paint-order', 'stroke').style('stroke', C('--bg')).style('stroke-width', '4px')
      .text(narrow ? `actual ${F('+.1f')(lastR)} h` : `actual: +${hm(mcLate)} · percentile ${cL(M.real_pct)}`);
    // crosshair
    const ch = f.g.append('line').attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).style('display', 'none');
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => {
        const i = d3.minIndex(K, k => Math.abs(k - x.invert(d3.pointer(ev)[0])));
        ch.style('display', null).attr('x1', x(K[i])).attr('x2', x(K[i]));
        const b = k => F('+.2f')(M.bands[k][i]);
        showTip(ev, `<b>km ${f1(K[i])} · ${dayLbl(MC.seg_day[i])}</b>${row('P95 / P5', `${b('95')} / ${b('5')} h`)}${row('P75 / P25', `${b('75')} / ${b('25')} h`)}${row(`${MCL[other]}, P95`, `${F('+.2f')(O.bands['95'][i])} h`)}${row('actual', `${F('+.2f')(MC.real_dev[i])} h`)}`);
      }).on('pointerleave', () => { ch.style('display', 'none'); hideTip(); });
    legend('l-mc', [['ln', C('--div-neg'), 'path ahead'], ['ln', C('--div-pos'), 'path behind'], ['', C('--accent') + ';opacity:.4', 'P5–P95 and P25–P75'],
      ['ln', C('--text-primary'), 'actual path'], ['dash', C('--warning'), `P5–P95 ${MCL[other]} (comparison)`]]);
    // animation: the simulations arrive one by one, faster and faster; each one runs the 159 km,
    // the counter and the arrival histogram fill as they land; then the percentiles and the real path
    cancelAnimationFrame(mcRaf);
    const cnt = $('mc-n'), fades = [bandG, lineG, cmpH, tagG, realL];
    const fullBars = () => bars.attr('width', d => xh(d.n));
    if (animate && !reduce) {
      const n = simP.length, T = 3800, len = simP.map(p => p.node().getTotalLength());
      const t0 = k => T * Math.pow(k / n, .55);          // gaps shrink: the run accelerates
      const run = k => 700 - 560 * (k / n);              // and each simulation crosses faster
      simP.forEach((p, k) => p.attr('stroke-dasharray', `${len[k]} ${len[k]}`).attr('stroke-dashoffset', len[k]).attr('opacity', 0));
      fades.forEach(g => g.attr('opacity', 0));
      const rl = realP.node().getTotalLength();
      realP.attr('stroke-dasharray', `${rl} ${rl}`).attr('stroke-dashoffset', rl);
      bars.attr('width', 0);
      const done = new Uint8Array(n), T0 = performance.now();
      const frame = now => {
        const t = now - T0; let landed = 0;
        for (let k = 0; k < n; k++) {
          if (done[k]) { landed++; continue; }
          const u = (t - t0(k)) / run(k);
          if (u < 0) continue;
          if (u >= 1) { done[k] = 1; landed++; simP[k].attr('stroke-dashoffset', 0).attr('stroke-dasharray', null).attr('opacity', .42).attr('stroke-width', .8); continue; }
          simP[k].attr('stroke-dashoffset', len[k] * (1 - d3.easeCubicOut(u))).attr('opacity', .95).attr('stroke-width', 1.4);
        }
        const frac = landed / n;
        cnt.textContent = f0(Math.round(frac * MC.ns));
        bars.attr('width', d => xh(d.n * frac));
        if (landed < n) { mcRaf = requestAnimationFrame(frame); return; }
        fullBars(); cnt.textContent = f0(MC.ns);
        fades.forEach((g, i) => g.transition().delay(i * 120).duration(500).attr('opacity', 1));
        realP.transition().delay(350).duration(1100).ease(d3.easeCubicInOut).attr('stroke-dashoffset', 0).on('end', () => realP.attr('stroke-dasharray', null));
      };
      mcRaf = requestAnimationFrame(frame);
    } else { fullBars(); cnt.textContent = f0(MC.ns); }
    // figures, backtest, stress test and text
    const B_ = MC.blocs.seg, C_ = MC.clim.seg, BT = MC.backtest, ST = MC.stress, SM = BT.summary, CL = MC.climate, SC = MC.sens_clim;
    const shm = v => `${v < 0 ? '−' : '+'}${hm(Math.abs(v))}`, pctW = v => `${f0(v)}%`;
    $('mc-lede').innerHTML = `On the evening of D2, I know two days of fair weather and the climate: it rains one day in three. A model fitted on these days replays the rest ${f0(MC.ns)} times, each with the weather of a real summer. The actual serves as judge.`;
    const mcRows = [
      ['Uncertainty about what follows', 'standard deviation of walking time D3–D9', hm(B_.term_sd), hm(C_.term_sd)],
      ['Bad scenario', 'delay exceeded in 1 traverse out of 20 (P95, the value at risk)', shm(B_.term[5]), shm(C_.term[5])],
      ['Very bad scenario', 'average delay in these worst 5% of traverses', shm(B_.es95), shm(C_.es95)],
      ['Where the actual falls', `percentile of the real traverse (${shm(mcLate)})`, cL(B_.real_pct), cL(C_.real_pct)],
    ].map(([t, d, b, c]) => `<tr><td><b>${t}</b><br><span class="muted">${d}</span></td><td class="n">${b}</td><td class="n"><b>${c}</b></td></tr>`).join('');

    // backtest, day by day: each evening the model is refitted on the days walked and forecasts the next one (table in the « ? »)
    const btTable = `<thead><tr><th>Day</th><th class="n">Chance of rain</th><th class="n">Range forecast the day before</th><th class="n">Actual</th><th class="n">Verdict</th></tr></thead><tbody>${BT.days.map(d => {
      const o = d.clim, out = d.real > o.p95 || d.real < o.p5;
      return `<tr><td style="white-space:nowrap">${dayLbl(d.day)}${d.wet ? ' <span class="muted">rain</span>' : ''}</td><td class="n muted">${pctW(d.p_wet)}</td><td class="n">${hm(o.p5)} – ${hm(o.p95)}</td><td class="n${out ? ' over' : ''}">${hm(d.real)}</td><td class="n ${out ? 'over' : 'muted'}">${out ? 'exceeded' : 'tenu'}</td></tr>`; }).join('')}</tbody>`;
    const S_ = SM.clim, Sb = SM.blocs, dayOk = BT.days.filter(d => d.real <= d.clim.p95 && d.real >= d.clim.p5).length;
    readout('r-bt', `check: <b>${S_.all.in90} outings out of ${S_.all.n}</b> within the range`);
    $('mc-story').innerHTML = [
      [C('--accent'), 'the climate', 'The model forecasts', `${f0(100 - CL.p_none)}%`, `chance, on the evening of D2, of at least one rainy day by D9 (${f1(CL.wet_mean)} on average). What it does not know: when, and how heavy.`],
      [C('--up'), 'the check', 'It holds, in the dry as in the rain', `${S_.all.in90} / ${S_.all.n}`, `outings within the range forecast the day before. Without the climate, the rain caught it off guard: ${Sb.wet.above95} outings out of ${Sb.wet.n} beyond the threshold.`],
      [C('--warning'), 'my bad luck', `${CL.real_wet} rainy days`, `${f0(CL.p_ge_real)}%`, `of worlds had as many or more. The actual ends at percentile ${cL(C_.real_pct)}: a slightly unlucky traverse, not an accident.`],
    ].map(([c, s_, t, v, tx]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><b class="v">${v}</b><p>${tx}</p></div>`).join('');
    $('mc-msg').innerHTML = `<b>The rain was not unpredictable.</b> It was likely; only its timing and its cost were not. A model that forgets the climate thinks it is safer than it is. What protects is the margin, valued below.`;

    // stress test
    const sc = Object.fromEntries(ST.scen.map(x => [x.label, x])), W = ST.worst, wd = W.start.split('-');
    $('st-intro').innerHTML = `A rainy day costs me <b>${fs0(ST.pct)}%</b> of time per segment (from ${fs0(ST.lo)} to ${fs0(ST.hi)}%), on equal terrain, slope and pack, measured on D7–D9. Each simulation draws this cost within the interval: I did not know how heavy it would be.`;
    $('st-cols').innerHTML = [
      [C('--accent'), 'fair weather only', 'The D2 model, without rain', hm(sc.sec.median), `The actual, ${hm(MC.real_tot)}, falls at percentile ${cL(sc.sec.real_pct)}: a very bad scenario.`],
      [C('--warning'), 'with the climate', `${f1(CL.wet_mean)} rainy day on average`, `${hm(sc.clim.median)} <small>${shm(sc.clim.delta)}</small>`, `The actual falls at percentile ${cL(sc.clim.real_pct)}: an ordinary traverse, a little unlucky.`],
      [C('--down'), 'the worst of summers', `${W.wet} rainy days out of ${W.days.length - MC.origin}`, `${hm(sc.pire.median)} <small>${shm(sc.pire.delta)}</small>`, `Start on ${+wd[2]}/${wd[1]}/${wd[0]}. One traverse in 20 exceeds ${hm(sc.pire.p95)}: the reserve day would not be enough, summits would have to be given up.`],
    ].map(([c, s_, t, v, tx]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><b class="v">${v}</b><p>${tx}</p></div>`).join('');

    // « ? » : d'où ça vient
    const cf = Object.fromEntries(MC.coef.map(c => [c.name, c]));
    DEFS.montecarlo = { t: 'Where Monte Carlo simulation comes from', html: () => `
      <p><b>The origin.</b> In 1946, at Los Alamos, the mathematician <b>Stanislaw Ulam</b>, convalescing, wondered what the chance of winning a game of solitaire was. The exact calculation was impossible; he had the idea of playing the game hundreds of times and counting the wins. With <b>John von Neumann</b>, he applied the idea to the path of neutrons, on the first computers. The code name came from the Monte Carlo casino, where Ulam’s uncle used to gamble.</p>
      <p><b>The principle.</b> When a result depends on many small chances that add up, it is not calculated: it is <b>replayed</b> thousands of times, and the spread of the results is examined.</p>
      <p><b>Here, four layers.</b></p>
      <p><b>1. A factor model</b>, fitted on the ${MC.cal_n} segments of D1–D${MC.origin} (the method of part 04, with only the data known that evening):</p>
      <p class="def-f">time = Tobler × pack × terrain × slope × rain × e<sup>u</sup></p>
      <p>That evening, it estimates: pack ${fs0(cf['pack on my back'].pct)}%, terrain ${fs0(cf['terrain (+1 level)'].pct)}% per grade level of the segment. These values differ from those of part 04, computed afterwards over nine days and with the grade of the outing: that is the price of a real forecast. The pack effect rests on a single outing without the pack (Volandstinden); it nevertheless held in dry weather.</p>
      <p><b>2. The noise u</b>, what the factors do not explain: <b>Bradley Efron</b>’s <i>bootstrap</i> (1979) resamples its own data at random instead of assuming a distribution; <b>Hans Künsch</b> (1989) draws consecutive <b>blocks</b> to keep their chaining (part 02). Here: real stretches of ${MC.block} segments (2 km), and the model re-estimated at each draw.</p>
      <p><b>3. The weather.</b> Each simulation draws a summer among the ${f0(CL.pool)} of the ${f0(CL.worlds)} ERA5 worlds (parts 05 and 09) whose D2 is dry, like mine: the persistence of rain (part 05) does the rest. A rainy day (at least 1 mm) costs ${fs0(CL.rain_pct)}% of time, drawn between ${fs0(CL.rain_lo)} and ${fs0(CL.rain_hi)}%. The probability of rain was known before leaving; its cost is only measured afterwards.</p>
      <p><b>4. The simulation</b>: the ${MC.fut_n} segments of D3 to D9 are replayed ${f0(MC.ns)} times on the route actually followed (including the Kvalvika one, left out of the measurements: it is replayed with the slope of its neighbours). The route is a decision; the time is the risk.</p>
      <p class="def-ex"><b>What the climate changes.</b> Without it, the actual falls at percentile ${cL(B_.real_pct)} (and beyond percentile 99 if each segment is drawn alone, without the chaining). With it, at percentile ${cL(C_.real_pct)}.</p>
      <p class="muted">Robustness of percentile ${cL(C_.real_pct)}: with the cost of rain from part 03 (${fs0(CL.rain_03)}%, on the massifs), ${cL(SC.cost03.real_pct)}; with a fixed cost of ${fs0(CL.rain_pct)}%, ${cL(SC.cost_fixed.real_pct)}; ignoring the dry D2, ${cL(SC.all_worlds.real_pct)}; with blocks of 1 km or 4 km, ${cL(SC.L4.real_pct)} or ${cL(SC.L16.real_pct)}; from one run to the next, ${SC.seeds.map(v => cL(v.real_pct)).join(', ')}.</p>` };
    DEFS.var95 = { t: 'The simulation figures, with and without the climate', wide: true, html: () => `
      <p>Same model, same ${f0(MC.ns)} draws: only the weather changes.</p>
      <div class="table-wrap flat"><table class="data"><thead><tr><th>Measure</th><th class="n">Fair weather only</th><th class="n">With the climate</th></tr></thead><tbody>${mcRows}</tbody></table></div>
      <p style="margin-top:12px">The P95 and the average of the worst 5% are the two risk measures of banks, applied to my walking time.</p>
      <p><b>The P95, or value at risk (VaR).</b> In 1994, the bank <b>J.P. Morgan</b> published <i>RiskMetrics</i>: its boss wanted a single number every evening, “how much can we lose tomorrow, in 95% of cases?”. The ${f0(MC.ns)} simulations are sorted from fastest to slowest, and the one at 95% is read: only 1 traverse in 20 does worse.</p>
      <p><b>The average of the worst 5%, or <i>expected shortfall</i>.</b> VaR says where the worst begins, not how far it goes. In 1999, <b>Artzner, Delbaen, Eber and Heath</b> showed this flaw and proposed the average of the cases beyond the threshold. Since the 2016 Basel reform, it is what banks must compute.</p>
      <p class="def-ex"><b>Here.</b> Fair-weather forecast for D3–D9: ${hm(MC.central)}. 95% VaR: ${shm(C_.term[5])} with the climate (${shm(B_.term[5])} without). Average of the worst 5%: ${shm(C_.es95)}. The actual, ${shm(mcLate)}, stays below the VaR with the climate; without it, it came close.</p>` };
    DEFS.backtest = { t: 'Where backtesting comes from', wide: true, html: () => `
      <p><b>The idea.</b> A risk model announces thresholds; afterwards, one checks whether they held. If the 95% threshold is right, the actual should exceed it only once in 20.</p>
      <p><b>The origin.</b> In 1995, <b>Paul Kupiec</b>, an economist at the Federal Reserve, proposed counting the exceedances and testing whether their number is consistent with the announced rate. In 1996, the <b>Basel Committee</b> made it a rule for banks, with traffic lights: over 250 days, up to 4 exceedances of the 99% VaR, green; 5 to 9, amber; 10 or more, red.</p>
      <p><b>Here.</b> Each evening, the model is refitted on the days already walked only (the cost of rain removed from wet days), draws the next day’s weather among the worlds that had the same weather that day, and forecasts the next day, outing by outing (${S_.all.n} outings from D3 to D9).</p>
      <p class="def-ex"><b>The count.</b> With the climate: ${S_.all.n - S_.all.in90} outings outside the 90% interval out of ${S_.all.n}, for ${f1(S_.all.n * .1)} expected; in the rain, ${S_.wet.above95} exceedance of the 95% threshold out of ${S_.wet.n}: green light. Fair weather only: ${Sb.wet.above95} exceedances out of ${Sb.wet.n} in the rain; the chance of seeing as many with a correct model is ${F('.1f')(Sb.p_above_wet * 100)}%: red light.</p>
      <p><b>Day by day</b>, with the climate: ${dayOk} days out of ${BT.days.length} within the range. The announced chance of rain goes from ${pctW(BT.days[0].p_wet)} to ${pctW(BT.days[BT.days.length - 1].p_wet)} once the rain has arrived: that is persistence (part 05).</p>
      <div class="table-wrap flat"><table class="data">${btTable}</table></div>
      <p class="muted">${S_.all.n} outings is few: the count shows a trend, not a proof. And the cost of rain comes from the same rainy days: the green light in the rain is partly given in advance.</p>` };
    DEFS.stress = { t: 'Where the stress test comes from', html: () => `
      <p><b>The problem.</b> A model fitted on the past only knows what it has seen. In 1998, the fund <b>LTCM</b>, run by two Nobel laureates, collapsed: its models, fitted on calm years, judged the Russian crisis almost impossible. In 2008, banks’ VaRs, fitted on 2004–2006, were exceeded day after day.</p>
      <p><b>The answer.</b> Complement the model with <b>imposed scenarios</b>, often historical (“what if 2008 happened again?”): the question is no longer “what is the probability?”, but “if it happens, how much does it cost, and can it be absorbed?”. Since 2009, the Federal Reserve and then the European Banking Authority have imposed these tests on large banks.</p>
      <p><b>Here.</b> The cost of a rainy day is measured where it happened: a “rainy day” variable added to the regression over the whole traverse gives ${fs0(ST.pct)}% of time per segment. The standard error is computed by outing, not by segment, since the segments of an outing share the same weather. Rain, gusts and the fatigue of the last days are mixed in it. Part 03 found ${fs0(CL.rain_03)}% on the massifs, without accounting for the pack: it is within the interval.</p>
      <p class="def-ex"><b>The historical scenario.</b> Among the summers where D2 is dry, the worst is the one starting on ${+wd[2]}/${wd[1]}/${wd[0]}: ${W.wet} rainy days from D3 to D9, but only ${f1(W.mm)} mm, a continuous drizzle. With my route, the median there would be ${hm(sc.pire.median)}, ${shm(sc.pire.delta)} over the fair-weather forecast.</p>` };
    if (!$('mc-more').querySelector('.def-btn')) $('mc-more').innerHTML = defBtn('montecarlo', 'Monte Carlo, factor model and climate: where it comes from') + ' ' + defBtn('var95', 'The figures, with and without the climate');
    [['bt-t', 'backtest'], ['st-t', 'stress']].forEach(([id, k]) => { if (!$(id).querySelector('.def-btn')) $(id).insertAdjacentHTML('beforeend', defBtn(k)); });
    $('t-mc').innerHTML = `<b>${f0(100 - CL.p_none)}%</b> chance of rain on the evening of D2; the actual at <b>percentile ${cL(C_.real_pct)}</b> with the climate, against ${cL(B_.real_pct)} without. Rain was likely; its timing and its cost were not. Forgetting the climate means believing you are safer than you are.`;
  }
  function initMc() {
    document.querySelectorAll('.segctl button').forEach(b => b.addEventListener('click', () => {
      mcModel = b.dataset.m;
      document.querySelectorAll('.segctl button').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
      drawMc(true);
    }));
    $('mc-replay').addEventListener('click', () => drawMc(true));
    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting) && !mcPlayed) { mcPlayed = true; drawMc(true); io.disconnect(); } }, { threshold: .35 });
    io.observe($('c-mc'));
  }

  /* ---------- 08 · plan vs actual ---------- */
  const PL = window.RISK_PLAN;
  const eff = o => o.km + o.dplus / 100;   // km-effort : 100 m de montée comptent comme 1 km
  function drawPlan() {
    if (!PL) return;
    const M = PL.match, P_ = PL.plan, MO = PL.modes;
    $('plan-lede').innerHTML = `The plan: 8 days mapped out before leaving, plus one reserve day. Almost nothing went as planned. But a fund manager is not judged on loyalty to the index: what matters is what the deviations cost. Here, in effort.`;
  }
  // la carte plein écran : plan et trace réelle, avec ou sans le sac, campements et sommets
  function drawPlanMap(host) {
    const P_ = PL.plan, Rl = PL.real, rowsById = Object.fromEntries(R.rows.map(r => [r.id, r]));
    host.innerHTML = '';
    const W = host.clientWidth, H = host.clientHeight, pad = 34;
    const all = [...P_.line.flat(), ...Rl.line.flat()], lat0 = d3.mean(all, p => p[1]) * Math.PI / 180, kx = Math.cos(lat0);
    const xs = d3.extent(all, p => p[0] * kx), ys = d3.extent(all, p => p[1]);
    const sc = Math.min((W - 2 * pad) / (xs[1] - xs[0]), (H - 2 * pad) / (ys[1] - ys[0]));
    const ox = (W - (xs[1] - xs[0]) * sc) / 2, oy = (H - (ys[1] - ys[0]) * sc) / 2;
    const X = p => ox + (p[0] * kx - xs[0]) * sc, Y = p => H - oy - (p[1] - ys[0]) * sc, ln = d3.line().x(X).y(Y);
    const svg = d3.select(host).append('svg').attr('width', W).attr('height', H).attr('class', 'pmap'), g = svg.append('g');
    const cS = C('--series-avec'), cT = C('--series-sans');
    // plan : pointillés fins, couleur du mode prévu
    P_.modes_line.forEach(m => g.append('path').attr('d', ln(m.pts)).attr('fill', 'none').attr('stroke', m.t ? cT : cS).attr('stroke-width', 1.4).attr('stroke-dasharray', '4 3').attr('opacity', .75).attr('class', 'nz'));
    const a = P_.line[0][P_.line[0].length - 1], b = P_.line[1][0];
    g.append('path').attr('d', ln([a, b])).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '1 5').attr('stroke-width', 1.6).attr('fill', 'none').attr('class', 'nz');
    g.append('text').attr('class', 'lbl pm-t').attr('x', (X(a) + X(b)) / 2 + 8).attr('y', (Y(a) + Y(b)) / 2).text('boat');
    // réel : trait plein, une sortie par trait
    Rl.line.forEach((l, k) => { const r = rowsById[Rl.ids[k]] || {};
      hover(g.append('path').attr('d', ln(l)).attr('fill', 'none').attr('stroke', r.sac ? cS : cT).attr('stroke-width', 2.6).attr('stroke-linejoin', 'round').attr('stroke-linecap', 'round').attr('class', 'nz'),
        () => `<b>D${r.day} · ${r.name}</b>${row('mode', r.sac ? 'with the pack' : 'without the pack (trail)')}${row('distance', `${f1(r.km)} km`)}${row('elevation gain', `${f0(r.dplus)} m`)}${row('grade', r.grade_lbl)}`); });
    // sommets : atteints (plein) ou abandonnés (creux)
    const tri = (x, y, s) => `M${x},${y - s}L${x + s * .9},${y + s * .6}L${x - s * .9},${y + s * .6}Z`;
    const sumG = g.append('g');
    Rl.summits.forEach(s => { const x = X([s.lon, s.lat]), y = Y([s.lon, s.lat]);
      sumG.append('path').attr('d', tri(x, y, 6)).attr('fill', C('--text-primary')).attr('class', 'pm-m');
      sumG.append('text').attr('class', 'lbl-strong pm-t').attr('x', x + 8).attr('y', y - 4).text(`${s.name}${s.alt && W >= 600 ? ` ${f0(s.alt)} m` : ''}`); });
    P_.summits.filter(s => !s.done).forEach(s => { const x = X([s.lon, s.lat]), y = Y([s.lon, s.lat]);
      sumG.append('path').attr('d', tri(x, y, 6)).attr('fill', C('--bg')).attr('stroke', C('--down')).attr('stroke-width', 1.6).attr('class', 'pm-m');
      sumG.append('text').attr('class', 'lbl pm-t').attr('x', x - 10).attr('y', y + 4).attr('text-anchor', 'end').style('fill', C('--down')).text(W < 600 ? s.name : `${s.name} · given up`); });
    // campements : prévus (carrés) et réels (ronds), avec le numéro des nuits
    const uniq = (arr, key) => { const m = new Map(); arr.forEach((c, i) => { const k = key(c); if (!m.has(k)) m.set(k, { ...c, n: [] }); m.get(k).n.push(i + 1); }); return [...m.values()]; };
    const pc = uniq(P_.camps, c => c.name), rc = uniq(Rl.camps, c => c.name);
    hover(g.selectAll(null).data(pc).join('rect').attr('x', c => X([c.lon, c.lat]) - 5).attr('y', c => Y([c.lon, c.lat]) - 5).attr('width', 10).attr('height', 10).attr('class', 'pm-m')
      .attr('fill', C('--bg')).attr('stroke', C('--text-primary')).attr('stroke-width', 1.6), c => `<b>Planned · ${c.name}</b>${row('night', c.n.map(i => `N${i}`).join(', '))}${c.est ? row('position', 'estimated') : ''}`);
    hover(g.selectAll(null).data(rc).join('circle').attr('cx', c => X([c.lon, c.lat])).attr('cy', c => Y([c.lon, c.lat])).attr('r', 6.5).attr('class', 'pm-m')
      .attr('fill', C('--accent')).attr('stroke', C('--bg')).attr('stroke-width', 1.5), c => `<b>Actual · ${c.name}</b>${row('night', c.n.map(i => `N${i}`).join(', '))}${row('altitude', `${f0(c.alt)} m`)}`);
    rc.forEach(c => g.append('text').attr('class', 'lbl-ink pm-t').attr('x', X([c.lon, c.lat]) - 10).attr('y', Y([c.lon, c.lat]) + 4).attr('text-anchor', 'end')
      .style('paint-order', 'stroke').style('stroke', C('--bg')).style('stroke-width', '3px').text(W < 600 ? `N${c.n.join('–')}` : `N${c.n.join('–')} ${c.name.replace('Heights of ', '')}`));
    // départ et arrivée
    const st = Rl.line[0][0], en = Rl.line[Rl.line.length - 1].slice(-1)[0];
    [[st, W < 600 ? 'start' : 'start, 14/06'], [en, W < 600 ? 'finish' : 'harbour arrival, 22/06']].forEach(([p, t]) => g.append('text').attr('class', 'lbl-strong pm-t').attr('x', X(p) + 10).attr('y', Y(p) + 16).text(t));
    // les étiquettes ne se chevauchent pas : chacune descend d'une ligne tant qu'elle touche une étiquette déjà placée
    g.selectAll('text.pm-t').nodes().forEach(t => { const r = t.getBBox();     // une étiquette qui sort du cadre passe de l'autre côté
      if (r.x < 4) { t.setAttribute('text-anchor', 'start'); t.setAttribute('x', r.x + r.width + 20); }
      else if (r.x + r.width > W - 4) { t.setAttribute('text-anchor', 'end'); t.setAttribute('x', r.x - 20); } });
    { const placed = [];
      g.selectAll('text.pm-t').nodes().sort((a, b) => a.getBBox().y - b.getBBox().y).forEach(t => {
        for (let k = 0; k < 8; k++) { const r = t.getBBox(), hit = placed.some(q => r.x < q.x + q.width && q.x < r.x + r.width && r.y < q.y + q.height && q.y < r.y + r.height);
          if (!hit) break; t.setAttribute('y', +t.getAttribute('y') + 12); }
        placed.push(t.getBBox()); }); }
    // échelle et nord, hors zoom
    const kmPx = sc * (1 / 111.32), L10 = 10 * kmPx;
    const ui = svg.append('g').attr('transform', `translate(${pad},${H - 18})`);
    ui.append('line').attr('x2', L10).attr('stroke', C('--text-primary')).attr('stroke-width', 2);
    [0, L10].forEach(x => ui.append('line').attr('x1', x).attr('x2', x).attr('y1', -4).attr('y2', 4).attr('stroke', C('--text-primary')).attr('stroke-width', 2));
    ui.append('text').attr('class', 'lbl').attr('x', L10 + 8).attr('y', 4).text('10 km');
    svg.append('text').attr('class', 'lbl-strong').attr('x', W - pad).attr('y', pad).attr('text-anchor', 'end').text('N ↑');
    // zoom et déplacement ; les traits et les textes gardent leur taille
    svg.call(d3.zoom().scaleExtent([1, 8]).on('zoom', ev => { const k = ev.transform.k; g.attr('transform', ev.transform);
      g.selectAll('.nz').attr('vector-effect', 'non-scaling-stroke'); g.selectAll('.pm-t').style('font-size', `${11 / k}px`); g.selectAll('.pm-m').attr('transform', function () { const bb = this.getBBox(), cx = bb.x + bb.width / 2, cy = bb.y + bb.height / 2; return `translate(${cx},${cy}) scale(${1 / k}) translate(${-cx},${-cy})`; }); }));
  }
  function drawBridge() {
    $('c-bridge').dataset.h = innerWidth < 640 ? 560 : 330;
    const M = PL.match, B = M.bridge, f = frame('c-bridge', { t: 8, r: 70, b: 28, l: 8 }), nar = f.narrow || innerWidth < 640;
    const lw = nar ? 0 : Math.min(250, f.w * .42);
    const isT = d => d.total || d.k === 'plan' || d.k === 'real';
    let run = 0; const D = B.map(b => { if (isT(b)) { run = b.v; return { ...b, a: 0, z: b.v }; } const a = run; run += b.v; return { ...b, a, z: run }; });
    const x = d3.scaleLinear().domain([0, d3.max(D, d => Math.max(d.a, d.z)) * 1.04]).range([0, f.w - lw]);
    const y = d3.scaleBand().domain(D.map(d => d.k)).range([0, f.h]).padding(nar ? .08 : .28);
    const bh = nar ? y.bandwidth() * .46 : y.bandwidth(), by = k => y(k) + (nar ? y.bandwidth() - bh : 0);
    const g = f.g.append('g').attr('transform', `translate(${lw},0)`);
    g.append('g').attr('class', 'gridl').call(d3.axisBottom(x).ticks(nar ? 4 : 6).tickSize(f.h).tickFormat('')).lower();
    g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(nar ? 4 : 6).tickSize(0).tickPadding(8).tickFormat(v => `${v} km`));
    const col = d => ({ plan: C('--accent'), cal: C('--series-avec'), dec: d.v < 0 ? C('--up') : C('--down'), ter: C('--warning'), mes: C('--text-muted') })[d.g];
    D.forEach((d, i) => {
      f.g.append('text').attr('class', isT(d) ? 'lbl-strong' : 'lbl').attr('x', 0).attr('y', nar ? y(d.k) + y.bandwidth() * .3 : y(d.k) + y.bandwidth() / 2).attr('dy', '.35em').text(d.l);
      g.append('rect').attr('x', x(Math.min(d.a, d.z))).attr('width', Math.max(1.5, Math.abs(x(d.z) - x(d.a)))).attr('y', by(d.k)).attr('height', bh).attr('rx', 2).attr('fill', col(d)).attr('opacity', isT(d) ? (d.k === 'plan' ? .5 : .9) : .75);
      if (i < D.length - 1) g.append('line').attr('x1', x(d.z)).attr('x2', x(d.z)).attr('y1', by(d.k) + bh).attr('y2', by(D[i + 1].k)).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '2 2');
      g.append('text').attr('class', 'lbl-strong').attr('x', x(Math.max(d.a, d.z)) + 6).attr('y', by(d.k) + bh / 2).attr('dy', '.35em').text(isT(d) ? `${f1(d.v)} km` : `${d.v > 0 ? '+' : '−'}${f1(Math.abs(d.v))}`);
    });
  }
  function drawPlanCharts() {
    if (!PL) return;
    const P_ = PL.plan, Rl = PL.real, M = PL.match, MO = PL.modes;
    // ---- le pont : de la distance prévue à la distance réelle
    if ($('bridge-fold').open) drawBridge();   // drawn when the fold opens (a closed fold has no width)
    readout('r-bridge', `<b>${f0(M.bridge.find(b => b.k === 'plan_eq').v)} km</b> planned → <b>${f0(M.bridge.find(b => b.k === 'real').v)} km</b> walked`);
    legend('l-bridge', [['', C('--up'), 'distance less'], ['', C('--down'), 'distance more'], ['', C('--series-avec'), 'reserve day'], ['', C('--warning'), 'terrain'], ['', C('--text-muted'), 'mesure']]);
    $('s-bridge').textContent = `boat Kirkefjord → Vindstad removed · bivouac: ${f1(MO.biv.km)} km in ${MO.biv.n} detours`;
    // ---- le plan et le réel par mode : sac ou trail
    const pS = MO.plan.sac, pT = MO.plan.trail, rS = MO.real.sac, rT = MO.real.trail;
    [pS, pT, rS, rT].forEach(o => { o.eff = eff(o); });
    const pc = (a, b) => { const v = Math.round((b / a - 1) * 100); return v === 0 ? '0%' : `${fs0(v)}%`; }, hP = pS.h + pT.h, hR = rS.h + rT.h, dpP = pS.dplus + pT.dplus, dpR = rS.dplus + rT.dplus, eP = pS.eff + pT.eff, eR = rS.eff + rT.eff;
    {
      $('c-pmode').dataset.h = innerWidth < 640 ? 420 : 150;
      const f = frame('c-pmode', { t: 8, r: 8, b: 4, l: 8 }), nar = f.narrow;
      const MET = [['Distance', 'km', 'km', v => f0(v)], ['Elevation gain', 'm', 'dplus', v => f0(v)], ['Effort (km + D+ / 100)', 'km-effort', 'eff', v => f0(v)]];
      const cols = nar ? 1 : 3, rows_ = nar ? 3 : 1, gap = 28, cw = (f.w - gap * (cols - 1)) / cols, ch = f.h / rows_;
      MET.forEach(([lab, unit, k, fmt], m) => {
        const g = f.g.append('g').attr('transform', `translate(${nar ? 0 : m * (cw + gap)},${nar ? m * ch : 0})`), lw = 38, tw = unit.length > 3 ? 96 : 70;
        const tot = [pS[k] + pT[k], rS[k] + rT[k]], x = d3.scaleLinear().domain([0, d3.max(tot)]).range([0, cw - lw - tw]);
        g.append('text').attr('class', 'lbl-strong').attr('x', 0).attr('y', 14).text(lab);
        [['Plan', pS, pT], ['Actual', rS, rT]].forEach(([nm, a, b], r) => {
          const yy = 28 + r * 44, bh = 30;
          g.append('text').attr('class', 'lbl').attr('x', 0).attr('y', yy + bh / 2 + 4).text(nm);
          [[a[k], C('--series-avec'), 0], [b[k], C('--series-sans'), a[k]]].forEach(([v, c, x0]) => {
            g.append('rect').attr('x', lw + x(x0)).attr('width', Math.max(1, x(v) - 1)).attr('y', yy).attr('height', bh).attr('rx', 2).attr('fill', c).attr('opacity', r ? .9 : .5);
            if (x(v) > 44) g.append('text').attr('class', 'lbl-ink').attr('x', lw + x(x0) + x(v) / 2).attr('y', yy + bh / 2 + 4).attr('text-anchor', 'middle').text(fmt(v));
          });
          g.append('text').attr('class', 'lbl-strong').attr('x', lw + x(a[k] + b[k]) + 6).attr('y', yy + bh / 2 + 4).text(`${fmt(a[k] + b[k])} ${unit}`);
        });
        const dk = (a, b) => { const v = Math.round(b - a); return `${v > 0 ? '+' : v < 0 ? '−' : ''}${Math.abs(v)} km`; };
        g.append('text').attr('class', 'lbl').attr('x', lw).attr('y', 28 + 2 * 44 + 8).text(k === 'km' ? `pack ${dk(pS[k], rS[k])} · trail ${dk(pT[k], rT[k])} · total ${dk(pS[k] + pT[k], rS[k] + rT[k])}` : `pack ${pc(pS[k], rS[k])} · trail ${pc(pT[k], rT[k])} · total ${pc(pS[k] + pT[k], rS[k] + rT[k])}`);
      });
      legend('l-pmode', [['', C('--series-avec'), 'with the pack'], ['', C('--series-sans'), 'without the pack (trail)'], ['', C('--text-muted'), 'plan light, actual solid']]);
      readout('r-pmode', `plan converted to the watch’s measure (×${F('.2f')(MO.ratio)})`);
    }
    const B = Object.fromEntries(M.bridge.map(b => [b.k, b.v])), dry = 67;   // sac au sec (partie 06, second ordre)
    const carry = (h, p) => h - h / (1 + p / 100);
    $('plan-cols').innerHTML = [
      [C('--down'), 'the route', 'It did not hold', `${f0(MO.track_done / P_.km8 * 10)} km out of 10`, `of the planned route walked. ${M.abandoned.length} summits or loops given up (${M.abandoned.map(a => a.name).join(', ')}), replaced by other outings. ${MO.camps_same} camps out of ${MO.camps_n} at the planned spot.`],
      [C('--up'), 'the effort', 'It held', `${f0(eP)} → ${f0(eR)} km-effort`, `${pc(eP, eR)} only, and ${f0(dpP)} → ${f0(dpR)} m of D+. ${f0(pS.km - rS.km)} km fewer carried, ${f0(rT.km - pT.km)} km more run: at my speeds, ${hm(hP)} planned against ${hm(hR)} walked.`],
    ].map(([c, s_, t, v, tx]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><b class="v">${v}</b><p>${tx}</p></div>`).join('');
    $('plan-msg').innerHTML = `<b>Neither underestimated nor overestimated.</b> The plan did not serve as a route: it served as a measure of the effort to provide. The deviations, in opposite directions, offset each other; the reserve day went to Støvla, as planned.`;
    DEFS.attribution = { t: 'Where the comparison with the plan comes from', html: () => `
      <p><b>The benchmark.</b> A fund manager is judged against a <i>benchmark</i>: a reference portfolio set in advance. Deviating from it is not a fault, it is the job. But each deviation must be explained.</p>
      <p><b>Performance attribution.</b> In 1986, <b>Brinson, Hood and Beebower</b> broke down the gap between a fund and its index into pieces that add up: the split between major asset classes (<i>allocation</i>) and the choice of securities (<i>selection</i>).</p>
      <p class="def-ex"><b>Here.</b> The plan is the index. The allocation is the split between pack and trail. The common measure is <b>effort</b>, in effort-km: 1 km counts 1, and 100 m of climbing count 1 more. Plan: ${f0(eP)} effort-km; actual: ${f0(eR)} (${pc(eP, eR)}). The bridge (the “From planned to actual distance” strip, below) starts from the ${f0(P_.km8)} km of the route and classifies each distance gap.</p>
      <p><b>Why not time.</b> I had no time estimate before leaving. Converting the plan into hours requires a speed, and the only one I have is the one measured during the trek, rain included (${f1(MO.speed.sac)} effort-km/h with the pack, ${f1(MO.speed.trail)} on trail). With it, actual time gives back exactly the actual effort: the comparison of times (${hm(hP)} vs ${hm(hR)}) can see nothing but the effort and the pack / trail mix. It does not see the slowing of pace, which the simulation measures (part 07, +${hm(mcLate)}). The two therefore say different things: the planned effort held, the pace slipped.</p>
      <p><b>The cost of carry.</b> In finance, holding a position costs money (funding, storage): it is the <i>cost of carry</i>. Here, the pack is the position: it lets me move on with my camp, but on equal terrain it adds ${f0(MO.sac_pct)}% of time (part 04, the ρ of part 06).</p>
      <div class="def-f">extra cost = time carried − time carried ÷ ${f2(1 + MO.sac_pct / 100)}</div>
      <div class="def-ex"><b>Plan.</b> ${hm(pS.h)} with the pack, of which ${hm(MO.carry.plan)} extra. <b>Actual.</b> ${hm(rS.h)}, of which ${hm(MO.carry.real)}. By carrying less far, I saved ${hm(MO.carry.plan - MO.carry.real)} of carrying.</div>
      <p class="muted">Range. The ${f0(MO.sac_pct)}% is an average; in the dry, the pack costs +${dry}% (part 06; a fragile figure, it rests on only 2 outings with the pack in the rain). Almost all the carrying was done in the dry: with +${dry}%, the extra cost would be ${hm(carry(pS.h, dry))} in the plan and ${hm(carry(rS.h, dry))} in reality, i.e. ${hm(carry(pS.h, dry) - carry(rS.h, dry))} saved. Actual time comes from the watch (${hm(hR)}), the simulation adds up the 250 m segments: a few minutes’ difference. An actual point counts as “on the plan” within 60 m of the route; the smoothed Strava route is shorter than the watch’s measure: its distances are multiplied by ${F('.2f')(MO.ratio)}.</p>` };
    const pt = $('c-pmode').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('attribution'));
        DEFS.carte = { t: 'The plan and the actual track', full: true, html: () => `<div class="pm-legend legend-row"><span><i style="background:${C('--series-avec')}"></i>with the pack</span><span><i style="background:${C('--series-sans')}"></i>without the pack (trail)</span><span>solid line: actual · dotted: plan</span><span>● actual camp · □ planned</span><span>▲ summit reached · △ given up</span><span class="muted">scroll or pinch to zoom</span></div><div class="pm-host" id="pm-host"></div>`, after: p => drawPlanMap(p.querySelector('#pm-host')) };
    if (!$('plan-more').innerHTML) $('plan-more').innerHTML = defBtn('carte', 'The map: the plan and the actual track');
    $('t-plan').innerHTML = `<b>${f0(MO.track_done / P_.km8 * 10)} km out of 10</b> of the route followed, but the effort within <b>${pc(eP, eR)}</b>. Less pack, more trail: the summits given up and the substitute outings offset each other. Good plan, good decisions, or luck? That is the next question.`;
  }

  /* ---------- 12 · conclusion ---------- */
  function drawConcl() {
    const PL_ = window.RISK_PLAN, MO = PL_.modes, X = window.RISK_CD, MC_ = MC;
    const eff = o => o.km + o.dplus / 100;
    const eP = eff(MO.plan.sac) + eff(MO.plan.trail), eR = eff(MO.real.sac) + eff(MO.real.trail);
    const kmP = MO.plan.sac.km + MO.plan.trail.km, kmR = MO.real.sac.km + MO.real.trail.km, dpP = MO.plan.sac.dplus + MO.plan.trail.dplus, dpR = MO.real.sac.dplus + MO.real.trail.dplus;
    const nSeg = R.series.filter(x => Math.abs(x.slope) <= 60).length;
    $('cc-lede').innerHTML = `I set off with a plan of ${f0(kmP)} km and ${f0(dpP)} m of elevation gain, a heavy pack and a single reserve day; I reached the harbour with ${f0(kmR)} km and ${f0(dpR)} m, by another route. The aim was not to tell the story of that week, but to measure its risk: where it was concentrated, what moved it, and whether my plan had foreseen it. To answer, it was enough to take up the tools of everyone who takes risks methodically: a benchmark to measure deviations, factors to explain them, scenarios to prepare for them, a margin to protect against them. Applied to nine days of walking, they fit without forcing: <b>the terrain becomes a market, the pack a position, the traverse a portfolio.</b>`;
    // le socle : les données, de la montre à la compréhension
    const step = (n, h, sub) => `<div class="st"><span class="n">${n}</span><b>${h}</b><small>${sub}</small></div>`;
    $('cc-socle').innerHTML = `<div class="socle-t"><span>the foundation</span><b>The data</b></div><div class="socle-line">${[
      step(1, 'Collect', 'GPS watch, sleep, weather, 30 summers'),
      step(2, 'Process and clean', `${f0(nSeg)} segments of 250 m, errors removed`),
      step(3, 'Understand', 'each deviation from the pace becomes a return'),
    ].join('<i class="ar" aria-hidden="true"></i>')}</div>`;
    $('cc-cols').innerHTML = [
      [C('--accent'), 'measure', 'The terrain as a market', `Tobler’s pace serves as the <b>expected return</b>: each segment deviates from it. Taken alone, the deviations almost follow a <b>normal distribution</b>; but they come in streaks, like <b>volatility</b> clustering in turbulent markets. The summits are almost <b>independent</b>: their <b>specific risk</b> is diluted over the week, as in a <b>diversified</b> portfolio. Rain, on the other hand, hits all the summits at once: that is <b>systematic risk</b>. Støvla carries both: an invisible trail, then the rain.`],
      [C('--series-avec'), 'explain', 'The pack as a position', `A <b>factor regression</b> puts a number on each cause: the pack costs ${fs0(sacS.pct)}%, each terrain level ${fs0(sens['terrain (+1 level)'].pct)}%. Read with the options <b>Greeks</b>, these sensitivities say how much my time moves: <b>gamma</b> reveals the sudden jump when the trail disappears, <b>vega</b> that the pace stays steadier under the pack, <b>theta</b> that uncertainty grows with the horizon. The weather, for its part, changes <b>regime</b>: one rainy day calls for another (52% against 23%). And fatigue does not slow my steps, it weighs on my choices: two summits given up.`],
      [C('--warning'), 'steer', 'The traverse as a portfolio', `A <b>Monte Carlo simulation</b> replays ${f0(MC_.ns)} traverses in 1,200 real summers: it gives a <b>value at risk</b>, passes the banks’ <b>backtest</b> and a <b>stress test</b>. The reserve day becomes an <b>option</b>, valued with Black-Scholes, whose value melts with each dry day. The plan becomes a <b>benchmark</b>, and the last question is every fund manager’s: <b>skill or luck?</b>`],
    ].map(([c, s_, t, tx]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><p>${tx}</p></div>`).join('');
    $('cc-msg').innerHTML = `<b>Same method, same vocabulary: only the data change.</b> That is what makes a trek a real field of analysis.`;
    const slow = EP.episodes.filter(d => d.sign > 0 && Math.round(d.lost_min) >= 5), lost = d3.sum(slow, d => d.lost_min);
    const O = X.opt, upTo = k => O.dist.filter(d => d.k <= k).reduce((a, d) => a + d.p, 0), share = v => Math.round(v / 10);
    const VG = window.RISK_ACTE2 && window.RISK_ACTE2.vega && window.RISK_ACTE2.vega.sac;
    $('lessons').innerHTML = [
      ['The pack slows, the trail exposes', `The pack slowed me down by ${f0(MO.sac_pct)}%. Without it, the terrain was steeper and my pace more irregular${VG ? ` (${f2(VG.a)} vs ${f2(VG.b)})` : ''}: the measurements confirm what I had felt.`],
      ['Bad passages come in streaks', `${slow.length} slow episodes, ${hm(lost / 60)} in all, mostly endured.`],
      ['The plan served as a measure, not as a path', `${f0(MO.track_done / PL_.plan.km8 * 10)} km out of 10 of the route followed, the effort within ${f0(Math.abs(eR / eP - 1) * 100)}%.`],
      ['Rain was likely; its timing was my luck', `Only 1 summer in 4 keeps the first six days dry; in 2026, it came on D7.`],
    ].map(([h, p]) => `<li><h4>${h}</h4><p>${p}</p></li>`).join('');
    DEFS.regles = { t: 'For the next traverse', html: () => `<ul class="rules">${[
      `<b>Two reserve days, not one.</b> One is enough in ${share(O.p_enough)} summers out of 10; two, in ${share(upTo(2))}.`,
      '<b>Choose before leaving what I will give up in the rain.</b> It was dropping the lake loop, not the margin, that saved the end.',
      '<b>A freed day is not a risk-free day.</b> In the rain, the danger moves from the pack to summits without the pack: Støvla and its rockfall.',
      '<b>After a short night, no exposed summit.</b> The 2 a.m. start on D5 ended with turning back at the foot of the summit.',
    ].map((x, i) => `<li data-k="${i + 1}"><span>${x}</span></li>`).join('')}</ul>` };
    if (!$('cc-more').innerHTML) $('cc-more').innerHTML = defBtn('regles', 'For the next traverse');
    DEFS.methodes = { t: 'Data, calculations, sources and limits', wide: true, html: () => $('tpl-methodes').innerHTML };
    if ($('meth-more') && !$('meth-more').innerHTML) $('meth-more').innerHTML = defBtn('methodes', 'Data, calculations, sources and limits');
    $('cc-end').innerHTML = `And counting the trips back to camp to fetch water, for the stove and for drinking, I passed the <b>10,000 m of D+</b> mark 😜`;
  }

  /* ---------- hero · map card thumbnail (the real trace) ---------- */
  function drawMapThumb() {
    const svg = d3.select('#map-thumb'); if (svg.empty()) return;
    svg.selectAll('*').remove();
    const el = svg.node(), W = el.clientWidth || 240, H = el.clientHeight || 150;
    svg.attr('viewBox', `0 0 ${W} ${H}`);
    const T = R.trace, lat0 = d3.mean(T, p => p[1]) * Math.PI / 180;
    const pts = T.map(p => [p[0] * Math.cos(lat0), -p[1]]);
    const x = d3.scaleLinear().domain(d3.extent(pts, p => p[0])), y = d3.scaleLinear().domain(d3.extent(pts, p => p[1]));
    const sx = (W - 24) / (x.domain()[1] - x.domain()[0]), sy = (H - 24) / (y.domain()[1] - y.domain()[0]), s = Math.min(sx, sy);
    const ox = (W - s * (x.domain()[1] - x.domain()[0])) / 2, oy = (H - s * (y.domain()[1] - y.domain()[0])) / 2;
    const P = pts.map(p => [ox + (p[0] - x.domain()[0]) * s, oy + (p[1] - y.domain()[0]) * s]);
    // contour-like halo, then the trace coloured with / without the pack (as on the map)
    svg.append('path').attr('d', d3.line()(P)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 7).attr('stroke-opacity', .08).attr('stroke-linejoin', 'round');
    for (let i = 1; i < P.length; i++) {
      if (Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]) > 18) continue;   // ferry / gap: no segment
      svg.append('line').attr('x1', P[i - 1][0]).attr('y1', P[i - 1][1]).attr('x2', P[i][0]).attr('y2', P[i][1])
        .attr('stroke', T[i][2] ? C('--series-avec') : C('--series-sans')).attr('stroke-width', 1.8).attr('stroke-linecap', 'round');
    }
    [[P[0], C('--up')], [P[P.length - 1], C('--text-primary')]].forEach(([p, c]) => svg.append('circle').attr('cx', p[0]).attr('cy', p[1]).attr('r', 3.6).attr('fill', c).attr('stroke', C('--bg')).attr('stroke-width', 1.5));
    svg.append('text').attr('class', 'lbl').attr('x', 8).attr('y', H - 8).text('N ↑');
  }

  /* ---------- 09 · chance ou décision ---------- */
  function drawCF() {
    const X = window.RISK_CD; if (!X || !X.vol) return;
    const V = X.vol, O = X.opt, TH_ = X.theta, CD = X.dec, TW = X.trail_wet, G = window.RISK_MARGE;
    const pctF = v => `${f0(v)}%`, nameOf = n => n === 'Last trail' ? 'Gylttinden' : n;
    const upTo = k => O.dist.filter(d => d.k <= k).reduce((a, d) => a + d.p, 0);
    // (a) la volatilité : le jour de la première pluie
    {
      const D = V.first, f = frame('c-first', { t: 22, r: 10, b: 30, l: 10 });
      const x = d3.scaleBand().domain(D.map(d => d.day)).range([0, f.w]).padding(.22), y = d3.scaleLinear().domain([0, d3.max(D, d => d.p) * 1.15]).range([f.h, 0]);
      const late = d => d.day === 0 || d.day >= 7, x0 = x(7) - x.step() * x.paddingInner() / 2;
      f.g.append('rect').attr('x', x0).attr('width', f.w - x0).attr('y', 0).attr('height', f.h).attr('fill', C('--up')).attr('fill-opacity', .08).attr('rx', 4);
      f.g.append('text').attr('class', 'ax-title').attr('x', x0 + 6).attr('y', 10).text(f.narrow ? `after: ${pctF(V.p_dry_1_6)}` : `after the big stages: ${pctF(V.p_dry_1_6)} of summers`);
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).tickSize(0).tickPadding(8).tickFormat(d => d ? `D${d}` : (f.narrow ? '∅' : 'aucune')));
      f.g.selectAll(null).data(D).join('rect').attr('x', d => x(d.day)).attr('width', x.bandwidth()).attr('y', d => y(d.p)).attr('height', d => f.h - y(d.p)).attr('rx', 2)
        .attr('fill', d => late(d) ? C('--up') : C('--down')).attr('fill-opacity', d => d.day === V.real_first ? 1 : .55).attr('stroke', d => d.day === V.real_first ? C('--text-primary') : 'none').attr('stroke-width', 1.5);
      f.g.selectAll(null).data(D).join('text').attr('class', 'lbl tagt').attr('x', d => x(d.day) + x.bandwidth() / 2).attr('y', d => y(d.p) - 5).attr('text-anchor', 'middle').text(d => f0(d.p));
      const r = D.find(d => d.day === V.real_first);
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(r.day) + x.bandwidth() / 2).attr('y', y(r.p) - 20).attr('text-anchor', 'middle').text('2026');
      hover(f.g.selectAll('.mh').data(D).join('rect').attr('class', 'hit').attr('x', d => x(d.day)).attr('width', x.bandwidth()).attr('y', 0).attr('height', f.h),
        d => `<b>${d.day ? `First rain on D${d.day}` : 'No rainy day'}</b>${row('share of summers', pctF(d.p))}`);
      legend('l-first', [['', C('--down') + ';opacity:.55', 'during the big stages'], ['', C('--up') + ';opacity:.55', 'after (or never)'], ['ring', C('--text-primary'), '2026']]);
      readout('r-first', `it rains from D1 in <b>${pctF(V.p_day1)}</b> of summers`);
      const pt = $('c-first').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('volat'));
    }
    // (b) l'option : combien de jours d'étape sous la pluie, et la marge suffit-elle ?
    {
      const D = O.dist, f = frame('c-need', { t: 22, r: 10, b: 30, l: 10 });
      const x = d3.scaleBand().domain(D.map(d => d.k)).range([0, f.w]).padding(.28), y = d3.scaleLinear().domain([0, d3.max(D, d => d.p) * 1.15]).range([f.h, 0]);
      const col = k => k === 0 ? C('--text-muted') : k === 1 ? C('--up') : C('--down');
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).tickSize(0).tickPadding(8).tickFormat(k => k === 4 ? '4 or +' : `${k} stage${k !== 1 ? 's' : ''}`));
      f.g.selectAll(null).data(D).join('rect').attr('x', d => x(d.k)).attr('width', x.bandwidth()).attr('y', d => y(d.p)).attr('height', d => f.h - y(d.p)).attr('rx', 2)
        .attr('fill', d => col(d.k)).attr('fill-opacity', d => d.k === O.real_plan ? 1 : .6).attr('stroke', d => d.k === O.real_plan ? C('--text-primary') : 'none').attr('stroke-width', 1.5);
      f.g.selectAll(null).data(D).join('text').attr('class', 'lbl tagt').attr('x', d => x(d.k) + x.bandwidth() / 2).attr('y', d => y(d.p) - 5).attr('text-anchor', 'middle').text(d => pctF(d.p));
      const r = D.find(d => d.k === O.real_plan);
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(r.k) + x.bandwidth() / 2).attr('y', y(r.p) - 20).attr('text-anchor', 'middle').text(f.narrow ? '2026' : '2026, per the plan');
      hover(f.g.selectAll('.mh').data(D).join('rect').attr('class', 'hit').attr('x', d => x(d.k)).attr('width', x.bandwidth()).attr('y', 0).attr('height', f.h),
        d => `<b>${d.k === 4 ? '4 stages or more' : `${d.k} stage${d.k !== 1 ? 's' : ''}`} rainy day</b>${row('share of summers', pctF(d.p))}${row('the reserve day', d.k === 0 ? 'not used' : d.k === 1 ? 'suffit' : 'not enough')}`);
      legend('l-need', [['', C('--text-muted') + ';opacity:.6', 'the margin is not used'], ['', C('--up') + ';opacity:.6', 'it is enough'], ['', C('--down') + ';opacity:.6', 'it is not enough']]);
      readout('r-need', `the margin is enough in <b>${pctF(O.p_enough)}</b> of summers`);
      const pt = $('c-need').closest('.pc').querySelector('.pc-t'); if (!pt.querySelector('.def-btn')) pt.insertAdjacentHTML('beforeend', defBtn('option'));
    }
    // (d) lire
    const av = X.ahead, avMax = av.reduce((b, a) => a.km > b.km ? a : b, av[0]), bunes = av.find(a => /Bunes/.test(a.real));
    $('cf-lede').innerHTML = `The rain, its timing and its amount, I endure: that is volatility. The reserve day, planned before leaving, is the only real option. One is measured over 1,200 real summers, the other is valued like an insurance.`;
    $('cf-cols').innerHTML = [
      [C('--warning'), 'volatility', 'The timing of the rain', '1 summer in 4', `keeps the first six days dry, like 2026 (${pctF(V.p_dry_1_6)}). In one summer in three, it rains from D1.`],
      [C('--accent'), 'the option, before leaving', 'A single reserve day', `is enough: ${pctF(O.p_enough)}`, `It is used in ${pctF(O.p_use)} of summers, but only covers one rainy day on one stage: in ${pctF(O.p_short)} of summers, two or more would be needed.`],
      [C('--down'), 'the option, in 2026', 'Overwhelmed, then freed', `${O.real_plan} stages`, `of the plan fell in the rain, those of the lake loop. I gave up the loop: the margin, freed, became Støvla, in the rain, with its rockfall.`],
      [C('--text-muted'), 'what did not count', 'The lead on D2–D3', `+${f0(avMax.km)} km → ${bunes ? `${bunes.km < 0 ? '−' : '+'}${f0(Math.abs(bunes.km))} km` : '0'}`, `on the evening of ${dateLbl(avMax.night)}, then nothing left the next day at Bunes: the D4 boat imposes the same stage, lead or not.`],
    ].map(([c, s_, t, v, tx]) => `<div style="--c:${c}"><span class="s">${s_}</span><div class="t">${t}</div><b class="v">${v}</b><p>${tx}</p></div>`).join('');
    $('cf-msg').innerHTML = `<b>Luck chose the timing; the only option was too small.</b> The reserve day did absorb my walking delay (part 07), but it could not cover two stages in the rain: it was rain falling at the end and giving up the lake loop that protected the traverse. And the freed day was not risk-free: ${f1(TW.hard_km)} km of demanding or expert trail in the rain (${TW.names.map(nameOf).join(', ')}).`;
    $('t-cf').innerHTML = `<b>1 summer in 4</b> keeps the first six days dry: that was my luck. The reserve day, the only real option, was enough in only <b>${pctF(O.p_enough)}</b> of summers. In 2026, the rain would have overwhelmed it; giving up the lake loop freed it for a summit.`;
    DEFS.volat = { t: 'Volatility: rain over 1,200 summers', html: () => `
      <p><b>Where the summers come from.</b> The same as in parts 05 and 07: ERA5, at the central point of the archipelago, from 1996 to 2025, with a start every day from 1 June to 10 July, i.e. ${f0(V.worlds)} 9-day windows. A rainy day gets at least 1 mm.</p>
      <p><b>What is measured.</b> The day of the first rain, without assuming anything about what I would have done. Rain on D1 or D2 would have soaked me from the start: I would probably have reached a village to dry my gear. That reaction cannot be modelled; we just say how many summers would have forced it.</p>
      <div class="def-ex"><b>Result.</b> It rains from D1 in ${pctF(V.p_day1)} of summers; the first six days stay dry in ${pctF(V.p_dry_1_6)}; no rainy day in nine days: ${pctF(V.p_none)}. In 2026, the first rain fell on D7, and that morning’s stage (Munkebu → Sørvågen) was done before the worst of the rain, with 0.6 mm.</div>
      <p class="muted">This is volatility in the financial sense: a hazard one does not choose, and can only measure and prepare for.</p>` };
    DEFS.option = { t: 'The reserve day, an option', html: () => `
      <p><b>The idea.</b> An option gives a <i>right</i> without an <i>obligation</i>, against a premium paid in advance. In 1977, <b>Stewart Myers</b> applied the idea outside markets: keeping the possibility to wait has value, even if it is never used. Unused insurance is not money lost: it protected while the future was uncertain.</p>
      <p><b>Here.</b> The premium: one day of the schedule, set aside before leaving. The right: to postpone by one day a stage that would fall in the rain. The option is “in the money” when a stage falls on a rainy day. Over the ${f0(V.worlds)} summers, we count the stage days of the plan (D${O.stage_days.join(', D')}) that get at least 1 mm.</p>
      <div class="def-ex"><b>Result.</b> The margin is used in ${pctF(O.p_use)} of summers and is enough in ${pctF(O.p_enough)}. With two days (sacrificing the summit planned on D6), it would be enough in ${pctF(upTo(2))}; with three, ${pctF(upTo(3))}. In 2026, the plan would have had ${O.real_plan} stages in the rain: the margin was overwhelmed.</div>
      <p><b>Theta.</b> Each evening, only the summers whose day had the same weather as mine are kept: each dry day lowers the chance that the margin will be used (${pctF(TH_[0].p_use)} at the start, ${pctF(TH_[TH_.length - 1].p_use)} on the evening of D6). The same reserve day, counted in minutes of walking, is valued with Black-Scholes in part 07${G ? `: ${hm(G.value_j2.sim / 60)} to absorb on D2, ${hm(G.used_min / 60)} actually used, without costing a day thanks to the midnight sun` : ''}.</p>
      <p class="muted">Limits. My reactions to rain are not modelled (drying gear, changing route): only the stages the climate would have soaked are counted. A 1 mm threshold does not tell a drizzle from a downpour.</p>` };
    // le journal des décisions, dans un bouton
    const I = CD.items, FL = { nuit: 'short night', exig: 'demanding grade', expert: 'expert grade', tard: 'late / time lost', pluie: 'rain', vent: 'wind > normal', neige: 'neige', brouillard: 'brouillard' };
    const QD = { merite: ['Deserved', C('--up')], chance: ['Luck', C('--warning')], consequence: ['Consequence', C('--down')], malchance: ['Bad luck', C('--series-avec')] };
    const decTable = `<thead><tr><th>Day</th><th>Decision</th><th>What I knew</th><th>Outcome</th><th>Verdict</th></tr></thead><tbody>${I.map(d => `<tr><td class="mono">${d.day}</td><td>${d.txt}${d.day === 'D2' ? '<div class="muted">lead wiped out on D4 by the boat</div>' : ''}${/faute de bivouac/.test(d.txt) ? '<div class="muted">partly endured: no bivouac possible at the lake</div>' : ''}</td><td>${d.flags.length ? d.flags.map(k => FL[k] || k).join(', ') : 'no signal'}</td><td>${d.res}</td><td class="nw"><span class="dot" style="background:${QD[d.quad][1]}"></span>${QD[d.quad][0]}</td></tr>`).join('')}</tbody>`;
    DEFS.decision = { t: 'The decisions, one by one', wide: true, html: () => `
      <p><b>The idea.</b> In 1966, <b>Ronald Howard</b> founded decision analysis on one rule: a decision is judged on what was known when it was made, not on what happened. Judging on the outcome alone is outcome bias (<i>resulting</i>, Annie Duke, 2018). In finance, it is the question put to every fund manager: skill or luck?</p>
      <p><b>The grid.</b> Each decision is classified by the signals known at that moment (cautious given the signals: good; committed despite them: risky) and by its outcome: good and ended well, “deserved”; risky and ended well, “luck”; risky and ended badly, “consequence”; good and ended badly, “bad luck”. Here: ${CD.quad.merite} “deserved”, ${CD.quad.consequence} “consequence”, ${CD.quad.chance} “luck”, ${CD.quad.malchance} “bad luck”.</p>
      <div class="table-wrap flat"><table class="data">${decTable}</table></div>
      <p class="muted">To be read as a journal, not as a proof: ${CD.n} decisions, chosen and graded by me afterwards.</p>` };
    if (!$('cf-more').innerHTML) $('cf-more').innerHTML = defBtn('decision', 'The decisions, one by one');
  }

  /* ---------- draw all, redraw on resize ---------- */
  const charts = [drawMapThumb, drawCandles, drawTerrain, drawDist, drawRoll, drawAcf, drawSens, drawHrv, drawWx, drawPersist, drawActe2, () => drawMc(false), drawMarge, drawPlanCharts, drawCF, drawConcl];
  function drawAll() { charts.forEach(fn => { try { fn(); } catch (e) { console.error(fn.name, e); } }); }
  drawTail(); drawPlan(); drawAll(); initMc();
  // espaces insécables : un nombre reste sur la même ligne que son unité (+41%, 1 h 36, ± 67 min), et « : ; ? ! » ne passent pas seuls à la ligne,
  // y compris dans les textes produits plus tard
  const NB = [[/(\d) (?=(?:%|°C|(?:min|h|km|m|mm|ms|bpm|j)(?![\p{L}\d])))/gu, '$1\u00a0'], [/([±×≈]) (?=\d)/g, '$1\u00a0'], [/(^|[^\d,])(\d{1,3}) (?=\d{3}(?!\d))/g, '$1$2\u00a0'], [/(\d\u00a0h) (?=\d)/g, '$1\u00a0'], [/ ([:;?!»])/g, '\u00a0$1'], [/« /g, '«\u00a0']];
  const glueText = t => { if (!/ /.test(t.nodeValue) || (t.parentNode && t.parentNode.closest && t.parentNode.closest('svg, script, style'))) return;
    const v = NB.reduce((a, [re, r]) => a.replace(re, r), t.nodeValue); if (v !== t.nodeValue) t.nodeValue = v; };
  const glue = n => { if (n.nodeType === 3) return glueText(n); if (n.nodeType !== 1 || n.closest('svg')) return;
    const w = document.createTreeWalker(n, NodeFilter.SHOW_TEXT); for (let t; (t = w.nextNode());) glueText(t); };
  glue(document.body);
  const glueQ = new Set(); let glueF = 0;
  new MutationObserver(ms => {
    ms.forEach(m => { if (m.type === 'characterData') glueQ.add(m.target); else m.addedNodes.forEach(n => glueQ.add(n)); });
    if (!glueF) glueF = requestAnimationFrame(() => { glueF = 0; const q = [...glueQ]; glueQ.clear(); q.forEach(n => { if (n.isConnected) glue(n); }); });
  }).observe(document.body, { childList: true, subtree: true, characterData: true });
  // navigation : un rechargement repart du haut ; les liens internes défilent sans laisser d'ancre dans l'adresse
  $('bridge-fold').addEventListener('toggle', e => { if (e.target.open) drawBridge(); });
  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
  const cleanUrl = () => history.replaceState(null, '', location.pathname + location.search);
  if (location.hash) {   // lien partagé vers une partie : on y va une fois les graphiques dessinés, puis on retire l'ancre
    const t = document.getElementById(decodeURIComponent(location.hash.slice(1)));
    if (t) requestAnimationFrame(() => t.scrollIntoView({ block: 'start' }));
    cleanUrl();
  } else scrollTo(0, 0);
  document.addEventListener('click', ev => {
    const a = ev.target.closest('a[href^="#"]'); if (!a) return;
    const t = document.getElementById(a.getAttribute('href').slice(1)); if (!t) return;
    ev.preventDefault(); t.scrollIntoView({ behavior: 'smooth', block: 'start' }); cleanUrl();
  });
  let lastW = innerWidth, t = 0;
  addEventListener('resize', () => { if (Math.abs(innerWidth - lastW) < 8) return; lastW = innerWidth; clearTimeout(t); t = setTimeout(drawAll, 150); });
  matchMedia('(prefers-color-scheme: light)').addEventListener?.('change', () => { drawAll(); drawTail(); });
})();
